window.__Q=window.__Q||{};window.__Q["clin/2/A1"]=[{"q":"接受肝淋巴管的淋巴结的是","o":["肠系膜上淋巴结","腰淋巴结","腹腔淋巴结","膈上淋巴结","幽门淋巴结"],"a":2,"e":"肝的深、浅淋巴管多经肝淋巴结中继，其输出淋巴管最终注入腹腔干周围的腹腔淋巴结；膈上淋巴结只收纳肝膈面的部分浅淋巴，属另一条引流途径。"},{"q":"疑核属于","o":["一般躯体运动核","一般躯体感觉核","特殊内脏感觉核","特殊躯体感觉核","特殊内脏运动核"],"a":4,"e":"疑核位于延髓网状结构内，发出特殊内脏运动纤维支配由鳃弓衍化的咽喉肌，属特殊内脏运动核柱；一般躯体运动核仅为动眼、滑车、展和舌下神经核。"},{"q":"眼动脉的分支包括","o":["视网膜中央动脉","面动脉","上颌动脉","内眦动脉","下颌动脉"],"a":0,"e":"视网膜中央动脉发自眼动脉，是供应视网膜内层的唯一动脉，属终动脉；面动脉和上颌动脉均为颈外动脉分支，与眼动脉无隶属关系。"},{"q":"通过圆孔的结构是","o":["眶上神经","眼神经","上颌神经","上颌动脉","脑膜中动脉"],"a":2,"e":"上颌神经穿圆孔出颅进入翼腭窝，再经眶下裂入眶续为眶下神经；眼神经与眶上神经经眶上裂入眶，脑膜中动脉穿棘孔入颅。"},{"q":"接受来自下丘臂的听觉传导纤维的核团是","o":["腹前核","内侧膝状体","腹后内侧核","腹外侧核","外侧膝状体"],"a":1,"e":"下丘臂连于内侧膝状体，把下丘的听觉冲动传向丘脑；上丘臂连于外侧膝状体，与视觉通路相关，二者不可混淆。"},{"q":"关于十二指肠的描述，正确的是","o":["全长约20cm","属于腹膜内位器官","肝胰壶腹开口于十二指肠水平部","分为上部、降部、水平部三部分","紧贴腹后壁"],"a":4,"e":"十二指肠除始、末两端被腹膜包裹外，大部分为腹膜外位器官，被腹膜固定于腹后壁；其全长20～25cm，分四部，肝胰壶腹开口于降部。"},{"q":"以下关于甲状腺鞘的描述，正确的是","o":["又称纤维囊","也称真被膜","由气管前筋膜形成","属于甲状腺被膜的内层","为甲状腺的外膜"],"a":2,"e":"甲状腺鞘即假被膜，由气管前筋膜包裹甲状腺形成；甲状腺外膜为真被膜即纤维囊，两者之间的囊鞘间隙内有甲状旁腺。"},{"q":"关于心尖的描述，正确的是","o":["朝向右前下方","由右心室构成","平对左侧第5肋间隙","前室间支与后室间支吻合处","活体不易触摸到其搏动"],"a":2,"e":"心尖由左心室构成，朝向左前下方，在左侧第5肋间隙锁骨中线内侧1～2cm处可触及心尖搏动；心底朝右后上方，主要由左心房构成。"},{"q":"薄束核和楔束核发出的纤维构成","o":["薄束和楔束","脊髓丘脑束","三叉丘系","内侧丘系","外侧丘系"],"a":3,"e":"薄束核与楔束核发出二级纤维经内弓状纤维越中线交叉，形成内侧丘系交叉，交叉后上行构成内侧丘系，止于丘脑腹后外侧核。"},{"q":"可作为划分上、下纵隔的标志是","o":["第4胸椎体下缘","胸骨体","胸骨柄","心包","肺门"],"a":0,"e":"纵隔以胸骨角至第4胸椎体下缘的平面分为上、下纵隔，该平面相当于主动脉弓下缘和左、右主支气管分叉处。"},{"q":"下列有关肝下间隙，描述正确的是","o":["借镰状韧带分为左、右肝下间隙","右肝下间隙借小网膜分为右肝下前间隙和右肝下后间隙","左肝下前间隙即小腹膜腔","右肝下后间隙即肝肾隐窝","属于结肠下区"],"a":0,"e":"肝下间隙指肝脏面腹膜与横结肠及其系膜之间的间隙，借镰状韧带和肝圆韧带分为左、右肝下间隙；左肝下间隙再借小网膜分为前、后两隙，其后方即网膜囊。"},{"q":"在锁骨中线处胸膜下界相交于","o":["第6肋","第7肋","第8肋","第9肋","第10肋"],"a":2,"e":"胸膜下界在锁骨中线与第8肋相交，在腋中线与第10肋相交，在肩胛线与第11肋相交；同一部位肺下界较胸膜下界高约两个肋。"},{"q":"颈内静脉伴行的血管是哪一条","o":["颈外静脉","上颌静脉","颈外动脉","下颌后静脉","颈总动脉"],"a":4,"e":"颈内静脉在颈动脉鞘内沿颈内动脉和颈总动脉外侧下行，至胸锁关节后方与锁骨下静脉合成头臂静脉；颈外静脉为浅静脉，行于胸锁乳突肌表面。"},{"q":"参加肩关节旋外的肌是","o":["胸大肌","小圆肌","背阔肌","大圆肌","肩胛下肌"],"a":1,"e":"小圆肌起自肩胛骨外侧缘背面，止于肱骨大结节下部，收缩使肩关节旋外；胸大肌、背阔肌和肩胛下肌的作用均为旋内。"},{"q":"关于指浅屈肌的叙述，错误的是","o":["为前臂后群浅层肌","肌束向下移行为4条肌腱","肌腱经腕管入手掌","止于内侧2～5指中节指骨体两侧","可屈腕关节和肘关节"],"a":0,"e":"指浅屈肌属前臂前群浅层肌，起自肱骨内上髁及尺、桡骨前面，肌腱经腕管入手掌，止于第2～5指中节指骨体两侧，可屈指、屈腕和屈肘。"},{"q":"关于交感神经和副交感神经的区别，错误的是","o":["低级中枢的部位不同","都是管理内脏运动","周围部神经节的位置不同","节前神经元与节后神经元的比例不同","副交感分布范围更广"],"a":4,"e":"交感节前神经元与多个节后神经元形成突触，故分布范围广、作用弥散；副交感节前与节后神经元比例小，作用较局限，二者低级中枢部位和节的位置亦不同。"},{"q":"竖脊肌的形态结构特征包括","o":["是背部强大的屈肌","位于背部的浅层","收缩时使脊柱后伸和仰头","为全身最大的阔肌","仅连于相邻椎骨之间"],"a":2,"e":"竖脊肌位于背肌深层，由髂肋肌、最长肌和棘肌组成，两侧同时收缩使脊柱后伸并仰头；一侧收缩使脊柱向同侧屈，对维持直立起重要作用。"},{"q":"不穿经梨状肌下孔的神经","o":["坐骨神经","阴部神经","臀下神经","股后皮神经","闭孔神经"],"a":4,"e":"坐骨神经、臀下神经、阴部神经和股后皮神经均经梨状肌下孔出盆腔；闭孔神经沿盆腔侧壁前行穿闭孔至股内侧，不经梨状肌下孔。"},{"q":"关于闭孔神经的叙述，错误的是","o":["自腰丛发出","沿盆腔侧壁前行穿闭孔","肌支支配股内侧肌群","皮支分布于大腿内侧面皮肤","没有分支到髋关节"],"a":4,"e":"闭孔神经自腰丛发出，经盆腔侧壁穿闭孔，肌支支配股内侧群，皮支分布于大腿内侧面皮肤；该神经尚有细小分支分布于髋关节和膝关节。"},{"q":"远侧列的腕骨包括","o":["手舟骨","月骨","三角骨","大多角骨","豌豆骨"],"a":3,"e":"远侧列腕骨由桡侧向尺侧依次为大多角骨、小多角骨、头状骨和钩骨；手舟骨、月骨、三角骨和豌豆骨属近侧列。"},{"q":"属于内生殖器的结构","o":["阴阜","前庭球","前庭大腺","小阴唇","阴蒂"],"a":2,"e":"女性内生殖器由卵巢、输卵管、子宫、阴道和前庭大腺组成，前庭大腺属附属腺；阴阜、小阴唇、阴蒂和前庭球均属女阴即外生殖器。"},{"q":"接受内侧丘系纤维的丘脑神经核是","o":["腹后内侧核","腹后外侧核","腹外侧核","腹前核","内侧膝状体"],"a":1,"e":"腹后外侧核接受内侧丘系和脊髓丘系纤维，发出丘脑中央辐射经内囊后肢投射至中央后回；腹后内侧核接受三叉丘系和味觉纤维。"},{"q":"肋的形态结构特征是","o":["第1～8肋前端连于胸骨称为真肋","第9～10肋软骨连成肋弓","外面近下缘处有肋沟","分为真肋和假肋","肋属扁骨"],"a":4,"e":"肋骨属扁骨，分体及前、后两端，后端肋头与胸椎肋凹相关节；第1～7肋为真肋，第8～10肋软骨依次连成肋弓，肋沟位于肋骨内面下缘。"},{"q":"对副神经的叙述错误的是","o":["在橄榄后沟下部连于延髓","经颈静脉孔出颅","脑根加入迷走神经","脊髓根支配斜方肌和胸锁乳突肌","为躯体运动神经"],"a":4,"e":"副神经由颅根和脊髓根合成，经颈静脉孔出颅，脊髓根支配胸锁乳突肌和斜方肌；其纤维支配鳃弓衍化的骨骼肌，属特殊内脏运动纤维而非一般躯体运动纤维。"},{"q":"胸核发出的纤维组成","o":["同侧的脊髓小脑前束","对侧的脊髓小脑前束","同侧的脊髓小脑后束","对侧的脊髓小脑后束","对侧的小脑下脚"],"a":2,"e":"胸核位于胸髓和上腰髓，发出的二级纤维在同侧侧索组成脊髓小脑后束，经小脑下脚入小脑皮质；脊髓小脑前束主要起自腰骶膨大，大部分纤维交叉。"},{"q":"两侧胸膜腔","o":["借呼吸道相通","向内侧与心包横窦相通","向下和腹膜腔相通","开口于肺门","各自形成密闭间隙"],"a":4,"e":"胸膜腔是脏、壁两层胸膜间密闭、狭窄并呈负压的腔隙，左右各一，互不相通，也不与呼吸道、心包腔或腹膜腔相通。"},{"q":"在足骨，跟骨前方的跗骨是","o":["足舟骨","骰骨","外侧楔骨","内侧楔骨","中间楔骨"],"a":1,"e":"跟骨前方与骰骨相接，骰骨属跗骨前列；足舟骨位于距骨前方属中列，三块楔骨位于足舟骨前方。"},{"q":"眼球屈光装置的主要结构","o":["角膜","房水","晶状体","玻璃体","视网膜"],"a":2,"e":"晶状体是眼屈光系统的主要装置，其曲度可随所视物体远近改变，视近物时睫状肌收缩、睫状小带松弛使晶状体凸度增大。"},{"q":"动眼神经穿经","o":["视神经管","眶上裂","眶下裂","眶上孔","眶下孔"],"a":1,"e":"动眼神经自中脑脚间窝出脑，经海绵窦外侧壁上部穿眶上裂入眶，分上、下两支支配眼外肌；视神经经视神经管入眶，上颌神经经圆孔出颅。"},{"q":"下列哪项属于实质性的内脏器官","o":["甲状腺","脾","肾上腺","肝","子宫"],"a":3,"e":"肝内部无特定空腔，表面包以被膜，实质被分割成肝小叶，属内脏学中的实质性器官；子宫为中空器官，甲状腺、肾上腺和脾不列入内脏器官。"},{"q":"下消化道不包括","o":["十二指肠","空肠","回肠","直肠","盲肠"],"a":0,"e":"临床以十二指肠为界，空肠以下至肛管称下消化道，故十二指肠属上消化道；下消化道包括空肠、回肠、盲肠、结肠、直肠和肛管。"},{"q":"关于腓总神经及其分支的叙述，错误的是","o":["腓深神经支配小腿前群肌","腓深神经支配小腿外侧群肌","腓浅神经分布于小腿外侧","腓骨颈处的骨折易导致腓总神经损伤","腓深神经终支分布于足背内侧区"],"a":1,"e":"腓深神经支配小腿前群肌和足背肌；小腿外侧群肌由腓浅神经支配，该神经还分布于小腿外侧、足背和趾背皮肤。"},{"q":"关于副神经的叙述，错误的是","o":["由颅根和脊髓根合成","经枕骨大孔出颅","颅根加入迷走神经","脊髓根支配胸锁乳突肌和斜方肌","为运动性脑神经"],"a":1,"e":"副神经脊髓根在椎管内上行，经枕骨大孔入颅，与颅根合成后共同经颈静脉孔出颅；颅根加入迷走神经，脊髓根支配胸锁乳突肌和斜方肌。"},{"q":"分上、下面和内、外缘的肋骨是","o":["第1肋骨","第2肋骨","第8肋骨","第11肋骨","第12肋骨"],"a":0,"e":"第1肋骨扁宽而短，分上、下面和内、外缘，无肋角和肋沟，内缘前份有前斜角肌结节；其余肋骨均分前、后两端和体，并具有肋角和肋沟。"},{"q":"可内收、内旋和前屈肩关节的肌是","o":["胸大肌","背阔肌","冈上肌","小圆肌","三角肌"],"a":0,"e":"胸大肌起自锁骨内侧、胸骨和第1～6肋软骨，止于肱骨大结节嵴，收缩使肩关节内收、旋内和前屈；背阔肌主要为后伸、内收和旋内。"},{"q":"颈动脉窦的描述，何者正确","o":["可感受血液中氧分压的变化","位于颈外动脉的起始处","为化学感受器","为压力感受器","可感受血液中二氧化碳分压的变化"],"a":3,"e":"颈动脉窦是颈总动脉末端与颈内动脉起始处的膨大，窦壁外膜内富含游离神经末梢，属压力感受器，血压升高时反射性引起心率减慢、血压下降。"},{"q":"阴道前庭","o":["两侧大阴唇之间的裂隙","又称为阴道穹","两侧小阴唇之间的裂隙","尿道外口在后方，阴道口在前方","前庭球位于阴道前庭内"],"a":2,"e":"阴道前庭是两侧小阴唇之间的菱形区，前部有尿道外口，后部有阴道口；前庭大腺导管开口于此，前庭球位于大阴唇深面。"},{"q":"穿经四边孔的动脉是","o":["胸肩峰动脉","旋肩胛动脉","肩胛下动脉","旋肱前动脉","旋肱后动脉"],"a":4,"e":"旋肱后动脉伴腋神经穿四边孔，绕肱骨外科颈分布于三角肌和肩关节；旋肩胛动脉穿三边孔至冈下窝，二者经不同孔道。"},{"q":"对舌下神经描述正确的是","o":["伴同名动静脉经舌下神经管出颅","来自对侧的舌下神经核","支配舌肌","经延髓脑桥沟出脑","为舌的感觉神经"],"a":2,"e":"舌下神经为运动性神经，起自延髓舌下神经核，经舌下神经管出颅，支配舌内肌和大部分舌外肌；一侧损伤时伸舌舌尖偏向患侧并伴舌肌萎缩。"},{"q":"属于颈外动脉分支的是","o":["甲状腺上动脉","椎动脉","脑膜中动脉","胸廓内动脉","甲状腺下动脉"],"a":0,"e":"甲状腺上动脉自颈外动脉起始部发出，分布于甲状腺和喉；椎动脉和胸廓内动脉为锁骨下动脉分支，甲状腺下动脉发自甲状颈干。"},{"q":"参与视觉、听觉姿势反射活动的纤维束","o":["网状脊髓束","顶盖脊髓束","内侧纵束","前庭脊髓束","红核脊髓束"],"a":1,"e":"上丘深层发出纤维越过中线形成被盖背侧交叉，下行构成顶盖脊髓束，止于颈髓中间带和前角内侧核，完成头颈部对视觉、听觉刺激的姿势反射。"},{"q":"经过内囊膝的纤维束是","o":["丘脑中央辐射","视辐射","皮质脊髓前束","皮质脊髓侧束","皮质核束"],"a":4,"e":"内囊膝部通过皮质核束，该束起自中央前回下部，下行终止于脑干一般躯体运动核和特殊内脏运动核；内囊后肢通过皮质脊髓束和丘脑中央辐射。"},{"q":"关于听觉性语言中枢的叙述，错误的是","o":["位于角回","损伤后患者不理解别人讲话的意思","损伤后患者不理解自己讲的话","损伤后患者不能正确回答问题和正常说话","损伤后患者能听到别人讲的话"],"a":0,"e":"听觉性语言中枢位于颞上回后部，损伤后患者能听到声音但不理解语意，称感觉性失语症；角回为视觉性语言区即阅读中枢，损伤致失读症。"},{"q":"注入右淋巴导管的淋巴干是","o":["肠干","右腰干","左支气管纵隔干","左颈干","右锁骨下干"],"a":4,"e":"右淋巴导管由右颈干、右锁骨下干和右支气管纵隔干汇合而成，注入右静脉角；左颈干、左支气管纵隔干和肠干均汇入胸导管。"},{"q":"腓浅神经损伤的表现为","o":["足外翻","足内翻","足背屈","足下垂","钩状足"],"a":1,"e":"腓浅神经支配腓骨长、短肌，司足外翻；损伤后足外翻肌瘫痪，内翻肌失去拮抗而表现为足内翻，并伴小腿外侧和足背感觉障碍。"},{"q":"关于形成静脉角的两条静脉是","o":["左、右头臂静脉","颈内静脉和颈外静脉","颈外静脉和锁骨下静脉","锁骨下静脉和颈内静脉","头臂静脉和锁骨下静脉"],"a":3,"e":"颈内静脉与锁骨下静脉在胸锁关节后方汇合，汇合处称静脉角，是胸导管和右淋巴导管的注入部位；头臂静脉由该二静脉汇合而成。"},{"q":"一侧舌下神经损伤可导致","o":["伸舌时舌尖偏向健侧","舌不能前伸","舌的感觉丧失","无舌肌萎缩","伸舌时舌尖偏向患侧"],"a":4,"e":"舌下神经支配同侧舌肌，一侧损伤后患侧颏舌肌瘫痪，伸舌时健侧舌肌将舌尖推向患侧，日久患侧舌肌萎缩。"},{"q":"关于腋神经正确的是","o":["从臂丛后束发出，穿过三边孔到达肩胛区","从臂丛外侧束发出，穿过四边孔到达肩胛区","从臂丛后束发出，穿过四边孔到达肩胛区","不发出分支到小圆肌","支配三角肌和大圆肌"],"a":2,"e":"腋神经自臂丛后束发出，与旋肱后血管伴行穿四边孔，绕肱骨外科颈至三角肌深面，支配三角肌和小圆肌，损伤后三角肌瘫痪出现方肩畸形。"},{"q":"分布于结肠左曲以上的消化管的副交感神经是","o":["内脏大神经","迷走神经","内脏小神经","盆内脏神经","腰内脏神经"],"a":1,"e":"迷走神经的副交感纤维随腹腔支分布至结肠左曲以上的消化管及肝、胰、脾、肾；结肠左曲以下由盆内脏神经即骶副交感纤维支配。"},{"q":"脊柱的组成不包括","o":["24块椎骨","骶骨","尾骨","椎间盘","骶髂关节"],"a":4,"e":"脊柱由24块椎骨、1块骶骨、1块尾骨及椎间盘、韧带和关节连结而成；骶髂关节是骶骨与髂骨间的关节，属下肢带骨连结。"},{"q":"腹壁上动脉起自下列哪条动脉","o":["胸廓内动脉","肩胛下动脉","肋颈干","甲状颈干","锁骨下动脉"],"a":0,"e":"胸廓内动脉行至第6肋间隙处分出腹壁上动脉和肌膈动脉，腹壁上动脉穿膈入腹直肌鞘，在腹直肌深面下行与腹壁下动脉吻合。"},{"q":"下列哪些动脉为锁骨下动脉的直接分支","o":["椎动脉、胸外侧动脉、胸廓内动脉、甲状颈干","甲状颈干、胸廓内动脉、甲状腺下动脉","椎动脉、甲状颈干、肋颈干、胸廓内动脉","甲状颈干、肋颈干、椎动脉、肩胛下动脉","胸廓内动脉、甲状颈干、上颌动脉、椎动脉"],"a":2,"e":"锁骨下动脉的直接分支为椎动脉、胸廓内动脉、甲状颈干和肋颈干；甲状腺下动脉发自甲状颈干，胸外侧动脉和肩胛下动脉属腋动脉分支。"},{"q":"肾蒂内各结构的排列，自上而下依次是","o":["肾静脉、肾动脉、肾盂","肾静脉、肾盂、肾动脉","肾盂、肾静脉、肾动脉","肾盂、肾动脉、肾静脉","肾动脉、肾静脉、肾盂"],"a":4,"e":"肾蒂内结构自上而下依次为肾动脉、肾静脉和肾盂，自前向后则为肾静脉、肾动脉和肾盂末端，理解时须注意两个方位。"},{"q":"齿状线在临床上的实用意义是","o":["齿状线上有神经反射弧","齿状线上、下血液供应、神经及淋巴引流各异","齿状线上直肠易受感染","齿状线下肛管狭窄易受感染","齿状线下是肛门外括约肌所在部位"],"a":1,"e":"齿状线以上被覆黏膜，受内脏神经支配，静脉经直肠上静脉入肝门静脉，淋巴入肠系膜下淋巴结；以下被覆皮肤，受躯体神经支配，静脉入髂内静脉，淋巴入腹股沟浅淋巴结。"},{"q":"关于心纤维性支架正确的是","o":["由疏松结缔组织构成","仅由4个瓣膜环组成","心肌纤维和心瓣膜的附着处","左纤维三角又称为中心纤维体","内有左、右束支通过"],"a":2,"e":"心纤维性支架又称心纤维骨骼，由致密结缔组织构成，位于房室口和动脉口周围，为心肌纤维和心瓣膜提供附着，中心纤维体由右纤维三角构成。"},{"q":"抗利尿激素和催产素是由以下哪个结构产生的","o":["腺垂体","神经垂体","垂体前叶","视上核和室旁核","垂体后叶"],"a":3,"e":"抗利尿激素和缩宫素由下丘脑视上核、室旁核的神经内分泌细胞合成，经视上垂体束运至神经垂体贮存并释放；神经垂体本身不合成激素。"},{"q":"关于松果体的叙述，错误的是","o":["位于背侧丘脑的后上方","呈淡红色的椭圆形小体","儿童期较发达","促进性成熟","成年后钙化"],"a":4,"e":"官方答案为【成年后钙化】，但依据教材，正确答案为【促进性成熟】。松果体分泌褪黑素，抑制性腺发育，并非促进性成熟；教材载16岁以后松果体逐渐钙化，可作颅内定位标志。"},{"q":"上丘脑不包括","o":["缰三角","缰连合","丘脑髓纹","前连合","后连合"],"a":3,"e":"上丘脑包括松果体、缰三角、缰连合、丘脑髓纹和后连合；前连合属大脑的连合纤维，连接两侧颞叶和嗅球，不属上丘脑。"},{"q":"与尺骨滑车切迹组成肱尺关节的结构是","o":["肱骨滑车","桡骨头关节凹","尺骨桡切迹","桡骨尺切迹","桡骨环状关节面"],"a":0,"e":"肱尺关节由肱骨滑车与尺骨滑车切迹构成，是肘关节的主体，可作屈伸运动；肱桡关节由肱骨小头与桡骨关节凹构成。"},{"q":"属于下丘脑的结构是","o":["丘脑枕","松果体","髓纹","灰结节","内、外侧膝状体"],"a":3,"e":"下丘脑位于下丘脑沟腹侧，包括视交叉、灰结节、漏斗、垂体和乳头体；丘脑枕属背侧丘脑，内、外侧膝状体属后丘脑。"},{"q":"分布于腹腔脏器的交感神经节后纤维发自","o":["胸5～12交感干神经节","腰交感干神经节","腰、骶交感干神经节","椎前神经节","胸1～5交感干神经节"],"a":3,"e":"腹腔脏器的交感节后纤维多起自腹腔神经节、主动脉肾神经节及肠系膜上、下神经节等椎前神经节；椎旁神经节的节后纤维主要随脊神经分布。"},{"q":"直接注入右心房的静脉是","o":["心大静脉","心中静脉","心小静脉","心最小静脉","心前静脉"],"a":4,"e":"心前静脉起于右心室前壁，越过冠状沟直接注入右心房；心大、中、小静脉均汇入冠状窦，心最小静脉直接开口于心腔。"},{"q":"下述关于胸骨旁淋巴结的描述，正确的是","o":["沿胸廓内血管排列","输出淋巴管注入锁骨下干","引流乳房上部的淋巴","位于胸膜腔内","与胸肌淋巴结联系密切"],"a":0,"e":"胸骨旁淋巴结沿胸廓内血管排列，引流胸腹前壁和乳房内侧部淋巴，输出管参与合成支气管纵隔干；它位于胸骨两旁，不在胸膜腔内。"},{"q":"在肩关节外展中最重要的一对肌是","o":["三角肌和肩胛下肌","三角肌和冈上肌","冈上肌和肩胛下肌","大圆肌和肩胛下肌","三角肌和大圆肌"],"a":1,"e":"三角肌中部纤维使肩关节外展，冈上肌启动外展并协助三角肌，二者为肩外展最重要的一对肌；冈下肌和小圆肌主司旋外。"},{"q":"一侧视神经受损，光照健侧瞳孔时，会出现","o":["患侧瞳孔直接对光反射消失，间接对光反射存在","患侧瞳孔直接和间接对光反射均消失","两眼瞳孔对光反射均消失","健侧瞳孔直接对光反射存在，间接对光反射消失","健侧瞳孔间接对光反射存在，直接对光反射消失"],"a":0,"e":"光照患侧眼时传入中断，两眼均无反应；光照健侧眼时冲动经健侧视神经上传并交叉至两侧动眼神经副核，故患眼间接对光反射存在。"},{"q":"发出分支分布于眼球角膜的神经","o":["视神经","动眼神经","展神经","眼神经","鼻睫神经"],"a":3,"e":"角膜的感觉由眼神经的鼻睫神经发出的睫状长神经传导，属一般躯体感觉；视神经司视觉，不传导角膜痛觉。"},{"q":"集合淋巴滤泡多存在于","o":["空肠","回肠","结肠","盲肠","直肠"],"a":1,"e":"集合淋巴滤泡又称Peyer斑，有20～30个，多位于回肠下部对肠系膜缘的黏膜内；孤立淋巴滤泡分散于空肠和回肠。"},{"q":"有关心脏正确的说法是","o":["心前面两心耳之间为主动脉根","右心房构成心右缘","居于胸腔的正中","位于两侧肺之间的前纵隔内","冠状沟将心脏分为左、右半"],"a":1,"e":"心右缘由右心房构成，左缘绝大部分由左心室构成；心位于中纵隔内，冠状沟是心房与心室在心表面的分界。"},{"q":"左侧精索静脉曲张的原因之一是","o":["左侧睾丸静脉以直角注入左髂外静脉","左侧睾丸静脉以直角注入左髂内静脉","左侧睾丸静脉以直角注入左髂总静脉","左侧睾丸静脉以直角注入下腔静脉","左侧睾丸静脉以直角注入左肾静脉"],"a":4,"e":"左睾丸静脉以直角注入左肾静脉，行程长且回流阻力大；右侧以锐角注入下腔静脉，故精索静脉曲张多见于左侧。"},{"q":"支配腮腺的副交感纤维来自","o":["耳神经节","迷走神经","面神经","上泌涎核","鼓索"],"a":0,"e":"支配腮腺的副交感节前纤维起自下泌涎核，经舌咽神经的岩小神经至耳神经节换元，节后纤维经耳颞神经入腮腺。"},{"q":"红核位于","o":["间脑","中脑","脑桥","延髓","小脑"],"a":1,"e":"红核位于中脑上丘水平的被盖中央，横断面呈圆形，发出纤维交叉后组成红核脊髓束；黑质亦位于中脑，二者均属锥体外系核团。"},{"q":"具有神经内分泌功能的下丘脑核团是","o":["乳头体核","视上核","下丘脑后核","腹内侧核","背内侧核"],"a":1,"e":"视上核和室旁核的神经元能合成抗利尿激素和缩宫素，属神经内分泌核团；乳头体核、腹内侧核和背内侧核主要参与内脏活动和摄食调节。"},{"q":"关于上矢状窦的说法错误的是","o":["位于大脑镰的上缘","前方止于盲孔","后方注入窦汇","蛛网膜粒突入此窦","不属于硬脑膜窦"],"a":4,"e":"上矢状窦位于大脑镰上缘，起自盲孔，向后注入窦汇，蛛网膜粒突入窦内；它属硬脑膜窦，窦壁无平滑肌，损伤后出血不易止住。"},{"q":"患者，头痛、恶心、呕吐，以及视力一过性朦胧。检眼镜观察发现视神经盘充血、扩大、隆起明显（≥3D），边缘模糊，甚至累及附近视网膜，条状出血和渗出物，视网膜静脉怒张弯曲，黄斑部可见不完全性的星芒状渗出物。头颅CT检查患者颅内脑脊液增多，诊断为颅内高压。其视力及视神经盘症状应该是颅内高压引起的","o":["视神经损伤","眼外肌受损","动眼神经损伤","滑车神经损伤","视神经盘水肿"],"a":4,"e":"颅内压增高时压力经视神经周围的蛛网膜下隙传至视神经，使视神经盘充血、隆起、边缘模糊，称视神经盘水肿。"},{"q":"骨间掌侧肌的作用是","o":["内收第2、3、4指","内收第2、4、5指","外展第2、3、4指","外展第2、4、5指","外展第3、4、5指"],"a":1,"e":"骨间掌侧肌起自第2掌骨内侧和第4、5掌骨外侧，止于第2、4、5指指背腱膜，收缩使第2、4、5指内收并屈掌指关节；骨间背侧肌外展第2、4指。"},{"q":"连于甲状软骨上缘与舌骨之间的结构称为","o":["环甲正中韧带","前庭韧带","方形膜","环状软骨气管韧带","甲状舌骨膜"],"a":4,"e":"甲状舌骨膜连于甲状软骨上缘与舌骨之间，中部增厚为甲状舌骨正中韧带，两侧为甲状舌骨外侧韧带，其内常含麦粒软骨。"},{"q":"在骨连结，纤维软骨结合包括","o":["耻骨连合","前臂骨间膜","骺软骨","骶椎合成骶骨","髂骨、坐骨和耻骨合成髋骨"],"a":0,"e":"耻骨连合由两侧耻骨联合面的纤维软骨连结构成，属软骨结合；前臂骨间膜为纤维连结，骶椎融合成骶骨及髋骨三部分融合均属骨性结合。"},{"q":"关于附睾的描述，不正确的是","o":["附着在睾丸的上端及后缘","可分为头、体、尾三部","附睾管也可产生精子","可分泌液体促进精子成熟","形态为新月形"],"a":2,"e":"附睾呈新月形，贴于睾丸上端和后缘，分头、体、尾三部；其功能为暂时储存精子并分泌附睾液促进精子成熟，精子由睾丸生精小管产生。"},{"q":"甲状腺次全切除手术后出现手足搐搦，可能是","o":["甲状腺素分泌不足","甲状旁腺功能亢进","切除了甲状旁腺","甲状腺功能低下","损伤甲状腺神经"],"a":2,"e":"甲状旁腺常位于甲状腺侧叶后缘与被膜之间，甲状腺次全切除时易被误切，致甲状旁腺激素不足、血钙降低，出现手足搐搦。"},{"q":"肾上腺的描述中，正确的是","o":["腹膜内位器官","腹膜间位器官","腹膜后位器官","不是内分泌腺","是混合腺，既是内分泌腺又是外分泌腺"],"a":2,"e":"肾上腺位于肾的上方，仅前面被腹膜覆盖，属腹膜外位器官即腹膜后位器官；它为内分泌腺，无外分泌部。"},{"q":"既可以屈髋关节又可以屈膝关节，并使膝关节旋内的肌是","o":["缝匠肌","股四头肌","大收肌","阔筋膜张肌","股薄肌"],"a":0,"e":"缝匠肌起自髂前上棘，止于胫骨上端内侧面，可屈髋、屈膝并使已屈的膝关节旋内，是全身最长的肌；股四头肌只屈髋伸膝。"},{"q":"躯干骨不包括","o":["椎骨","肋","尾骨","骶骨","肩胛骨"],"a":4,"e":"躯干骨包括24块椎骨、1块骶骨、1块尾骨、胸骨和12对肋；肩胛骨属上肢带骨，参与肩关节构成。"},{"q":"动眼神经损伤可使患者出现","o":["患侧眼内斜视","患侧眼内斜视和瞳孔缩小","对侧眼外斜视","患侧眼外斜视和瞳孔散大","对侧偏盲"],"a":3,"e":"动眼神经支配除外直肌和上斜肌以外的眼外肌及瞳孔括约肌，损伤后内直肌等瘫痪致患眼外斜视，瞳孔括约肌失能致瞳孔散大。"},{"q":"属于头颈部深静脉的是","o":["颈外静脉","颈前静脉","颈内静脉","面静脉","颞浅静脉"],"a":2,"e":"头颈部静脉分浅、深两组，颈内静脉与锁骨下静脉属深静脉；面静脉、颞浅静脉、颈前静脉和颈外静脉均属浅静脉。"},{"q":"关于直肠的描述正确的是","o":["有结肠带","穿盆膈接续肛管","上段为腹膜内位","中段为腹膜间位","没有弯曲"],"a":1,"e":"直肠在第3骶椎前方起自乙状结肠，沿骶、尾骨前面下行，穿盆膈移行为肛管，矢状面上有骶曲和会阴曲；直肠无结肠带。"},{"q":"管理角膜感觉的神经","o":["视神经","面神经","眼神经","动眼神经","上颌神经"],"a":2,"e":"角膜的感觉纤维来自眼神经的鼻睫神经所发睫状长神经，属一般躯体感觉；视神经只传导视觉冲动。"},{"q":"防止子宫脱垂的韧带","o":["子宫骶韧带","子宫圆韧带","子宫主韧带","子宫阔韧带","骨盆漏斗韧带"],"a":2,"e":"子宫主韧带位于阔韧带基部，由结缔组织和平滑肌构成，自子宫颈两侧缘延至盆侧壁，是维持子宫颈位置、防止子宫脱垂的重要结构。"},{"q":"阻塞后引起左心室侧壁梗死","o":["前室间支","后室间支","左心室后支","旋支","动脉圆锥支"],"a":3,"e":"旋支分布于左心房、左心室侧壁及左心室后壁一部分，其阻塞引起左心室侧壁心肌梗死；前室间支供应左心室前壁和室间隔前2/3。"},{"q":"关于膀胱的叙述，错误的是","o":["膀胱三角是结核、肿瘤和炎症的好发部位","分为尖、体、底和颈四部分","膀胱三角位于尿道内口与输尿管口之间","正常成年人膀胱容量为200～400ml","膀胱的最下部为膀胱颈"],"a":3,"e":"正常成人膀胱容量平均350～500ml，超过500ml可产生疼痛；膀胱空虚时呈三棱锥体形，分尖、体、底、颈四部，膀胱三角位于两输尿管口与尿道内口之间。"},{"q":"降肋助呼气的肌是","o":["前、中、后斜角肌","肋间内肌","肋间外肌","前锯肌","胸小肌"],"a":1,"e":"肋间内肌肌束斜向前上，起自下位肋骨上缘止于上位肋骨下缘，收缩时降肋助呼气；肋间外肌肌束斜向前下，提肋助吸气。"},{"q":"关于心包的叙述，错误的是","o":["分为纤维性心包和浆膜性心包","纤维性心包与浆膜性心包相移行为心包腔","浆膜性心包贴于纤维性心包内面","浆膜性心包覆盖于心表面","心包位于纵隔内"],"a":1,"e":"浆膜心包的脏、壁两层在出入心的大血管根部互相移行，两层间的潜在腔隙即心包腔；纤维心包只与浆膜心包壁层相贴，不参与围成心包腔。"},{"q":"一患者左侧大脑Broca区损伤，可能会发生","o":["无法阅读原先认识的字，不理解文字符号的意义，因Broca区是视觉性语言区","虽能发音，无法说出有意义的语言，因Broca区是运动性语言区","手的运动存在，但无法完成写字、绘图等精细动作，因Broca区是书写区","尽管视觉正常，对原先认识的字不能阅读，因Broca区是视觉性语言区","能听见别人讲话，但不理解讲话的内容，因Broca区是听觉语言区"],"a":1,"e":"Broca区即运动性语言中枢，位于额下回后1/3，损伤后患者虽能发音，却不能说出有意义的语言，称运动性失语症。"},{"q":"胃的供血动脉中起自肝固有动脉的是","o":["胃左动脉","胃右动脉","胃后动脉","胃短动脉","胃网膜右动脉"],"a":1,"e":"胃右动脉发自肝固有动脉，沿胃小弯左行与胃左动脉吻合；胃左动脉直接起自腹腔干，胃网膜右动脉发自胃十二指肠动脉。"},{"q":"子宫峡位于","o":["子宫与输卵管之间","子宫体与子宫颈之间","子宫颈阴道上部与子宫颈阴道部之间","子宫颈与阴道之间","子宫体与子宫颈阴道部之间"],"a":1,"e":"子宫峡位于子宫体与子宫颈相接处，非孕时长约1cm，妊娠期逐渐伸展成为子宫下段，是剖宫产切口的常用部位。"},{"q":"锥体交叉","o":["位于脑桥腹侧","位于中脑的大脚底","感觉传导束的交叉处","皮质脊髓束的交叉纤维","锥体外系纤维的交叉处"],"a":3,"e":"锥体交叉位于延髓下端，由皮质脊髓束大部分纤维越中线交叉形成；交叉后的纤维在对侧侧索下行称皮质脊髓侧束，属运动传导束。"},{"q":"关于阴茎的描述何者正确","o":["分为头、体、颈三部","分为头、体、颈、根四部","分为头、体、根三部","由一个阴茎海绵体构成","由两个尿道海绵体构成"],"a":2,"e":"阴茎分为头、体和根三部分，由两个阴茎海绵体和一个尿道海绵体构成；尿道海绵体前端膨大为阴茎头，尖端有尿道外口。"},{"q":"穿过茎乳孔的脑神经","o":["动眼神经","面神经","展神经","舌下神经","副神经"],"a":1,"e":"面神经经内耳门入面神经管，最后由茎乳孔出颅，再进入腮腺分支；舌下神经经舌下神经管出颅，舌咽、迷走和副神经经颈静脉孔。"},{"q":"在腕骨，从桡侧至尺侧，远侧列的腕骨是","o":["钩骨、小多角骨、头状骨、大多角骨","头状骨、小多角骨、大多角骨、钩骨","小多角骨、大多角骨、头状骨、钩骨","大多角骨、小多角骨、头状骨、钩骨","大多角骨、小多角骨、三角骨、钩骨"],"a":3,"e":"远侧列腕骨由桡侧向尺侧依次为大多角骨、小多角骨、头状骨和钩骨；三角骨与手舟骨、月骨、豌豆骨同属近侧列。"},{"q":"有关脾的功能正确的是","o":["是人体最大的淋巴结","不具有造血功能","清除衰老的红细胞","不能参加免疫应答反应","不具有内分泌功能"],"a":2,"e":"脾是人体最大的淋巴器官，具有储血、造血、清除衰老红细胞及参与免疫应答的功能；它并非淋巴结，也无外分泌功能。"},{"q":"下丘脑的功能不包括","o":["神经内分泌的调节","自主神经的调节","视觉的中继站","体温的调节","摄食行为的调节"],"a":2,"e":"下丘脑是神经内分泌和自主神经的高级中枢，参与体温、摄食、水平衡和情绪调节；视觉的中继站是外侧膝状体，不属下丘脑。"},{"q":"在头面部的痛温觉传导通路中，第1级神经元胞体位于","o":["脊神经节","睫状神经节","三叉神经脊束核","三叉神经脑桥核","三叉神经节"],"a":4,"e":"头面部痛温觉传导通路的第1级神经元为三叉神经节内的假单极神经元，其中枢突入脑桥主要止于三叉神经脊束核，第2级纤维交叉后组成三叉丘系。"},{"q":"肾门位于","o":["肾的外侧缘","肾的内侧缘","肾的上端","肾的下端","肾的前面"],"a":1,"e":"肾门位于肾内侧缘中部的凹陷处，是肾血管、神经、淋巴管及肾盂出入的门户，其体表投影在竖脊肌外侧缘与第12肋的夹角处。"},{"q":"上颌窦的开口位于","o":["下鼻道","上鼻道","中鼻道","后鼻道","前鼻道"],"a":2,"e":"上颌窦开口于中鼻道半月裂孔，窦口高于窦底，直立位积液不易引流；额窦和前、中筛窦也开口于中鼻道，后筛窦开口于上鼻道。"},{"q":"心脏瓣膜复合体不包括哪个结构","o":["二、三尖瓣瓣环","瓣尖","腱索","乳头肌","肉柱"],"a":4,"e":"心脏瓣膜复合体由瓣环、瓣尖、腱索和乳头肌构成，共同保证血液单向流动；肉柱是心室壁的肌性隆起，不属瓣膜复合体。"},{"q":"损伤视交叉中央处，两眼视野表现为","o":["双眼右侧偏盲","左眼鼻侧偏盲","双眼颞侧偏盲","右眼鼻侧偏盲","双眼全盲"],"a":2,"e":"视交叉中央部为来自两眼视网膜鼻侧半的交叉纤维，损伤后两鼻侧视网膜功能丧失，表现为双眼视野颞侧偏盲。"},{"q":"掌深弓的组成","o":["由桡动脉的末端和尺动脉的掌深支组成","常由尺动脉的末端单独组成","常由桡动脉单独组成","由桡动脉的末端和尺动脉的末端组成","与掌浅弓没有吻合"],"a":0,"e":"掌深弓由桡动脉末端与尺动脉掌深支吻合而成，位于指深屈肌腱深面；掌浅弓则由尺动脉末端与桡动脉掌浅支构成。"},{"q":"关于脾切迹的描述正确的是","o":["脾前缘下部有2～3个切迹","后缘有2～3个切迹","正常情况下在肋弓下可触及","上端锐利","脾大时是触诊脾的标志"],"a":4,"e":"脾上缘较锐，前部有2～3个脾切迹，脾大时脾切迹是触诊脾的重要标志；正常脾位于左季肋区，肋弓下不能触及。"},{"q":"关于肺的淋巴管注入的淋巴结是","o":["胸骨旁淋巴结","肋间后淋巴结","气管旁淋巴结","支气管肺淋巴结","纵隔后淋巴结"],"a":3,"e":"肺的淋巴管注入肺淋巴结和支气管肺门淋巴结，再依次经气管支气管淋巴结、气管旁淋巴结引流；肺门淋巴结收纳肺和食管等处的淋巴。"},{"q":"第7颈椎的形态结构特征不包括","o":["又名隆椎","棘突长而不分叉","活体易于触及","常作为计数椎骨序数的标志","横突孔有椎动脉经过"],"a":4,"e":"第7颈椎棘突长而不分叉，末端隆起称隆椎，活体易触及，是计数椎骨序数的标志；椎动脉穿第6至第1颈椎横突孔，第7颈椎横突孔通常无椎动脉通过。"},{"q":"参与协调眼球运动和头部姿势的纤维束","o":["网状脊髓束","顶盖脊髓束","内侧纵束","前庭脊髓束","红核脊髓束"],"a":2,"e":"内侧纵束为脑干内复合的上、下行纤维束，联系前庭神经核与动眼、滑车、展神经核，协调眼球运动和头颈姿势。"},{"q":"子宫圆韧带的作用","o":["牵引子宫颈向后","维持子宫前倾","上提子宫底","防止子宫向下脱垂","防止子宫向两侧移位"],"a":1,"e":"子宫圆韧带起自子宫角前面，经腹股沟管止于阴阜和大阴唇皮下，牵引子宫底向前，维持子宫前倾；子宫主韧带则防止子宫脱垂。"},{"q":"小脑幕切迹与鞍背之间成一环形孔即小脑幕裂孔，该孔之间有","o":["中脑","脑桥","脑干","延髓","小脑"],"a":0,"e":"小脑幕切迹与鞍背之间形成小脑幕裂孔，内有中脑通过；幕上病变引起颅内压增高时，海马旁回和钩可经此疝入，压迫大脑脚和动眼神经。"},{"q":"关于胫神经的叙述，错误的是","o":["为坐骨神经主干的延续","在腘窝内，胫神经位于腘血管的浅面","在踝管内分为足底内侧神经和足底外侧神经","支配足底所有短肌","支配小腿外侧群肌"],"a":4,"e":"胫神经为坐骨神经主干的延续，在腘窝位于腘血管浅面，经踝管分为足底内侧神经和足底外侧神经，支配小腿后群肌和足底肌；小腿外侧群由腓浅神经支配。"},{"q":"肾的被膜从内向外依次是","o":["肾筋膜、脂肪囊、纤维囊","肾筋膜、纤维囊、脂肪囊","脂肪囊、纤维囊、肾筋膜","脂肪囊、肾筋膜、纤维囊","纤维囊、脂肪囊、肾筋膜"],"a":4,"e":"肾的被膜由内向外依次为纤维囊、脂肪囊和肾筋膜，纤维囊紧贴肾实质，脂肪囊为肾床，肾筋膜发出小梁穿过脂肪囊与纤维囊相连固定肾。"},{"q":"声门裂位于","o":["两侧喉室之间","两侧声襞之间","两侧声韧带之间","两侧前庭襞之间","方形膜和弹性圆锥之间"],"a":1,"e":"声门裂是两侧声襞与杓状软骨底及声带突之间的裂隙，为喉腔最狭窄处；两侧前庭襞之间的裂隙较宽，称前庭裂。"},{"q":"椎前神经节不包括哪个结构","o":["腹腔神经节","主动脉肾神经节","肠系膜上神经节","肠系膜下神经节","星状神经节"],"a":4,"e":"椎前神经节包括腹腔神经节、主动脉肾神经节、肠系膜上神经节和肠系膜下神经节；星状神经节即颈胸神经节，属椎旁神经节。"},{"q":"损伤后导致共济失调的纤维束","o":["脊髓丘脑前束","脊髓丘脑侧束","脊髓小脑束","皮质脊髓侧束","皮质脊髓前束"],"a":2,"e":"脊髓小脑束将躯干和下肢的本体感觉传入小脑，损伤后肢体动作不协调，出现共济失调；脊髓丘脑束损伤主要致对侧痛温觉障碍。"},{"q":"位于中脑顶盖的结构是","o":["红核","黑质","动眼神经核","三叉神经中脑核","上丘"],"a":4,"e":"中脑顶盖由一对上丘和一对下丘构成，上丘为视觉反射中枢，下丘为听觉反射中枢；红核和黑质位于被盖部，不属顶盖。"},{"q":"右侧内囊膝损伤可出现","o":["左侧下肢肌瘫痪","右侧下肢肌瘫痪","左侧面肌全部瘫痪","左侧睑裂以下面肌瘫痪","右侧舌肌瘫痪"],"a":3,"e":"内囊膝通过皮质核束，右侧损伤使左侧面神经核下部和舌下神经核失去上运动神经元支配，表现为左侧睑裂以下面肌瘫痪、伸舌偏左。"},{"q":"桡神经沟位于","o":["肱骨体中部的后面内上斜向外下的浅沟","肱骨体中部的前面内上斜向外下的浅沟","肱骨体中部的后面外上斜向内下的浅沟","肱骨体中部的前面外上斜向内下的浅沟","肱骨体中部的后面横行的浅沟"],"a":0,"e":"桡神经沟位于肱骨体后面中部，自内上斜向外下，桡神经和肱深动脉沿此沟经过，肱骨中段骨折易伤及桡神经而出现垂腕。"},{"q":"舌咽神经管理的腺体是","o":["腮腺","泪腺","舌下腺","下颌下腺","甲状腺"],"a":0,"e":"舌咽神经的一般内脏运动纤维起自下泌涎核，经岩小神经至耳神经节换元，节后纤维经耳颞神经支配腮腺分泌；面神经管理下颌下腺和舌下腺。"},{"q":"胸骨角平对","o":["第1肋","第2肋","第3肋","第4肋","第5肋"],"a":1,"e":"胸骨角是胸骨柄与胸骨体连接处向前的横嵴，两侧平对第2肋软骨，向后平对第4胸椎体下缘，是计数肋骨和划分上、下纵隔的标志。"},{"q":"关于腹主动脉分支，错误的说法是","o":["分为壁支和脏支","脏支包括成对和不成对的","最上方不成对的脏支为腹腔干","阑尾动脉为其主要分支之一","肾上腺中动脉为该动脉发出的脏支"],"a":3,"e":"阑尾动脉发自回结肠动脉，属肠系膜上动脉的分支；腹主动脉的脏支包括不成对的腹腔干、肠系膜上动脉、肠系膜下动脉和成对的肾上腺中动脉、肾动脉、睾丸动脉。"},{"q":"关于肺静脉的正确记述是","o":["注入右心房","含有静脉血","含左上、左下肺静脉","含右上、右中、右下肺静脉","位于肺根的最上方"],"a":2,"e":"肺静脉每侧两条，即左上、左下和右上、右下肺静脉，注入左心房，运送含氧量高的血液；右上肺静脉收集右肺上、中叶的血液。"},{"q":"寰枕关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":2,"e":"寰枕关节由枕髁与寰椎侧块的上关节凹构成，关节头呈椭圆形，属双轴椭圆关节，两侧同时活动可使头俯仰和侧屈。"},{"q":"关于心脏表面标志正确的说法是","o":["冠状沟分隔左、右心房","界沟分隔心房、心室","室间沟深部为室间隔","心尖左侧有心尖切迹","冠状沟位于人体的冠状面上"],"a":2,"e":"前、后室间沟是左、右心室在心表面的分界，其深部即室间隔；冠状沟分隔心房与心室，界沟位于右心房表面。"},{"q":"背侧丘脑腹后外侧核接受","o":["三叉丘系纤维","内侧丘系、脊髓丘系","嗅觉纤维","味觉纤维","内脏感觉纤维"],"a":1,"e":"腹后外侧核接受内侧丘系和脊髓丘系纤维，中继后经丘脑中央辐射投射至中央后回；腹后内侧核接受三叉丘系和味觉纤维。"},{"q":"关于腹膜腔的叙述，错误的是","o":["女性腹膜腔与外界相通","为全身最大的浆膜","有吸收功能","由壁腹膜和脏腹膜围成","包裹所有的腹腔脏器"],"a":4,"e":"腹膜腔由壁腹膜和脏腹膜围成，是全身最大的浆膜腔，有吸收功能，女性经输卵管腹腔口与外界相通；腹膜外位器官如肾、胰表面无腹膜包裹。"},{"q":"关于胸导管的叙述，下列哪项是正确的","o":["于奇静脉和腹主动脉之间上行","上段与右侧纵隔胸膜所相邻","在第5胸椎平面处斜行向左","在下纵隔，胸导管位于食管的左侧","最后注入右颈静脉角"],"a":2,"e":"胸导管起自乳糜池，经主动脉裂孔入胸腔，沿脊柱右前方在胸主动脉与奇静脉之间上行，至第5胸椎高度斜行向左，最后注入左静脉角。"},{"q":"正中神经损伤典型症状的状态是","o":["“垂腕症”","“猿手”","“爪形手”","“方肩”","“翼状肩”"],"a":1,"e":"正中神经损伤致鱼际肌萎缩、手掌平坦，称猿手；尺神经损伤出现爪形手，桡神经损伤出现垂腕，腋神经损伤出现方肩。"},{"q":"眼球壁三层结构，由外向内依次为","o":["虹膜、血管膜、视网膜","纤维膜、血管膜、视网膜","纤维膜、角膜、视网膜","角膜、血管膜、视网膜","角膜、巩膜、视网膜"],"a":1,"e":"眼球壁由外向内依次为纤维膜、血管膜和视网膜，纤维膜分角膜与巩膜，血管膜含虹膜、睫状体和脉络膜，视网膜为感光层。"},{"q":"关于盲肠描述正确的是","o":["其右侧接回肠","长3～5cm","位置不固定","一部分被腹膜包裹","为腹膜内位器官"],"a":4,"e":"盲肠各面均有腹膜覆盖，属腹膜内位器官，因无系膜或系膜短小，位置相对固定；其左侧接回肠，下续升结肠。"},{"q":"尺骨的骨性标志不包括","o":["尺骨后缘","桡切迹","鹰嘴","尺骨头","茎突"],"a":0,"e":"官方答案为【尺骨后缘】，但依据教材，正确答案为【桡切迹】。教材载鹰嘴、后缘全长、尺骨头和茎突均可在体表扪及，而桡切迹为与桡骨头相关节的关节面，不能触及。"},{"q":"以下哪个不是迷走神经颈部的分支","o":["喉上神经","耳支","咽支","脑膜支","左喉返神经"],"a":4,"e":"迷走神经在颈部发出喉上神经、咽支、耳支和脑膜支；喉返神经在胸部发出，左喉返神经勾绕主动脉弓，右喉返神经勾绕右锁骨下动脉。"},{"q":"不直接起自腹主动脉的是","o":["脾动脉","肠系膜上动脉","睾丸动脉","肾动脉","肾上腺中动脉"],"a":0,"e":"脾动脉是腹腔干的分支，腹腔干还分出胃左动脉和肝总动脉；肠系膜上动脉、睾丸动脉、肾动脉和肾上腺中动脉均直接起自腹主动脉。"},{"q":"脊髓蛛网膜","o":["位于软脊膜的内面","位于硬脑膜的外面","其外面有脑脊液流动","与硬脊膜之间有终池","与软脊膜之间的间隙称蛛网膜下隙"],"a":4,"e":"脊髓蛛网膜位于硬脊膜深面、软脊膜浅面，与软脊膜之间为较宽的蛛网膜下隙，内充满脑脊液；其下部自脊髓下端至第2骶椎扩大为终池。"},{"q":"关于锥体交叉和内侧丘系交叉，下列说法错误的是","o":["位于延髓内，锥体交叉位置较低","位于延髓内，内侧丘系交叉位置较高","在延髓内位于同一平面","锥体交叉是运动纤维交叉","内侧丘系交叉属于感觉纤维交叉"],"a":2,"e":"锥体交叉位于延髓下端，位置较低，为运动纤维交叉；内侧丘系交叉位于其上方，属感觉纤维交叉，二者不在同一平面。"},{"q":"鼓索含有","o":["特殊内脏运动和一般内脏感觉两种纤维","一般内脏运动和一般内脏感觉两种纤维","特殊内脏感觉和一般内脏感觉两种纤维","特殊内脏感觉和特殊内脏运动两种纤维","特殊内脏感觉和一般内脏运动两种纤维"],"a":4,"e":"鼓索含特殊内脏感觉和一般内脏运动两种纤维，前者司舌前2/3味觉，后者为副交感纤维，经下颌下神经节换元后控制下颌下腺和舌下腺的分泌。"},{"q":"临床上，可触及肩胛骨的主要骨性标志包括","o":["肩胛冈、肩峰、肩胛骨下角、内侧缘及肩胛下窝","肩胛冈、肩峰、肩胛骨下角、内侧缘及冈下窝","肩胛冈、肩峰、肩胛骨下角、内侧缘及喙突","肩胛冈、肩峰、肩胛骨下角、内侧缘及冈上窝","肩胛冈、肩峰、肩胛骨下角、内侧缘及肩胛切迹"],"a":2,"e":"肩胛冈、肩峰、肩胛骨下角和内侧缘及喙突均可在体表扪及；肩胛下窝、冈上窝和冈下窝分别位于肩胛骨前面和背面，不能直接触及。"},{"q":"关于鼓室内侧壁的描述，不正确的是","o":["中部的隆起称为岬","岬的后上方有前庭窗","岬的后下方有蜗窗","前庭窗的后上方有面神经管凸","蜗窗由镫骨底封闭"],"a":4,"e":"鼓室内侧壁中部隆起为岬，岬的后上方有前庭窗，由镫骨底及韧带封闭；岬的后下方为蜗窗，由第二鼓膜封闭而非镫骨底。"},{"q":"只接受对侧皮质核束纤维的神经核是","o":["三叉神经运动核","滑车神经核","动眼神经核","舌下神经核","展神经核"],"a":3,"e":"面神经核下部和舌下神经核只接受对侧皮质核束支配，其余脑神经运动核均接受双侧纤维；故一侧内囊膝损伤出现对侧面下部肌和舌肌瘫痪。"},{"q":"外旋肩关节的肌是","o":["胸大肌","背阔肌","冈上肌","小圆肌","大圆肌"],"a":3,"e":"小圆肌止于肱骨大结节下部，收缩使肩关节旋外；冈下肌亦使肩关节旋外，大圆肌、胸大肌和背阔肌则使肩关节旋内。"},{"q":"寰枢正中关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":1,"e":"寰枢正中关节由枢椎齿突与寰椎前弓后面的关节面构成，属车轴关节，可沿垂直轴作旋转运动，使头转向对侧。"},{"q":"有关腹膜腔，描述正确的是","o":["经横结肠及胃结肠韧带分为结肠上区和结肠下区","大、小腹膜腔经网膜孔相通","半卧位最低部位是右肝下间隙","各间隙之间均相互交通","左结肠旁沟积液不易流出"],"a":1,"e":"网膜囊又称小腹膜腔，借肝十二指肠韧带后方的网膜孔与腹膜腔其余部分即大腹膜腔相通；腹膜腔以横结肠及其系膜分为结肠上、下区。"},{"q":"关于面静脉走行的正确的描述是","o":["起自内眦静脉","注入颈外静脉","在颈内、颈外动脉的深面走行","通过面深静脉与乙状窦相通","位于面动脉前方"],"a":0,"e":"面静脉起自内眦静脉，在面动脉后方下行，于下颌角下方接受下颌后静脉前支，跨过颈内、外动脉表面注入颈内静脉。"},{"q":"听小骨链正确的关节顺序是","o":["锤骨-砧骨-镫骨","锤骨-镫骨-砧骨","砧骨-锤骨-镫骨","镫骨-砧骨-锤骨","镫骨-锤骨-砧骨"],"a":0,"e":"听小骨链依次为锤骨、砧骨和镫骨，锤骨柄连于鼓膜，砧骨长脚与镫骨头形成砧镫关节，镫骨底封闭前庭窗，将声波振动传入内耳。"},{"q":"筛窦后群开口于","o":["中鼻道","上鼻道","下鼻道","蝶筛隐窝","鼻泪管"],"a":1,"e":"筛窦前、中群开口于中鼻道，后群开口于上鼻道；后筛窦与视神经管毗邻，感染蔓延可引起视神经炎。"},{"q":"关于胸腺的描述，不正确的是","o":["向上可伸入胸廓上口","位于胸骨柄的后方","上纵隔的前部","胸腺是淋巴器官","新生儿的胸腺较小"],"a":4,"e":"胸腺位于上纵隔前部、胸骨柄后方，可向上伸入胸廓上口达颈部；新生儿和幼儿胸腺相对较大，性成熟后发育至高峰，随后逐渐萎缩。"},{"q":"最强大的伸髋关节肌是","o":["股二头肌","半腱肌","半膜肌","臀大肌","臀中肌"],"a":3,"e":"臀大肌起自髂骨翼外面和骶骨背面，止于髂胫束和股骨臀肌粗隆，收缩使髋关节伸和旋外，是伸髋关节最强大的肌。"},{"q":"对纵隔的描述，正确的选项是","o":["位于胸膜腔内","上界是肺尖","容纳心、肺","两侧界是纵隔胸膜","两侧界是肺门"],"a":3,"e":"纵隔是两侧纵隔胸膜之间全部器官、结构和结缔组织的总称，前界为胸骨，后界为脊柱胸段，上界为胸廓上口，下界为膈。"},{"q":"尺神经在腕部豌豆骨外侧受损后，出现的症状不包括","o":["骨间肌萎缩","掌骨沟明显深陷","第4、5掌指关节过伸，指骨间关节屈曲","小鱼际肌萎缩","垂腕征"],"a":4,"e":"垂腕征是桡神经损伤的典型表现，因桡侧腕长、短伸肌及指伸肌瘫痪所致。腕部豌豆骨外侧损伤的是尺神经，仅累及手内肌，出现骨间肌和小鱼际肌萎缩、掌骨间沟深陷及环小指爪形手。"},{"q":"棘突宽而短，呈板状，水平伸向后方的椎骨是","o":["寰椎","第2～6颈椎","隆椎","胸椎","腰椎"],"a":4,"e":"腰椎棘突宽而短，呈板状，水平伸向后方，各棘突间隙较宽，临床上可于此行腰椎穿刺。胸椎棘突细长并斜向后下方，呈叠瓦状排列，颈椎棘突短而分叉。"},{"q":"可伸和外展桡腕关节的肌肉是","o":["肱桡肌","桡侧腕长伸肌","指伸肌","掌长肌","尺侧腕伸肌"],"a":1,"e":"桡侧腕长伸肌止于第2掌骨底，桡侧腕短伸肌止于第3掌骨底，二肌的主要作用为伸腕和外展腕关节。尺侧腕伸肌的作用是伸腕并内收腕关节。"},{"q":"左侧内囊损伤表现为","o":["左额纹消失","左侧能闭眼，左口角下垂","左侧不能闭眼，右口角下垂","右侧能闭眼，右口角下垂并向左侧偏斜","右侧不能闭眼，左口角下垂并向左侧偏斜"],"a":3,"e":"左侧内囊损伤使皮质核束受损，面神经核上部接受双侧皮质核束纤维，故额肌和眼轮匝肌功能保留，能闭眼；核下部仅受对侧纤维支配，致右口角下垂并歪向健侧。"},{"q":"含有内脏运动纤维的是","o":["三叉神经","副神经","面神经","舌下神经","滑车神经"],"a":2,"e":"面神经为混合性脑神经，含一般内脏运动（副交感）纤维，起自上泌涎核，经翼腭神经节和下颌下神经节换元后支配泪腺及唾液腺分泌。"},{"q":"脚踩到钉子后，下肢反射性的屈曲，分析该反射属于","o":["牵张反射","深反射","屈曲反射","单突触反射","病理反射"],"a":2,"e":"屈曲反射是肢体皮肤受伤害性刺激时出现的保护性屈曲反应，其径路至少需3个神经元参加，属多突触反射。踩钉后下肢回缩即属此类，而非牵张反射或单突触反射。"},{"q":"开口于上鼻道的器官","o":["额窦","上颌窦","筛窦前群","筛窦中群","筛窦后群"],"a":4,"e":"筛窦后群开口于上鼻道，前群和中群均开口于中鼻道。额窦经筛漏斗开口于中鼻道，上颌窦开口于中鼻道半月裂孔。"},{"q":"关于肾的位置描述，正确的是","o":["位于腹膜后间隙前","右肾略高于左肾","肾门高度约位于第2腰椎体平面","第12肋斜越左肾后面中部","两肾下端距离较近"],"a":3,"e":"第12肋分别斜过左肾后面中部和右肾后面上部。肾门约平第1腰椎椎体，两肾上端相距较近、下端相距较远，右肾因肝的存在而略低于左肾。"},{"q":"和眼球运动无关的眼球外肌是","o":["上睑提肌","上直肌","下直肌","上斜肌","内直肌"],"a":0,"e":"上睑提肌起自视神经管前上方的眶壁，止于上睑皮肤和上睑板，收缩时提上睑、开大眼裂，属运动眼睑的肌。运动眼球的为四条直肌和两条斜肌。"},{"q":"关于迷走神经不正确的是","o":["分布于颈、胸、腹腔大部分脏器的平滑肌、心肌、腺体","左迷走神经勾绕锁骨下动脉经食管前面下行形成前干","参与心丛的形成","腹腔支加入腹腔神经丛","喉上神经支配环甲肌与声门裂以上的喉黏膜"],"a":1,"e":"左迷走神经越过主动脉弓前方，经左肺根后方至食管前面下行组成前干；勾绕锁骨下动脉的是右迷走神经。左喉返神经勾绕主动脉弓，右喉返神经勾绕右锁骨下动脉。"},{"q":"下颌神经出入颅腔的部位","o":["茎乳孔","眶下裂","圆孔","破裂孔","卵圆孔"],"a":4,"e":"三叉神经第三支下颌神经经卵圆孔出颅，眼神经经眶上裂入眶，上颌神经经圆孔出颅。面神经则由内耳门至茎乳孔出颅。"},{"q":"关于眼的神经支配的叙述，错误的是","o":["展神经支配外直肌","滑车神经支配上斜肌","上直肌由动眼神经支配","感觉神经来自三叉神经的眼支","瞳孔开大肌受副交感神经支配"],"a":4,"e":"瞳孔开大肌呈放射状排列，受颈上神经节的交感纤维支配，兴奋时使瞳孔开大；瞳孔括约肌和睫状肌才受动眼神经副交感纤维支配。"},{"q":"关于舌扁桃体描述正确的是","o":["参与构成咽峡","位于界沟前方","其后方有舌盲孔","由淋巴组织构成","位于舌的两侧"],"a":3,"e":"舌扁桃体位于舌根背面黏膜，是由淋巴组织构成的大小不等的丘状隆起，属咽淋巴环的组成部分。界沟与舌盲孔均位于其前方。"},{"q":"关于空、回肠描述正确的是","o":["空肠上接十二指肠上曲","回肠下续结肠","近侧3/5为空肠，远侧2/5为回肠","约2%的成人，在回肠末端0.3～1m范围内，有Meckel憩室","空肠肠壁内有集合淋巴"],"a":3,"e":"约2%的成人，在距回肠末端0.3～1.0m范围的回肠对系膜缘有Meckel憩室，为胚胎期卵黄囊管未完全消失所致。空肠占近侧2/5、回肠占远侧3/5，集合淋巴滤泡位于回肠。"},{"q":"只能外展肩关节的肌是","o":["胸大肌","背阔肌","冈上肌","小圆肌","三角肌"],"a":2,"e":"冈上肌起自冈上窝，肌腱越过肩关节上方止于肱骨大结节上部，作用为使肩关节外展，是只作用于肩关节外展的肌。三角肌除外展外还能屈、伸和旋转肩关节。"},{"q":"关于尺神经正确的是","o":["发自臂丛外侧束","支配前臂所有屈肌","经肱骨下端尺神经沟下行进入前臂","损伤后不影响拇指的任何功能","肱骨外侧髁骨折时易受损"],"a":2,"e":"尺神经发自臂丛内侧束，穿内侧肌间隔下行入肱骨内上髁后方的尺神经沟，再经尺侧腕屈肌起点行至前臂前内侧。它只支配尺侧腕屈肌和指深屈肌尺侧半。"},{"q":"关于胆总管的描述正确的是","o":["直径0.3～0.5cm","位于肝固有动脉的左侧","位于肝胃韧带内","由左、右肝管汇合形成","由肝总管和胆囊管汇合形成"],"a":4,"e":"胆总管由肝总管与胆囊管汇合而成，长4～8cm，直径0.6～0.8cm，行于肝十二指肠韧带内，位于肝固有动脉右侧。左、右肝管汇合形成的是肝总管。"},{"q":"临床上上肢出血可压迫哪根血管进行止血","o":["压迫颈总动脉进行止血","压迫颞浅动脉进行止血","压迫面动脉进行止血","压迫肱动脉进行止血","压迫股动脉进行止血"],"a":3,"e":"上肢出血时可于臂中部将肱动脉压向肱骨止血，前臂和手部出血亦可在肱二头肌内侧沟中份压迫肱动脉。颈总动脉、颞浅动脉和面动脉用于头面部止血。"},{"q":"脑脊液产生于","o":["脑组织","硬脑膜","蛛网膜","软脑膜","脑室脉络丛"],"a":4,"e":"脑脊液主要由各脑室脉络丛产生，少量由室管膜上皮和毛细血管产生。侧脑室脉络丛经室间孔入第三脑室，经中脑水管至第四脑室，再经正中孔和外侧孔流入蛛网膜下隙。"},{"q":"海绵窦外侧壁自上而下排列正确的是","o":["展神经、动眼神经和上颌神经","动眼神经、滑车神经、眼神经和上颌神经","展神经和颈内动脉","眼神经、上颌神经、动眼神经和滑车神经","滑车神经、眼神经、动眼神经和展神经"],"a":1,"e":"海绵窦外侧壁自上而下依次有动眼神经、滑车神经、眼神经和上颌神经通过；窦腔内侧壁则有颈内动脉和展神经穿行。"},{"q":"在脊柱，连于各个椎体与椎间盘之间，有限制脊柱过度前屈的韧带是","o":["棘上韧带","黄韧带","后纵韧带","前纵韧带","横突间韧带"],"a":2,"e":"后纵韧带位于椎管内椎体的后面，与椎间盘纤维环及椎体上下缘紧密相连，有限制脊柱过度前屈的作用。限制脊柱过度后伸的是前纵韧带。"},{"q":"儿童期功能低下时可导致呆小症，为下列哪个内分泌腺","o":["垂体","松果体","甲状腺","甲状旁腺","肾上腺"],"a":2,"e":"甲状腺素对婴幼儿的骨骼发育和中枢神经系统发育影响显著，小儿甲状腺功能减退时身体矮小并伴脑发育障碍，即呆小症。甲状旁腺则主司钙磷代谢。"},{"q":"上肢带骨包括","o":["肩胛骨","肱骨","桡骨","尺骨","手骨"],"a":0,"e":"上肢带骨包括锁骨和肩胛骨，自由上肢骨包括肱骨、桡骨、尺骨和手骨。肱骨属自由上肢骨的近侧部。"},{"q":"在仰卧时，腹膜腔最低的部位是","o":["十二指肠上隐窝","盲肠后隐窝","肝肾隐窝","膀胱上窝","腹股沟内侧窝"],"a":2,"e":"肝肾隐窝位于肝右叶与右肾之间，仰卧位时是腹膜腔的最低部位，积液常积存于此。该隐窝向上与右结肠旁沟相通。"},{"q":"输送尿液离开肾的结构是","o":["乳头孔","肾小盏","肾大盏","肾盂","输尿管"],"a":3,"e":"肾盂由2～3个肾大盏汇合而成，出肾门后逐渐变细，约在第2腰椎上缘水平移行为输尿管，是尿液离开肾的通道。乳头孔、肾小盏和肾大盏均位于肾内。"},{"q":"关于输尿管盆部的描述，正确的是","o":["沿腰大肌前面下行至盆底","属于腹膜内位器官","经骨盆上口入盆后称为输尿管盆部","女性经子宫动脉的前上方至膀胱底","男性经输精管的前上方至膀胱底"],"a":2,"e":"输尿管自小骨盆入口处续为盆部，经盆腔侧壁、髂内血管和骶髂关节前方下行达坐骨棘水平。沿腰大肌前面下行的是输尿管腹部，输尿管属腹膜外位器官。"},{"q":"关于颈外动脉正确的是","o":["在平对环状软骨下缘高度发自颈总动脉","在平对甲状软骨上缘高度发自颈总动脉","有分支分布于脑","在下颌颈处分为面动脉和颞浅动脉","分布于甲状腺侧叶下部"],"a":1,"e":"颈总动脉在平甲状软骨上缘处分为颈内动脉和颈外动脉，分叉处称颈动脉杈。颈外动脉分支分布于头颈部和硬脑膜，有分支分布于脑的是颈内动脉。"},{"q":"关于肾的叙述，错误的是","o":["左肾蒂较右肾蒂长","肾窦是肾门的延续","肾窦内没有输尿管","肾锥体的数目与肾乳头总数一致","肾筋膜包被在肾上腺和肾的周围"],"a":3,"e":"2～3个肾锥体尖端合并成一个肾乳头，故肾锥体数多于肾乳头数，二者数目并不一致。肾窦是肾门的延续，左肾蒂较右肾蒂长，肾筋膜包裹肾和肾上腺。"},{"q":"心尖由哪部分构成","o":["左心室","右心室","左心房","右心房","动脉圆锥"],"a":0,"e":"心尖圆钝而游离，由左心室构成，朝向左前下方，在左侧第5肋间隙锁骨中线内侧1～2cm处可触及心尖搏动。"},{"q":"关于肛管的描述正确的是","o":["上端在尿生殖膈平面连续直肠","与直肠的分界线称为白线","肛窦是由肛瓣和相邻肛柱的下端形成","发生在齿状线以上的痔称为外痔","发生在齿状线以下的痔称为内痔"],"a":2,"e":"肛窦由每一肛瓣与其相邻两个肛柱下端围成，开口向上，窦底有肛腺开口，易积存粪屑而致肛窦炎。直肠与肛管的分界为肛直肠线，齿状线以上者为内痔。"},{"q":"不属于腰丛的是","o":["股外侧皮神经","髂腹下神经","髂腹股沟神经","生殖股神经","臀上神经"],"a":4,"e":"臀上神经自骶丛发出，经梨状肌上孔出盆腔分布于臀中、小肌，不属腰丛。腰丛分支包括髂腹下神经、髂腹股沟神经、生殖股神经和股外侧皮神经。"},{"q":"滑膜关节的基本结构不包括","o":["关节囊外层","关节唇","关节面","关节囊内层","关节腔"],"a":1,"e":"滑膜关节的基本结构为关节面、关节囊和关节腔，关节囊分纤维膜与滑膜两层。关节唇和关节盘属辅助结构，可加深关节窝、增加关节稳固性。"},{"q":"参与瞳孔对光反射的结构是","o":["红核","黑质","顶盖前区","下丘","上丘"],"a":2,"e":"瞳孔对光反射通路为视网膜→视神经→视交叉→视束→上丘臂→顶盖前区→两侧动眼神经副核→动眼神经→睫状神经节→瞳孔括约肌。顶盖前区是联络两侧副核的关键中继站。"},{"q":"下泌涎核发出纤维参与组成","o":["面神经","舌咽神经","迷走神经","副神经","舌下神经"],"a":1,"e":"下泌涎核位于延髓上部，发出一般内脏运动纤维随舌咽神经走行，经鼓室神经、岩小神经至耳神经节换元，节后纤维经耳颞神经支配腮腺分泌。"},{"q":"支配眼球外肌的神经","o":["动眼神经、滑车神经、展神经","三叉神经、舌咽神经、面神经","舌咽神经、迷走神经、舌下神经","动眼神经、滑车神经、三叉神经","三叉神经、面神经"],"a":0,"e":"眼球外肌由动眼神经、滑车神经和展神经支配：动眼神经支配上直肌、下直肌、内直肌、下斜肌和上睑提肌，滑车神经支配上斜肌，展神经支配外直肌。"},{"q":"指骨间关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":0,"e":"指骨间关节由相邻指骨的底与滑车构成，共9个，关节囊两侧有韧带加强，只能作屈伸运动，是典型的屈戌关节。"},{"q":"有关右心房错误的描述是","o":["界嵴分隔腔静脉窦和固有心房","固有心房的前上部为右心耳","Koch三角的深面为房室结","右心房收集除心脏以外体循环的静脉血","梳状肌起自界嵴"],"a":3,"e":"右心房除接纳上、下腔静脉的体循环静脉血外，还接受冠状窦回流的心静脉血。界嵴分隔腔静脉窦与固有心房，梳状肌起自界嵴，Koch三角深面为房室结。"},{"q":"喉室位于喉腔内，属于","o":["喉前庭","喉中间腔","声门下腔","弹性圆锥","方形膜"],"a":1,"e":"喉中间腔是声襞与前庭襞之间的部分，向两侧经前庭襞与声襞间的裂隙延伸为喉室。喉前庭位于喉口与前庭襞之间，声门下腔位于声襞以下。"},{"q":"对滑车神经的描述，正确的是","o":["起于同侧的滑车神经核","经上丘下方出脑","紧贴颈内动脉穿海绵窦","经眶上裂入眶","支配下斜肌"],"a":3,"e":"滑车神经起于对侧的滑车神经核，自中脑下丘下方出脑，穿海绵窦外侧壁后经眶上裂入眶，支配上斜肌，是唯一自脑干背面出脑的脑神经。"},{"q":"在上肢骨的连结，有肱二头肌长头腱经过关节囊的关节是","o":["胸锁关节","肩关节","肩锁关节","肘关节","腕关节"],"a":1,"e":"肩关节囊的滑膜层向外膨出形成结节间滑膜鞘，肱二头肌长头腱即经此鞘穿过关节腔，该腱起自肩胛骨盂上结节，经肱骨结节间沟下行。"},{"q":"蝶窦开口于","o":["上鼻道","中鼻道","下鼻道","蝶筛隐窝","上鼻甲下方"],"a":3,"e":"蝶窦居蝶骨体内，被中隔分为左右两腔，分别向前开口于蝶筛隐窝。上颌窦、额窦及筛窦前、中群均开口于中鼻道。"},{"q":"关于胸神经前支说法正确的是","o":["进入肋间隙形成12对肋间神经","神经纤维来自脊神经前根","支配肋间肌的运动神经","第1肋间神经的外侧皮支称为肋间臂神经","在胸、腹壁皮肤具有明显的节段性分布特点"],"a":4,"e":"胸神经前支在胸、腹壁皮肤的分布具有明显节段性，T2相当胸骨角平面、T4乳头平面、T6剑突平面、T10脐平面。第1胸神经前支大部分加入臂丛，肋间臂神经来自第2肋间神经外侧皮支。"},{"q":"支配肱二头肌的神经是","o":["肌皮神经","尺神经","腋神经","桡神经","正中神经的分支"],"a":0,"e":"肌皮神经自臂丛外侧束发出，斜穿喙肱肌，在肱二头肌与肱肌之间下行并发出分支支配该三肌，终支在肘关节稍下方穿出深筋膜续为前臂外侧皮神经。"},{"q":"心底由哪个心房及心室构成","o":["左心室和右心室","右心室和右心房","左心房和右心房","左心室和左心房","右心室和左心房"],"a":2,"e":"心底朝向右后上方，主要由左心房构成，仅小部分由右心房构成；心尖则由左心室构成，故心底与心尖的构成不同。"},{"q":"肾窦内的结构不包括","o":["肾柱","肾小盏","肾大盏","肾盂","肾血管"],"a":0,"e":"肾窦内容纳肾血管、肾小盏、肾大盏、肾盂和脂肪等。肾柱是伸入肾锥体之间的肾皮质，属肾实质而非肾窦内的结构。"},{"q":"关于神经元的论述错误的是","o":["是神经系统结构和功能的基本单位","突起分为树突和轴突","具有接受刺激及传导神经冲动的功能","由胞体和突起两部分构成","双极神经元属运动神经元"],"a":4,"e":"双极神经元属感觉神经元，见于视网膜双极细胞及前庭神经节、蜗神经节；运动神经元为多极神经元。神经元由胞体和突起构成，突起分树突和轴突。"},{"q":"关于乙状窦的说法，正确的是","o":["直接注入颈内静脉","不成对","位于枕骨横沟内","是窦汇的延续","是直窦的延续"],"a":0,"e":"乙状窦成对，位于乙状窦沟内，是横窦的延续，向前下在颈静脉孔处出颅续为颈内静脉。窦汇由上矢状窦、直窦和横窦汇合而成。"},{"q":"关于膀胱分部的叙述，错误的是","o":["膀胱颈","膀胱体","膀胱底","膀胱尖","前列腺部"],"a":4,"e":"膀胱分膀胱尖、膀胱体、膀胱底和膀胱颈四部。前列腺部是男性尿道穿过前列腺的部分，属尿道分部，不属膀胱分部。"},{"q":"第3～6颈椎的形态结构特征包括","o":["椎体大，呈心形","横突末端有颈动脉结节","有横突孔","上、下关节突的关节面呈冠状位","棘突长而不分叉"],"a":2,"e":"第3～6颈椎椎体较小，椎孔较大呈三角形，横突有横突孔，有椎动脉和椎静脉通过。颈动脉结节为第6颈椎横突前结节，关节面呈冠状位是胸椎的特征。"},{"q":"肾实质的结构不包括","o":["肾锥体","肾乳头","肾小盏","乳头孔","肾柱"],"a":2,"e":"肾实质分皮质和髓质，髓质由肾锥体构成，肾锥体尖为肾乳头，乳头上有乳头孔，肾柱为伸入锥体间的皮质。肾小盏属肾窦内的排尿管道。"},{"q":"关于第Ⅰ躯体感觉区的叙述，错误的是","o":["位于中央后回和中央旁小叶后部","接受对侧半躯体痛、温、触、压以及位置和运动觉","投影区的大小与各部形体大小无关","投影区的大小取决于该部感觉敏感程度","头面部投影区是上下颠倒"],"a":4,"e":"第Ⅰ躯体感觉区位于中央后回和中央旁小叶后部，其投射特点为上下颠倒但头部为正、左右交叉，投射范围取决于该部感觉敏感程度而非形体大小。"},{"q":"关于颈椎正确的是","o":["均有椎体及椎弓","1、2颈椎无横突孔","棘突末端都分叉","第6颈椎棘突末端膨大成颈动脉结节","第7颈椎又名隆椎"],"a":4,"e":"第7颈椎又名隆椎，棘突长、末端不分叉，活体易于触及，是计数椎骨序数的标志。寰椎无椎体和棘突，第1、2颈椎也有横突孔。"},{"q":"颈椎的形态结构特征为","o":["椎体粗壮","椎体横断面呈肾形","椎孔呈卵圆形或三角形","关节突的关节面近似冠状位","棘突呈板状，水平伸向后方，彼此之间的间隙较大"],"a":3,"e":"官方答案为【关节突的关节面近似冠状位】，但依据教材，正确答案为【椎孔呈卵圆形或三角形】。颈椎椎孔较大呈三角形、关节突关节面接近水平位，关节面呈冠状位是胸椎的特征。"},{"q":"附着于延髓脑桥沟的脑神经，从内侧向外侧为","o":["迷走神经、舌咽神经、前庭蜗神经","舌咽神经、前庭蜗神经、面神经","展神经、面神经、前庭蜗神经","面神经、展神经、三叉神经","前庭蜗神经、面神经、展神经"],"a":2,"e":"延髓脑桥沟内自中线向外侧依次连有展神经、面神经和前庭蜗神经根。三叉神经连于脑桥基底部与小脑中脚交界处。"},{"q":"没有通过内囊后肢的上、下行纤维是","o":["丘脑中央辐射","视辐射","皮质脊髓束","听辐射","皮质核束"],"a":4,"e":"皮质核束经内囊膝部下行，不通过后肢。内囊后肢的豆丘部有皮质脊髓束和丘脑中央辐射，豆状核后部有视辐射，豆状核下部有听辐射。"},{"q":"下列关于动脉摸脉点的描述正确的是","o":["面动脉在活体上易触摸到搏动的部位在咬肌后缘与下颌骨下缘交界处","足背动脉在活体上易触摸到搏动的部位是踝关节后方，内、外踝连线的中点","股动脉在活体上易触摸到搏动的部位是股动脉的上段","桡动脉在活体上诊脉的部位是桡动脉上段","股动脉在活体上易触摸到搏动的部位是股动脉的下段"],"a":2,"e":"股动脉在腹股沟韧带中点稍下方位置表浅，活体可触及搏动，下肢出血时可在此将动脉压向耻骨上支。面动脉在咬肌前缘绕下颌骨下缘处、足背动脉在踝关节前方可触及搏动。"},{"q":"肱骨外科颈的部位是","o":["肱骨大、小结节交界处","肱骨头周围的环形沟","肱骨头与肱骨干的交界处","肱骨上端干骺端处","肱骨上端与肱骨干的交界处"],"a":4,"e":"肱骨外科颈是肱骨上端与肱骨体交界处稍细的部位，为肱骨头骨松质与肱骨干骨皮质交界的区域，较易发生骨折。"},{"q":"属于骨迷路的结构是","o":["椭圆囊","耳蜗","球囊","膜半规管","蜗管"],"a":1,"e":"骨迷路分为耳蜗、前庭和骨半规管三部分，由颞骨岩部骨密质围成。椭圆囊、球囊、膜半规管和蜗管均属膜迷路。"},{"q":"关于锥体系的叙述，错误的是","o":["含有皮质脊髓束","含有皮质核束","含有上、下运动神经元","含有小脑","含有中央前回和中央旁小叶的Betz细胞"],"a":3,"e":"锥体系包括皮质脊髓束和皮质核束，由中央前回和中央旁小叶的锥体细胞（含Betz细胞）发出，经上、下两级运动神经元完成随意运动。小脑属锥体外系结构。"},{"q":"下列属于海马结构的是","o":["齿状回","扣带回","海马旁回钩","杏仁体","海马旁回"],"a":0,"e":"海马和齿状回共同构成海马结构，位于侧脑室下角底壁及海马沟上方。扣带回、海马旁回属边缘叶，杏仁体属基底核。"},{"q":"棘突较长，向后下方倾斜，呈叠瓦状的椎骨是","o":["寰椎","第2～6颈椎","隆椎","胸椎","腰椎"],"a":3,"e":"胸椎棘突较长，向后下方倾斜，各相邻棘突呈叠瓦状排列，与呈冠状位的关节突关节面共同限制胸椎活动。颈椎棘突短而分叉，腰椎棘突呈板状水平后伸。"},{"q":"直肠癌首先转移的淋巴结是","o":["直肠上淋巴结","闭孔淋巴结","左结肠淋巴结","腰淋巴结","腹股沟深淋巴结"],"a":0,"e":"齿状线以上的直肠淋巴管沿直肠上血管上行，首先注入直肠上淋巴结，故直肠癌多先转移至此。齿状线以下者还可流向盆底及腹股沟淋巴结。"},{"q":"穿行于右纤维三角内的是","o":["结间束","房室束","左束支","右束支","浦肯野纤维"],"a":1,"e":"房室结前端变细穿入右纤维三角形成房室束，房室束穿过右纤维三角的右上面下行，至室间隔膜部与肌部交界处离开右纤维三角。"},{"q":"躯干和四肢的意识性本体感觉传导通路中，第2级神经元发出纤维进行交叉的部位在","o":["脊髓","延髓","脑桥","中脑","背侧丘脑"],"a":1,"e":"躯干和四肢意识性本体感觉传导通路的第2级神经元为薄束核和楔束核，其发出的内弓状纤维在延髓中央管腹侧越中线交叉，形成内侧丘系交叉。"},{"q":"可分为皮质和髓质的内分泌器官是","o":["甲状腺","肾上腺","垂体","松果体","卵泡和黄体"],"a":1,"e":"肾上腺由周边的皮质和中央的髓质构成，皮质分泌盐皮质激素、糖皮质激素和性激素，髓质分泌肾上腺素和去甲肾上腺素。"},{"q":"舌咽神经不分布于","o":["咽鼓管","腮腺","鼓室","颈动脉窦","心肌"],"a":4,"e":"舌咽神经的一般内脏感觉纤维分布于咽、鼓室、咽鼓管、软腭、舌后1/3黏膜及颈动脉窦、颈动脉小球，并控制腮腺分泌。心肌由迷走神经支配。"},{"q":"关于腹膜腔，下列描述不正确的是","o":["膀胱和肾的手术可在腹膜腔外进行","网膜囊是腹膜腔的一部分","是密闭腔隙，不与外界相通","腹膜腔内仅有少量浆液","腹腔脏器的穿孔可引起急性腹膜炎"],"a":2,"e":"男性腹膜腔为封闭的腔隙，女性则借输卵管腹腔口经输卵管、子宫、阴道与外界相通，故并非绝对密闭。腔内仅有少量浆液，网膜囊属腹膜腔的一部分。"},{"q":"面神经管理","o":["面部皮肤","舌前2/3味觉","舌前2/3一般感觉","舌后1/3味觉","舌后1/3一般感觉"],"a":1,"e":"面神经的特殊内脏感觉纤维胞体位于膝神经节，其周围突经鼓索随舌神经分布于舌前2/3的味蕾，中枢突止于孤束核上部。舌后1/3味觉由舌咽神经管理。"},{"q":"肩关节的特征不包括","o":["肱骨头大","关节盂小","有关节盘","有囊外韧带","有盂唇"],"a":2,"e":"肩关节由肱骨头与关节盂构成，肱骨头大、关节盂小而浅，周缘有盂唇加深，囊外有喙肱韧带等加强，囊内无关节盘。囊内有纤维软骨关节盘的是胸锁关节。"},{"q":"骶副交感核","o":["位于S2～S4节段板层Ⅶ的外侧部","在于S1～S5节段板层Ⅶ侧部","位于T1～L4节段板层Ⅶ侧部","位于T5～L1节段板层Ⅶ侧部","是副交感节后神经元胞体所在的部位"],"a":0,"e":"骶副交感核位于脊髓S2～S4节段板层Ⅶ的外侧部，是副交感神经节前神经元胞体所在的部位，发出的纤维组成盆内脏神经。"},{"q":"可屈膝、踝关节的肌是","o":["腓肠肌","胫骨前肌","胫骨后肌","腓骨长肌","比目鱼肌"],"a":0,"e":"腓肠肌内、外侧头分别起自股骨内、外上髁后面，向下以跟腱止于跟骨结节，能屈踝关节和屈膝关节。比目鱼肌只屈踝关节。"},{"q":"关于蜗管的叙述，错误的是","o":["位于蜗螺旋管内","蜗管盘绕蜗轴两圈半","局部膜壁增厚形成壶腹嵴","和骨螺旋板一起分隔蜗螺旋管为前庭阶和鼓阶","下壁的基底膜上有螺旋器"],"a":2,"e":"蜗管位于蜗螺旋管内，盘绕蜗轴两圈半，其下壁基底膜上有螺旋器，与骨螺旋板共同将蜗螺旋管分为前庭阶和鼓阶。壶腹嵴位于膜半规管的膜壶腹壁上。"},{"q":"自脑干背面出脑的神经是","o":["动眼神经","滑车神经","面神经","副神经","舌下神经"],"a":1,"e":"滑车神经在下丘下方与上髓帆之间出脑，是唯一自脑干背侧面出脑的脑神经，其余脑神经均自脑干的腹侧或外侧出脑。"},{"q":"前尿道是指","o":["前列腺部","尿道膜部","尿道海绵体部","前列腺部、膜部","膜部、海绵体部"],"a":2,"e":"临床上将尿道前列腺部和膜部合称后尿道，穿过尿道海绵体的海绵体部称前尿道，长约12～17cm。"},{"q":"下肢深部感觉传导通路的交叉部位在","o":["脊髓前连合","脑桥臂","延髓内侧丘系交叉","中脑结合臂","间脑视交叉"],"a":2,"e":"下肢深感觉即意识性本体感觉，其第2级纤维在延髓中央管腹侧越过中线交叉，形成内侧丘系交叉，交叉后上行组成内侧丘系。"},{"q":"第二鼓膜封闭","o":["蜗窗的组织膜","前庭窗的组织膜","外耳道底的组织膜","内耳道底的组织膜","鼓室的组织膜"],"a":0,"e":"蜗窗又称圆窗，位于鼓室岬的后下方，在活体上由第二鼓膜封闭；前庭窗则由镫骨底封闭，二者同为鼓室内侧壁的重要结构。"},{"q":"黄韧带的特征不包括","o":["是椎弓间的连结","位于椎弓板之间","能限制脊柱过度前伸","参与组成椎管","由黄色弹性纤维构成"],"a":2,"e":"黄韧带连于相邻椎弓板之间，由黄色弹性纤维构成，协助围成椎管，并有限制脊柱过度前屈的作用。限制脊柱过度后伸的是前纵韧带。"},{"q":"延髓内的脑神经核","o":["脑桥核","面神经核","上橄榄核","迷走神经背核","上泌涎核"],"a":3,"e":"迷走神经背核位于延髓，属一般内脏运动（副交感）核。面神经核和上泌涎核位于脑桥，脑桥核和上橄榄核亦不属延髓内的脑神经核。"},{"q":"斜方肌麻痹时，不能做下列哪项动作","o":["充分外展肩关节","充分屈肩关节","使肩胛骨向脊柱靠近","使肩胛骨贴近胸廓","充分内收肩关节"],"a":2,"e":"斜方肌起自枕外隆凸、项韧带及全部胸椎棘突，止于锁骨外侧1/3、肩峰和肩胛冈，收缩时拉肩胛骨向脊柱靠拢，由副神经支配。麻痹后耸肩无力、肩胛骨不能内收。"},{"q":"背侧丘脑腹后内侧核接受","o":["内侧丘系","外侧丘系","三叉丘系","脊髓丘脑束","脊髓小脑束"],"a":2,"e":"腹后内侧核接受三叉丘系和孤束核发出的味觉纤维，腹后外侧核接受内侧丘系和脊髓丘系的纤维，二者发出丘脑中央辐射投射至中央后回。"},{"q":"以下关于泪器的描述，正确的是","o":["泪器属于眼球的一部分","泪器由泪腺和鼻泪管两部分组成","泪腺分泌的泪液可防止结膜干燥","泪囊为一膜性盲囊，其下端为盲端","泪点是泪小管的开口"],"a":4,"e":"泪点位于上、下睑缘近内侧端的泪乳头顶部，是泪小管的开口。泪器由泪腺和泪道组成，不属眼球结构；泪囊下端续为鼻泪管。"},{"q":"关于大肠描述正确的是","o":["长约2m","在右髂窝处从回肠而起","阑尾不属于大肠","大肠都没有系膜","包括盲肠、阑尾、结肠、直肠和肛管5部分"],"a":4,"e":"大肠全长1.5m，分盲肠、阑尾、结肠、直肠和肛管5部分，全程围绕于空、回肠周围。结肠和盲肠具有结肠带、结肠袋和肠脂垂三个特征性结构。"},{"q":"损伤后导致本体感觉丧失的纤维束","o":["薄束、楔束","脊髓丘脑束","脊髓小脑束","皮质脊髓束","红核脊髓束"],"a":0,"e":"薄束和楔束位于脊髓后索，传导同侧躯干和四肢的意识性本体感觉及精细触觉，损伤后同侧本体感觉丧失。脊髓小脑束传导非意识性本体感觉。"},{"q":"有关腰淋巴结的描述，正确的是","o":["位于腹膜前隙内","沿髂内动脉和髂外静脉排列","引流腹腔成对器官的淋巴","收纳腹股沟浅淋巴结的输出淋巴管","输出淋巴管汇合成左、右肠干"],"a":2,"e":"腰淋巴结位于腹后壁，沿腹主动脉和下腔静脉排列，引流腹后壁深层结构和腹腔成对器官的淋巴，输出淋巴管汇合成左、右腰干。"},{"q":"胞质中含有GFAP（胶质纤维酸性蛋白）的胶质细胞是","o":["施万细胞","室管膜细胞","小胶质细胞","少突胶质细胞","星形胶质细胞"],"a":4,"e":"星形胶质细胞胞质内含由胶质纤维酸性蛋白（GFAP）组成的胶质丝，GFAP仅存在于该细胞胞体中，可作为鉴定星形胶质细胞的特异性标志物。"},{"q":"心的下缘由哪部分构成","o":["左心室和心尖","右心室和心尖","左心室和右心室","左心室和左心耳","右心室和右心耳"],"a":1,"e":"心的下缘即锐缘，介于膈面与胸肋面之间，接近水平位，由右心室和心尖构成。膈面则大部分由左心室构成。"},{"q":"躯干和四肢的非意识性本体感觉传导通路的第2级神经元位于","o":["脊髓的胶状质","脊髓的后角固有核","脊髓的胸核和腰骶膨大第Ⅴ～Ⅶ外侧部","延髓的楔束核","延髓的薄束核"],"a":2,"e":"非意识性本体感觉传导通路的第2级神经元胞体位于C8～L2节段胸核和腰骶膨大第Ⅴ～Ⅶ层外侧部，前者发出脊髓小脑后束，后者发出脊髓小脑前束。"},{"q":"关于肾的构造，错误的描述是","o":["肾实质可分浅层的皮质和深层的髓质两部分","肾髓质由许多小的管道组成","肾锥体基底朝向皮质，尖朝向肾窦","肾乳头开口于肾盂","肾锥体之间的皮质为肾柱"],"a":3,"e":"肾乳头突入肾小盏，其顶端乳头孔将终尿排入肾小盏，而非直接开口于肾盂。肾实质分皮质与髓质，肾锥体尖朝向肾窦，锥体间的皮质为肾柱。"},{"q":"展神经","o":["经眶上裂入眶","支配上直肌","主干损伤眼外斜视","含有感觉纤维","含有副交感纤维"],"a":0,"e":"展神经为纯运动性脑神经，穿海绵窦后经眶上裂入眶，支配外直肌。损伤后眼球不能外展，出现内斜视。"},{"q":"脑干内的副交感神经核","o":["疑核、动眼神经副核、上泌涎核、下泌涎核","迷走神经背核、动眼神经核、上泌涎核、下泌涎核","动眼神经副核、孤束核、泌涎核、迷走神经背核","动眼神经副核、上泌涎核、下泌涎核、迷走神经背核","动眼神经副核、面神经核、疑核、副神经核"],"a":3,"e":"脑干内的一般内脏运动核即副交感核共4对，为动眼神经副核、上泌涎核、下泌涎核和迷走神经背核，支配头颈胸腹的平滑肌、心肌和腺体。"},{"q":"关于尺动脉的叙述，错误的是","o":["该动脉在平桡骨颈高度处发自肱动脉","其主要分支为骨间总动脉和掌深支","其体表投影为：自肘窝中点稍下至豌豆骨桡侧","其压迫止血部位为：在腕部的尺侧腕屈肌的内侧","压迫该动脉其止血范围为：整个前臂和手部"],"a":4,"e":"尺动脉的压迫止血范围仅为部分手部，并非整个前臂和手部。该动脉在平桡骨颈高度发自肱动脉，主要分支为骨间总动脉和掌深支。"},{"q":"延髓前正中裂两旁的隆起的外侧是","o":["锥体","橄榄","薄束结节","楔束结节","听结节"],"a":1,"e":"延髓前正中裂两侧为锥体，锥体背外侧的卵圆形隆起为橄榄，内含下橄榄核。薄束结节和楔束结节位于延髓背侧下部。"},{"q":"舌下神经核","o":["接受双侧皮质核束的支配","发出舌下神经经橄榄背外侧出脑","管理舌的感觉和运动","受损后伸舌时舌尖偏向健侧","受损后舌肌萎缩"],"a":4,"e":"舌下神经核为躯体运动核，仅接受对侧皮质核束支配，其纤维经延髓前外侧沟出脑，支配舌内肌和大部分舌外肌。核下性损伤出现患侧舌肌瘫痪、萎缩，伸舌偏向患侧。"},{"q":"躯干和四肢的非意识性本体感觉传导通路由多少级神经元组成","o":["1级","2级","3级","4级","5级"],"a":1,"e":"非意识性本体感觉传导通路传入小脑，由2级神经元组成；意识性本体感觉和精细触觉传导通路则由3级神经元组成。"},{"q":"支配心脏的副交感神经来自","o":["舌咽神经","迷走神经","副神经","膈神经","三叉神经"],"a":1,"e":"心脏的副交感节前纤维来自延髓的迷走神经背核和疑核，经迷走神经心支至心丛内的心神经节换元，节后纤维分布于心，使心率减慢。"},{"q":"四分法为解剖学常用的纵隔区分法。中纵隔位于","o":["上纵隔内","上、下纵隔之间","前纵隔内","前、后纵隔之间","后纵隔内"],"a":3,"e":"纵隔四分法以胸骨角平面分上、下纵隔，下纵隔再以心包为界分前、中、后三部，中纵隔位于前、后纵隔之间，容纳心及出入心的大血管。"},{"q":"第四脑室位于","o":["脑桥与中脑之间","延髓、脑桥与小脑之间","脑桥、中脑与小脑之间","中脑、小脑与延髓之间","中脑、间脑与小脑之间"],"a":1,"e":"第四脑室位于延髓、脑桥与小脑之间，呈四棱锥形，内容脑脊液，经第四脑室正中孔和两个外侧孔与蛛网膜下隙相通。"},{"q":"舌咽神经分布的区域不包括","o":["舌前2/3","咽壁","鼓室","颈动脉窦","颈动脉小球"],"a":0,"e":"舌咽神经的一般内脏感觉纤维分布于咽、鼓室、咽鼓管、软腭、舌后1/3黏膜及颈动脉窦、颈动脉小球，舌前2/3的一般感觉由舌神经管理。"},{"q":"项韧带的特征不包括","o":["续于棘上韧带","向前附着于颈椎棘突","由弹性纤维构成","向上附着于人字缝","向下达第7颈椎棘突"],"a":3,"e":"项韧带向上附着于枕外隆凸及枕外嵴，而非人字缝；向下达第7颈椎棘突并续于棘上韧带，为双层致密弹性纤维隔，供颈部肌附着。"},{"q":"腹外斜肌腱膜形成的结构不包括","o":["耻骨梳韧带","腹股沟管浅环","腹股沟镰","腹白线","腔隙韧带"],"a":2,"e":"腹股沟镰由腹内斜肌腱膜与腹横肌腱膜结合而成，不属腹外斜肌腱膜形成的结构。腹外斜肌腱膜形成腹股沟管浅环、腹白线、腔隙韧带和耻骨梳韧带。"},{"q":"外侧丘系的纤维束走行及功能的描述，正确的是","o":["经延髓、脑桥和中脑中线的外侧上行","终止于上丘","终止于外侧膝状体","大部分纤维终止于下丘中央核","仅传导对侧耳的听觉信息"],"a":3,"e":"外侧丘系由对侧交叉及同侧未交叉的纤维组成，在脑桥行于被盖腹外侧，进入中脑后大部分纤维终止于下丘中央核，小部分止于内侧膝状体。"},{"q":"经眶上裂进出眶的神经是","o":["视神经","嗅神经","滑车神经","上颌神经","滑车上神经"],"a":2,"e":"滑车神经穿海绵窦外侧壁后经眶上裂入眶，支配上斜肌。视神经经视神经管入眶，上颌神经经圆孔出颅。"},{"q":"关于窦房结正确的描述是","o":["内脏神经的作用决定其兴奋","借房室束连于房室结","是心脏的正常起搏点","位于房间隔下部右侧心内膜下","属于特殊神经组织"],"a":2,"e":"窦房结是心的正常起搏点，位于上腔静脉与右心房交界处界沟上1/3的心外膜深面，由特殊心肌细胞构成，并非神经组织。"},{"q":"以下具有吞噬能力的神经胶质细胞为","o":["施万细胞","室管膜细胞","小胶质细胞","少突胶质细胞","星形胶质细胞"],"a":2,"e":"小胶质细胞来源于中胚层的单核巨噬细胞，脑组织炎症或损伤时被激活为阿米巴样细胞，游走至损伤处吞噬和清除坏死组织。"},{"q":"下列关于肺动脉干的描述正确的是","o":["起自左心房","位于心包内","起始处位于主动脉根的后方","由左前下方行向右后上方","运输动脉血"],"a":1,"e":"肺动脉干位于心包内，起自右心室，在主动脉前方行向左后上方，至主动脉弓下方分为左、右肺动脉，输送的是静脉血。"},{"q":"三角肌的形态结构特征包括","o":["位于臂部","受桡神经支配","使肩关节外展","只起于肩胛骨","止于肱骨桡神经沟下方"],"a":2,"e":"三角肌起自锁骨外侧1/3、肩峰和肩胛冈，止于肱骨三角肌粗隆，主要作用为使肩关节外展，由腋神经支配，位于肩部而非臂部。"},{"q":"属于听觉感受器的结构是","o":["椭圆囊斑","球囊斑","壶腹嵴","螺旋器","膜壶腹"],"a":3,"e":"螺旋器又称Corti器，位于蜗管下壁的基底膜上，是听觉感受器。椭圆囊斑、球囊斑和壶腹嵴均为位置觉感受器。"},{"q":"患者，女。乳房上部有一个结节，请问该处的淋巴管最容易注入的是","o":["胸肌淋巴结","膈上淋巴结","尖淋巴结","胸骨旁淋巴结","锁骨下淋巴结"],"a":2,"e":"乳房上部的淋巴管沿胸大肌下缘向外上方走行，注入腋窝的尖淋巴结，尖淋巴结输出管合成锁骨下干。乳房内侧部的淋巴注入胸骨旁淋巴结。"},{"q":"下述哪个不是髂内动脉的分支","o":["子宫动脉","膀胱下动脉","直肠下动脉","卵巢动脉","阴部内动脉"],"a":3,"e":"卵巢动脉起自腹主动脉，经卵巢悬韧带下行入盆腔，不属髂内动脉分支。子宫动脉、膀胱下动脉、直肠下动脉和阴部内动脉均由髂内动脉发出。"},{"q":"外侧膝状体接受","o":["深感觉的传导通路纤维","痛、温觉的传导通路纤维","触觉的传导通路纤维","视觉的传导通路纤维","听觉的传导通路纤维"],"a":3,"e":"外侧膝状体是视觉传导通路在丘脑的中继站，接受视束纤维，发出视辐射投射至枕叶视区。内侧膝状体则接受听觉纤维。"},{"q":"脑干内的特殊内脏运动核支配","o":["咀嚼肌、表情肌、咽喉肌","舌肌","心肌","平滑肌","眼球外肌"],"a":0,"e":"特殊内脏运动核包括三叉神经运动核、面神经核、疑核和副神经核，支配由鳃弓衍化的咀嚼肌、表情肌、咽喉肌及胸锁乳突肌、斜方肌。"},{"q":"关于肝门静脉或肝门静脉系的特点，正确的描述是","o":["静脉压低于下腔静脉","静脉高压时很少发生食管静脉丛曲张","肝门静脉因含有许多瓣膜而扩张","静脉高压可引起脐周静脉网曲张和痔","血流少于肝固有动脉"],"a":3,"e":"肝门静脉系与腔静脉系通过食管静脉丛、直肠静脉丛和脐周静脉网相交通，门静脉高压时可致脐周静脉网曲张呈海蛇头样，并可引起痔。"},{"q":"关于喉返神经的叙述，错误的是","o":["右侧勾绕腋动脉","左侧勾绕主动脉弓","上行于气管食管沟内","入喉内改名为喉下神经","与甲状腺下动脉交叉"],"a":0,"e":"右喉返神经勾绕右锁骨下动脉，左喉返神经勾绕主动脉弓，二者均行于气管食管沟内，与甲状腺下动脉交叉，入喉后改称喉下神经。"},{"q":"一患者入院检查后发现对侧偏身躯体深浅感觉缺失，余无异常发现，该患者损伤的什么结构","o":["丘脑中央辐射","丘脑前辐射","额桥束","听辐射","视辐射"],"a":0,"e":"丘脑中央辐射是丘脑腹后核至中央后回的纤维束，经内囊后肢，传递全身皮肤、肌和关节的感觉，损伤后出现对侧偏身深浅感觉缺失。"},{"q":"关于喉的描述，正确的是","o":["上界为甲状软骨上缘","下界为环状软骨下缘","成人位于第2～4 颈椎前方","前方有甲状腺峡","后方为食管"],"a":1,"e":"喉的上界为会厌上缘，下界为环状软骨下缘，成人喉位于第3～6颈椎前方，前有皮肤、筋膜和舌下肌群，后方为喉咽。甲状腺峡位于第2～4气管软骨环前方。"},{"q":"短骨不包括","o":["豌豆骨","指骨","大多角骨","足舟骨","骰骨"],"a":1,"e":"指骨属长骨，共14块，每节分底、体和滑车。腕骨和跗骨属短骨，豌豆骨、大多角骨、足舟骨和骰骨均为短骨。"},{"q":"锁骨的形态结构特征不包括","o":["全长可在体表扪及","分为一体两端","内侧端粗大为胸骨端","外侧端扁平为肩峰端","其内侧1/3段凸向前"],"a":4,"e":"锁骨内侧2/3凸向前、呈三棱形，外侧1/3凸向后、呈扁平形。锁骨全长可在体表扪及，内侧端为胸骨端、外侧端为肩峰端。"},{"q":"关于大唾液腺的叙述，错误的是","o":["腮腺位于外耳道下方","腮腺管开口于平对上颌第2磨牙牙冠的颊黏膜上","下颌下腺管开口于舌下阜","舌下腺大管开口于舌下襞","舌下腺较小"],"a":3,"e":"舌下腺大管与下颌下腺管共同开口于舌下阜，舌下腺小管才开口于舌下襞表面。腮腺管开口于平对上颌第2磨牙牙冠的颊黏膜。"},{"q":"含有心传导系右束支的结构是","o":["界嵴","室上嵴","室间隔膜部","隔缘肉柱","乳头肌"],"a":3,"e":"隔缘肉柱又称节制索，横过右心室腔，房室束的右束支及供应前乳头肌的血管经此到达前乳头肌，手术时应防止损伤以免发生右束支传导阻滞。"},{"q":"生成雄激素的结构是","o":["精曲小管上皮","睾丸网","睾丸间质细胞","精直小管","附睾管"],"a":2,"e":"雄激素由生精小管之间的睾丸间质细胞分泌，可促进精子发生、激发并维持男性第二性征。精曲小管上皮主司生精。"},{"q":"关于卵巢的描述，正确的是","o":["卵巢位置固定主要靠卵巢窝","卵巢悬韧带又称为卵巢子宫索","上端有卵巢固有韧带连于子宫","前缘借卵巢系膜连于子宫阔韧带","下端又称为输卵管端"],"a":3,"e":"卵巢前缘借卵巢系膜连于子宫阔韧带，称卵巢系膜缘，其中部为卵巢门，有血管神经出入。卵巢悬韧带内含卵巢血管，卵巢固有韧带连于子宫底。"},{"q":"头面部的触觉传导至","o":["三叉神经脊束核","三叉神经中脑核","三叉神经脑桥核","脊神经节","三叉神经运动核"],"a":2,"e":"头面部触压觉的初级纤维主要终止于三叉神经脑桥核，痛温觉纤维止于三叉神经脊束核。第2级纤维交叉后组成三叉丘系，终于腹后内侧核。"},{"q":"肩胛骨的形态结构特征不包括","o":["三角形扁的不规则骨","贴于胸廓的后外侧面","介于第2～7肋骨之间","腹侧面或肋面称为肩胛下窝","可分为二面、三缘和三个角"],"a":0,"e":"肩胛骨为三角形扁骨，贴于胸廓后外面，介于第2至第7肋之间，分二面、三缘和三个角，其肋面即肩胛下窝，不属不规则骨。"},{"q":"男性生殖系统中负责分泌雄性激素的是","o":["睾丸间质细胞","精曲小管","精囊","白膜","前列腺"],"a":0,"e":"睾丸间质细胞位于生精小管之间的结缔组织内，分泌雄激素。精曲小管产生精子，前列腺和精囊分泌精浆成分。"},{"q":"关于桡动脉的叙述，错误的是","o":["该动脉在平桡骨颈高度处发自肱动脉","其主要分支是掌浅支和拇主要动脉","其体表投影为自肘窝中点稍下至桡骨茎突的连线","其压迫止血部位在桡骨茎突的上方，肱桡肌腱的内侧","压迫该动脉其止血范围为：整个前臂和手部"],"a":4,"e":"桡动脉的压迫止血范围仅为部分手部，不能覆盖整个前臂和手部。该动脉在平桡骨颈高度发自肱动脉，主要分支为掌浅支和拇主要动脉。"},{"q":"眼球壁中膜由前向后包括","o":["虹膜、脉络膜、视网膜","瞳孔、虹膜、睫状体","虹膜、睫状体、脉络膜","瞳孔、睫状体、脉络膜","脉络膜、睫状体、虹膜"],"a":2,"e":"眼球壁中膜即血管膜，由前向后分为虹膜、睫状体和脉络膜三部分。视网膜属内膜，瞳孔是虹膜中央的孔。"},{"q":"关于内囊，正确的选项是","o":["位于丘脑、尾状核和豆状核之间的白质板","位于豆状核、丘脑和尾状核之间的白质板","位于豆状核、尾状核和丘脑之间的白质板","位于豆状核、丘脑、尾状核之间的白质板","位于丘脑、尾状核、豆状核和屏状核之间的白质板"],"a":0,"e":"官方题库缺失图片"},{"q":"使足做背屈和内翻运动的肌是","o":["小腿三头肌","胫骨前肌","趾长伸肌","腓骨长肌","腓骨短肌"],"a":1,"e":"胫骨前肌起自胫骨上端外侧面，止于内侧楔骨内侧面和第1跖骨底，作用是伸踝关节（背屈）并使足内翻。腓骨长肌则使足跖屈和外翻。"},{"q":"通过心脏右纤维三角的结构是","o":["房室束","左束支","右束支","结间束","窦房结支"],"a":0,"e":"房室结前端变细穿入右纤维三角形成房室束，房室束穿过右纤维三角的右上面，至室间隔膜部与肌部交界处离开，随后分为左、右束支。"},{"q":"关于腘淋巴结的叙述，正确的是","o":["沿大隐静脉末端和腘血管排列","注入腹股沟浅淋巴结","输出淋巴管沿股神经上行","引流小腿深层结构的淋巴","分为浅、中、深三群"],"a":3,"e":"腘淋巴结位于腘窝，沿腘血管排列，分浅、深两群，引流小腿深部结构和足外侧缘等处的淋巴，输出管注入腹股沟深淋巴结。"},{"q":"关于脊髓小脑说法正确的是","o":["因传出纤维主要终止于脊髓而得名","由绒球和小结构成","参与随意运动的调控","种系进化上最早出现","参与肌张力的调节"],"a":4,"e":"脊髓小脑即旧小脑，主要接受脊髓小脑前、后束的本体感觉冲动，传出纤维经顶核、中间核中继后影响脊髓前角运动神经元，以调节肌张力。"},{"q":"骨骼肌在受到外力牵拉伸长时，引起其收缩的反射属于","o":["内脏躯体反射","牵张反射","内脏反射","屈曲反射","躯体内脏反射"],"a":1,"e":"牵张反射指有神经支配的骨骼肌受外力牵拉伸长时引起同一肌肉收缩的反射，肌梭为感受器，冲动经脊神经后根兴奋α-运动神经元。"},{"q":"第2颈椎的特征不包括","o":["又名枢椎","有椎体","与寰椎前弓后面的齿突凹相关节","体积最大","向上伸出齿突"],"a":3,"e":"枢椎即第2颈椎，有椎体并向上伸出齿突，与寰椎前弓后面的齿突凹相关节。颈椎中其体积并不最大，椎体自第2颈椎向下逐渐增大。"},{"q":"蚓状肌对第2～5指的作用是","o":["屈掌指关节和屈指骨间关节","伸掌指关节和屈指骨间关节","屈掌指关节和伸指骨间关节","伸掌指关节和伸指骨间关节","屈近侧指间关节和伸远侧指间关节"],"a":2,"e":"蚓状肌起自指深屈肌腱，止于第2～5指的指背腱膜，收缩时屈掌指关节并伸指骨间关节，与骨间肌协同完成精细动作。"},{"q":"海绵窦直接注入","o":["上矢状窦","下矢状窦","直窦","岩上窦","乙状窦"],"a":3,"e":"海绵窦向后外经岩上窦和岩下窦引流，岩上窦将其血液导入横窦，岩下窦导入乙状窦或颈内静脉。海绵窦不直接注入上矢状窦或直窦。"},{"q":"成人子宫正常的姿势是","o":["前倾前屈","前倾后屈","后倾前屈","后倾后屈","前倾侧屈"],"a":0,"e":"成人子宫呈轻度前倾前屈位，即子宫体伏于膀胱上面、子宫与阴道间形成向前开放的角，由子宫阔韧带、圆韧带、主韧带和骶子宫韧带共同维持。"},{"q":"支配泪腺分泌的神经是","o":["面神经","舌咽神经","副神经","三叉神经","迷走神经"],"a":0,"e":"泪腺的副交感分泌纤维来自面神经，经岩大神经至翼腭神经节换元，节后纤维经颧神经、泪腺神经达泪腺。腮腺分泌由舌咽神经管理。"},{"q":"颅腔内前庭蜗神经瘤最容易压迫的神经是","o":["面神经","三叉神经","展神经","迷走神经","舌下神经"],"a":0,"e":"前庭蜗神经根位于脑桥小脑三角，该处肿瘤最易压迫相邻的面神经，引起同侧面肌瘫痪，并可累及三叉神经、舌咽神经和迷走神经。"},{"q":"梨状隐窝位于","o":["鼻咽部","口咽部","喉咽部","固有口腔","咽隐窝的两侧"],"a":2,"e":"梨状隐窝位于喉咽部，在喉口两侧各有一深窝，常为异物滞留之处。鼻咽部两侧的深窝为咽隐窝，是鼻咽癌的好发部位。"},{"q":"使足做跖屈和外翻动作的肌是","o":["腓肠肌","趾长屈肌","胫骨后肌","腓骨长肌","比目鱼肌"],"a":3,"e":"腓骨长肌起自腓骨外侧面，肌腱经外踝后方绕至足底，止于内侧楔骨和第1跖骨底，作用为使足跖屈和外翻。腓肠肌只屈踝关节。"},{"q":"属于膜迷路的是","o":["椭圆囊、球囊、耳蜗","椭圆囊、膜半规管、蜗管","前庭、膜半规管、耳蜗","前庭、膜半规管、蜗管","前庭、骨半规管、耳蜗"],"a":1,"e":"膜迷路由椭圆囊和球囊、膜半规管和蜗管三部分组成，其内充满内淋巴。前庭、骨半规管和耳蜗属骨迷路。"},{"q":"关于角膜的叙述，错误的是","o":["角膜占纤维膜的后1/6","营养物质来源于毛细血管、泪液和房水","无血管，富有感觉神经末梢","角膜具有屈光作用","无色透明且富有弹性"],"a":0,"e":"角膜占眼球纤维膜的前1/6，巩膜占后5/6。角膜无色透明、富有弹性、无血管而富有感觉神经末梢，具有屈光作用，营养来自周围毛细血管、泪液和房水。"},{"q":"关于主动脉小球描述正确的是","o":["在主动脉弓下方，位于动脉韧带内","属于化学感受器","属于压力感受器","位于主动脉弓的壁内","位于主动脉弓的前方"],"a":1,"e":"主动脉小球位于主动脉弓下方、靠近动脉韧带处，为2～3个粟粒样小体，属化学感受器，感受血液二氧化碳分压、氧分压和氢离子浓度的变化。"},{"q":"躯干和四肢的意识性本体感觉传导通路中的第2级神经元胞体位于","o":["三叉神经节内","脊髓后角固有核","脊髓侧角","延髓薄束核和楔束核","延髓的下橄榄核"],"a":3,"e":"意识性本体感觉传导通路的第1级神经元在脊神经节，第2级神经元胞体位于延髓的薄束核和楔束核，第3级神经元胞体在背侧丘脑腹后外侧核。"},{"q":"骨的描述，不正确的是","o":["是一种器官","成人有206块","主要有骨组织构成","锁骨属于躯干骨","指骨属于长骨"],"a":3,"e":"锁骨属上肢带骨，不属躯干骨；躯干骨包括椎骨、骶骨、尾骨、胸骨和肋。骨是器官，成人共206块，指骨属长骨。"},{"q":"关于内侧丘系在脑干各部内位置的叙述，错误的是","o":["发出该束神经纤维的细胞体位于同侧薄束核和楔束核内","在延髓，内侧丘系位于中线和下橄榄核间，锥体背侧","在脑桥，内侧丘系经过斜方体","在中脑，内侧丘系纤维在上丘高度位于红核背外侧","内侧丘系向上终止于同侧的背侧丘脑腹后外侧核"],"a":0,"e":"内侧丘系由对侧薄束核和楔束核发出的二级纤维交叉后形成，故其纤维胞体位于对侧而非同侧。该系在延髓居锥体背侧，在脑桥穿斜方体，向上止于腹后外侧核。"},{"q":"不属于颈内动脉行程分部的是","o":["颈部","岩部","海绵窦部","前床突上部","前床突下部"],"a":4,"e":"颈内动脉按行程分为颈部、岩部、海绵窦部和前床突上部四部，其中后两部合称虹吸部。前床突下部不属其分部。"},{"q":"脑干由哪些结构组成","o":["由丘脑、中脑和脑桥组成","由间脑、中脑和脑桥组成","由间脑、中脑和延髓组成","由中脑、脑桥和延髓组成","由间脑、脑桥和延髓组成"],"a":3,"e":"脑干自下而上由延髓、脑桥和中脑三部分组成，位于颅后窝前部，上接间脑，下续脊髓。间脑不属脑干的组成部分。"},{"q":"不属于肝蒂的结构","o":["肝圆韧带","肝固有动脉左、右支","肝门静脉的左、右支","肝的神经","肝的淋巴管"],"a":0,"e":"肝蒂为出入肝门诸结构的总称，含肝固有动脉左右支、肝门静脉左右支、肝管、肝的神经和淋巴管。肝圆韧带位于肝圆韧带裂内，由脐静脉闭锁而成。"},{"q":"具有伸膝关节作用的肌","o":["缝匠肌","半腱肌","半膜肌","股二头肌","股四头肌"],"a":4,"e":"股四头肌起自髂前下棘和股骨粗线等，经髌韧带止于胫骨粗隆，能屈髋关节并伸膝关节。缝匠肌、半腱肌、半膜肌和股二头肌均屈膝。"},{"q":"左心房可见到的结构是","o":["上、下腔静脉口","冠状窦口","卵圆窝","界嵴","二尖瓣口"],"a":4,"e":"左心房经左房室口与左心室相通，该口周缘附有二尖瓣，故二尖瓣口是左心房内可见的结构。上、下腔静脉口、冠状窦口和界嵴均属右心房，卵圆窝位于房间隔的右心房侧。"},{"q":"不穿过眶上裂的神经是","o":["眼神经","视神经","动眼神经","滑车神经","展神经"],"a":1,"e":"视神经经视神经管入颅，不经过眶上裂。动眼神经、滑车神经、展神经以及三叉神经的眼神经均经眶上裂入眶。"},{"q":"在腕骨，从桡侧至尺侧，近侧列的腕骨是","o":["月骨、手舟骨、三角骨、豌豆骨","三角骨、月骨、手舟骨、豌豆骨","豌豆骨、月骨、三角骨、手舟骨","手舟骨、月骨、大多角骨、豌豆骨","手舟骨、月骨、三角骨、豌豆骨"],"a":4,"e":"近侧列自桡侧向尺侧依次为手舟骨、月骨、三角骨和豌豆骨，远侧列才是大多角骨、小多角骨、头状骨和钩骨。"},{"q":"关于颈内动脉正确的描述是","o":["在颈部发出舌动脉","其颈部位居颈外动脉的内侧","供应脑的前2/3","伴行于颈内静脉外侧","起始处的膨大称颈动脉小球"],"a":2,"e":"颈内动脉供应大脑半球前2/3及部分间脑，发出舌动脉等面颈部分支的是颈外动脉。颈内动脉在颈部位于颈外动脉后外侧，起始部膨大为颈动脉窦而非颈动脉小球。"},{"q":"大脑动脉环由下列动脉组成","o":["两侧大脑前动脉、两侧颈内动脉、两侧大脑后动脉、前交通动脉、后交通动脉","两侧大脑前动脉、两侧大脑后动脉、前交通动脉、后交通动脉","两侧大脑前动脉、两侧大脑后动脉、前交通动脉、两侧基底动脉","两侧大脑前动脉、两侧颈内动脉、两侧基底动脉、前交通动脉","两侧大脑前动脉、两侧颈内动脉、椎动脉、后交通动脉"],"a":0,"e":"大脑动脉环由两侧大脑前动脉起始段、两侧颈内动脉末段、两侧大脑后动脉以及前、后交通动脉共同围成，位于蝶鞍上方，环绕视交叉、灰结节和乳头体。"},{"q":"关于固有鼻腔，描述正确的是","o":["顶部的鼻黏膜有嗅细胞","中鼻甲的鼻黏膜有嗅细胞","下鼻道的鼻黏膜有嗅细胞","内壁有鼻毛","内壁有皮脂腺"],"a":0,"e":"嗅区位于上鼻甲及其相对的鼻中隔和二者上方的鼻腔顶部，富含嗅细胞。中鼻甲、下鼻道属呼吸区，鼻毛和皮脂腺见于鼻前庭的皮肤部。"},{"q":"关于左心室正确的记述是","o":["入口周缘有三尖瓣","左上部为动脉圆锥","流出道与肺动脉口相延续","前内侧部为主动脉前庭","内有隔缘肉柱"],"a":3,"e":"左心室流出道即主动脉前庭，位于左心室前内侧部，由室间隔上部和二尖瓣前尖围成。三尖瓣、动脉圆锥和隔缘肉柱均属右心室，肺动脉口与右心室流出道相续。"},{"q":"关于颈总动脉和颈外动脉的叙述，错误的是","o":["右颈总动脉发自主动脉弓，左颈总动脉起自头臂干","颈总动脉的分支有颈内动脉和颈外动脉","其体表投影为：自胸锁关节至耳屏稍前下方作一连线，甲状软骨上缘以上为颈外动脉，以下为颈总动脉","其压迫止血部位为：在环状软骨弓的侧方，可摸到颈总动脉搏动，将动脉压向后内侧的第6颈椎横突上","压迫该动脉其止血范围为头面部"],"a":0,"e":"左颈总动脉起自主动脉弓，右颈总动脉起自头臂干，该项将二者颠倒。颈总动脉在甲状软骨上缘分为颈内、颈外动脉，压迫其可暂时止住头面部出血。"},{"q":"腹部的动脉","o":["脏支分为成对和不成对两种","成对脏支只有肾动脉和睾丸动脉","阑尾动脉发自肠系膜下动脉","脾动脉是肠系膜上动脉的分支","胃网膜左动脉是胃十二指肠动脉的分支"],"a":0,"e":"腹主动脉脏支按是否成对分为两类：成对的有肾上腺中动脉、肾动脉和睾丸（卵巢）动脉，不成对的有腹腔干、肠系膜上动脉和肠系膜下动脉。阑尾动脉发自回结肠动脉，脾动脉发自腹腔干。"},{"q":"收缩时，可在颧弓下方摸到坚硬的条状隆起的肌是","o":["颞肌后束","二腹肌前腹","翼内肌浅头","咬肌","翼外肌"],"a":3,"e":"咬肌起自颧弓下缘及其内面，止于下颌支外面，牙咬紧时在颧弓下方可触及其坚硬条状隆起，是重要肌性标志。颞肌位于颧弓上方，二腹肌前腹在下颌骨下缘内侧。"},{"q":"不属于下丘脑的结构是","o":["乳头体","灰结节","漏斗","视交叉","外侧膝状体"],"a":4,"e":"外侧膝状体属后丘脑，是视束的终止核和视觉传导通路的中继站。下丘脑包括视交叉、灰结节、漏斗和乳头体等结构。"},{"q":"喉返神经不支配下列何结构","o":["环杓后肌","环杓侧肌","环甲肌","杓斜肌","杓横肌"],"a":2,"e":"环甲肌是唯一的喉外肌，由喉上神经喉外支支配，收缩时紧张并拉长声带。环杓后肌、环杓侧肌、杓斜肌和杓横肌等喉内肌均由喉返神经支配。"},{"q":"内耳的结构不包括","o":["前庭","耳蜗","半规管","内耳道","内淋巴"],"a":3,"e":"内耳由骨迷路和膜迷路组成，骨迷路包括前庭、骨半规管和耳蜗，膜迷路内含内淋巴。内耳道是颞骨岩部内的骨性管道，有前庭蜗神经、面神经和迷路动脉穿行，不属内耳结构。"},{"q":"与喉直接相连通的结构是","o":["鼻咽","口咽","喉咽","鼻腔","口腔"],"a":2,"e":"喉口通喉咽部，喉以环状软骨气管韧带连于气管，故与喉直接相通的是喉咽。鼻咽、口咽分别经咽鼓管和咽峡通鼻腔、口腔，不与喉腔直接相连。"},{"q":"枢椎是","o":["第1颈椎","第2颈椎","第7颈椎","胸椎","腰椎"],"a":1,"e":"第2颈椎椎体向上伸出齿突，与寰椎前弓后面的齿突凹相关节，称枢椎。第1颈椎无椎体和棘突，称寰椎；第7颈椎棘突长而不分叉，称隆椎。"},{"q":"支配臂肌前群的神经是","o":["正中神经","桡神经","尺神经","腋神经","肌皮神经"],"a":4,"e":"臂肌前群由肌皮神经支配，该神经自臂丛外侧束发出后斜穿喙肱肌，分支支配喙肱肌、肱二头肌和肱肌。正中神经、尺神经支配前臂前群肌，桡神经支配臂后群肌。"},{"q":"关于阴道穹的描述，正确的是","o":["上部与子宫颈阴道部之间环行的凹陷称阴道前庭","阴道穹可分为互不连通的4部","以阴道穹前部最深","阴道穹后部与膀胱子宫陷凹相邻仅隔阴道壁和腹膜","直肠子宫陷凹积液时，可经阴道穹后部进行穿刺"],"a":4,"e":"阴道穹后部最深，仅隔阴道壁和一层腹膜与直肠子宫陷凹相邻，该陷凹积液时可经此穿刺引流。阴道穹四部彼此连通，阴道前庭是阴道口周围的区域。"},{"q":"子宫淋巴管注入的淋巴结是","o":["髂内淋巴结","腰淋巴结","肠系膜上淋巴结","髂外淋巴结","腹股沟深淋巴结"],"a":0,"e":"子宫颈和子宫体下部的淋巴管主要注入髂内淋巴结及闭孔淋巴结，子宫底和体上部沿卵巢血管注入腰淋巴结。肠系膜上淋巴结收纳小肠和右半结肠的淋巴。"},{"q":"下列关于前列腺的描述，正确的是","o":["由平滑肌构成","是成对的中空性器官","呈尖朝上、底朝下","体后面有纵行的前列腺沟","活体直肠指诊，触摸不到前列腺"],"a":3,"e":"前列腺体后面平坦，正中有一纵行浅沟称前列腺沟，活体直肠指诊可触及，腺体肥大时该沟变浅或消失。前列腺是单一实质性腺体，底朝上、尖朝下。"},{"q":"隆椎就是","o":["第1颈椎","第2颈椎","第4颈椎","第6颈椎","第7颈椎"],"a":4,"e":"第7颈椎棘突长、末端不分叉，活体易于触及，是计数椎骨序数的标志，故名隆椎。寰椎为第1颈椎，枢椎为第2颈椎。"},{"q":"临床上行冠状动脉造影术一般首选哪条动脉为入口","o":["面动脉","颈总动脉","肱动脉","颈外动脉","尺动脉"],"a":2,"e":"经上肢动脉入路时多取肱动脉，其在肱二头肌内侧沟内位置表浅、管径较粗，可容纳造影导管且便于压迫止血。面动脉和颈外动脉属头颈部血管，不能到达心。"},{"q":"可牵拉下颌骨向前下，并作侧方运动的肌是","o":["翼外肌","颞肌","翼内肌","咬肌","二腹肌"],"a":0,"e":"翼外肌起自蝶骨大翼下面和翼突外侧面，止于下颌颈，两侧同时收缩使下颌骨前伸并张口，单侧收缩使下颌骨移向对侧。颞肌、咬肌和翼内肌均为闭口肌。"},{"q":"关于解剖学姿势的描述，错误的是","o":["身体直立","上肢自然下垂于躯干两侧","两眼向正前方平视","手掌向内侧","足尖向前"],"a":3,"e":"解剖学姿势要求双上肢下垂于躯干两侧、掌心向前，而非手掌向内。身体直立、两眼平视正前方、两足并拢足尖向前均符合标准姿势。"},{"q":"关于右淋巴导管的描述，正确的是","o":["接受右支气管纵隔干","注入颈外静脉","接受尖淋巴结的输出淋巴管","引流全身3/4部位的淋巴","接受Virchow淋巴结的输出淋巴管"],"a":0,"e":"右淋巴导管由右颈干、右锁骨下干和右支气管纵隔干汇合而成，注入右静脉角，仅引流全身右上1/4的淋巴。引流全身约3/4淋巴并接受左支气管纵隔干的是胸导管。"},{"q":"背阔肌受哪个神经支配","o":["胸长神经","胸背神经","副神经","腋神经","肩胛上神经"],"a":1,"e":"背阔肌由胸背神经支配，该神经发自臂丛后束，沿肩胛骨外侧缘伴肩胛下血管下行。胸长神经支配前锯肌，副神经支配斜方肌和胸锁乳突肌。"},{"q":"与面神经有关的核团是","o":["三叉神经运动核","下泌涎核","孤束核","疑核","副神经核"],"a":2,"e":"面神经的特殊内脏感觉纤维传导舌前2/3味觉，中枢突终于孤束核上部。面神经核为特殊内脏运动核，上泌涎核发出其副交感纤维，下泌涎核属舌咽神经。"},{"q":"胸椎的形态结构特征是","o":["关节突关节面呈水平位","横突肋凹与肋结节相关节","棘突特别短","第1胸椎有横突孔","椎体横断面呈肾形"],"a":1,"e":"胸椎椎体两侧有肋凹，横突末端前面有横突肋凹与肋结节相关节，关节突关节面呈冠状位，棘突长而向后下倾斜呈叠瓦状。椎体呈肾形是腰椎特征，横突孔为颈椎特有。"},{"q":"关节唇的特征不包括","o":["增大关节面","可加深关节窝","附着于关节窝周缘","增加关节的稳定性","是透明软骨环"],"a":4,"e":"关节唇是附着于关节窝周缘的纤维软骨环，可增大关节面、加深关节窝并增加关节稳定性，髋臼唇和盂唇即属此类。透明软骨构成的是关节软骨。"},{"q":"属于腹膜外位器官的是","o":["肝","子宫","脾","肾上腺","膀胱"],"a":3,"e":"腹膜外位器官仅一面被腹膜覆盖，如肾、肾上腺、输尿管、十二指肠降部和水平部以及胰。肝、子宫和膀胱属腹膜间位器官，脾为腹膜内位器官。"},{"q":"收缩时使舌尖伸向对侧的肌肉是","o":["舌纵肌","舌骨舌肌","舌横机","颏舌肌","茎突舌肌"],"a":3,"e":"颏舌肌起自下颌体后面的颏棘，止于舌正中线两侧，单侧收缩使舌尖伸向对侧，双侧收缩拉舌向前下即伸舌。一侧颏舌肌瘫痪时，伸舌舌尖偏向患侧。"},{"q":"属于副交感神经节前纤维的神经是","o":["内脏大神经","腰内脏神经","内脏小神经","盆内脏神经","心上中下神经"],"a":3,"e":"盆内脏神经由骶2～4脊神经前支中的副交感纤维构成，属副交感节前纤维，在盆丛内换元后支配盆腔脏器。内脏大、小神经和腰内脏神经均为交感节前纤维。"},{"q":"下列关于膜迷路的描述，正确的是","o":["膜迷路是套在骨迷路内封闭的膜性管和囊","由椭圆囊、球囊、膜半规管和蜗螺旋管组成","膜迷路和骨迷路在蜗顶蜗孔处相交通","椭圆囊、球囊、内淋巴囊位于前庭内","膜迷路将骨迷路分为半规管、前庭和耳蜗3部分"],"a":0,"e":"膜迷路是套在骨迷路内封闭的膜性管和囊，内含内淋巴。前庭、骨半规管和蜗螺旋管属骨迷路，膜迷路则由椭圆囊、球囊、膜半规管和蜗管组成。"},{"q":"胸长神经","o":["属于锁骨下分支","属于臂丛内侧束的分支","属于臂丛外侧束的分支","沿着肩胛下肌表面下行","受损后，肩胛骨内侧缘翘起"],"a":4,"e":"胸长神经发自臂丛锁骨上部的神经根，沿前锯肌表面下行并支配该肌，损伤后前锯肌瘫痪，肩胛骨内侧缘翘起呈翼状肩。它不属内侧束或外侧束的分支。"},{"q":"与桡神经伴行走在桡神经沟内的动脉是","o":["肱动脉","肱深动脉","旋肱前动脉","旋肱后动脉","腋动脉"],"a":1,"e":"肱深动脉与桡神经伴行穿桡神经沟，并发出中副动脉和桡侧副动脉参与肘关节网。肱动脉行于肱二头肌内侧沟，旋肱前、后动脉环绕肱骨外科颈。"},{"q":"胶状质属于脊髓灰质","o":["Ⅰ层","Ⅱ层","Ⅲ层","Ⅳ层","Ⅴ层"],"a":1,"e":"脊髓灰质后角由后向前分为Ⅰ～Ⅵ层，第Ⅱ层由密集小细胞组成，称胶状质，接受后根细纤维传入并参与痛觉信息调制。"},{"q":"外展并参与屈、伸肩关节的肌是","o":["三角肌","胸大肌","背阔肌","冈上肌","小圆肌"],"a":0,"e":"三角肌起自锁骨外侧段、肩峰和肩胛冈，止于三角肌粗隆，中部纤维外展肩关节，前、后部纤维分别协助屈、伸肩关节。冈上肌只外展，小圆肌只外旋。"},{"q":"尺骨的形态结构不包括","o":["位于前臂的内侧，分为一体两端","上端前面有一半月形的滑车切迹","下端后内侧有向下的突起称尺骨茎突","下端有尺骨头","滑车切迹前下方的突起称鹰嘴"],"a":4,"e":"尺骨上端前面有半月形滑车切迹，其后上方的突起为鹰嘴，前下方的突起为冠突。尺骨下端有尺骨头和后内侧的尺骨茎突，位于前臂内侧。"},{"q":"脊神经后根内含有","o":["特殊躯体感觉纤维","特殊内脏感觉纤维","躯体运动纤维","内脏运动纤维","躯体感觉和内脏感觉纤维"],"a":4,"e":"脊神经后根由感觉神经元的中枢突构成，含躯体感觉和内脏感觉纤维。前根由运动神经元的轴突构成，含躯体运动和内脏运动纤维。"},{"q":"关于喉前庭，描述正确的是","o":["又称为喉腔","位于喉口与前庭襞之间","呈上窄下宽状","位于弹性圆锥下方","与声门下腔相连接"],"a":1,"e":"喉前庭为喉口至前庭襞之间的部分，呈上宽下窄的漏斗状，位于弹性圆锥上方。前庭襞与声襞之间为喉中间腔，声襞以下至环状软骨下缘为声门下腔。"},{"q":"关于三叉丘系正确的是","o":["由同侧三叉神经脊束核和部分三叉神经脑桥核发出的纤维组成","由对侧三叉神经脊束核和部分三叉神经脑桥核发出的纤维组成","三叉神经脊束纤维的直接延续","在脑干的内侧丘系的腹侧上升","大部分纤维传导同侧头面部的痛、温觉信息"],"a":1,"e":"三叉丘系由对侧三叉神经脊束核和部分三叉神经脑桥核发出的纤维交叉后上行组成，终止于背侧丘脑腹后内侧核，传导对侧头面部痛温觉和触压觉。"},{"q":"构成肾髓质的结构是","o":["肾皮质","肾柱","肾锥体","肾乳头","肾窦"],"a":2,"e":"肾髓质由15～20个肾锥体构成，锥体尖端为肾乳头，伸入肾小盏。肾皮质位于浅层并伸入锥体之间形成肾柱，肾窦是肾门向肾内凹陷的腔隙。"},{"q":"限制子宫向两侧移动的韧带是","o":["子宫骶韧带","子宫圆韧带","子宫主韧带","子宫阔韧带","骨盆漏斗韧带"],"a":3,"e":"子宫阔韧带由子宫前、后面的腹膜向两侧延伸至盆侧壁形成，可限制子宫向两侧移动。子宫圆韧带维持前倾，子宫主韧带防止下垂，骶子宫韧带维持前屈。"},{"q":"患者，女，27岁。足月妊娠，初次正常分娩时需注意保护的结构是","o":["大阴唇","小阴唇","阴阜","会阴体","阴蒂"],"a":3,"e":"会阴体是阴道口与肛门之间由皮肤、肌肉和筋膜构成的楔形区域，分娩时易撕裂，接产时须加以保护。大、小阴唇及阴阜属外生殖器的皮肤结构。"},{"q":"关于中耳的描述，错误的是","o":["中耳由鼓室、咽鼓管、乳突窦和乳突小房组成","大部分位于颞骨岩部内，为含气的不规则小腔隙","中耳向外借鼓膜与外耳道相隔","中耳向内借内耳道底与内耳相邻","中耳向前借咽鼓管通鼻咽部"],"a":3,"e":"鼓室内侧壁即迷路壁，有岬、前庭窗和蜗窗，与内耳相邻；内耳道位于颞骨岩部后面，不构成鼓室壁。鼓室外侧壁为鼓膜，前壁借咽鼓管通鼻咽部。"},{"q":"眼球外肌中使瞳孔转向外侧的包括","o":["上斜肌和下斜肌","上直肌和上斜肌","外直肌和下直肌","外直肌和上直肌","下直肌和下斜肌"],"a":0,"e":"下斜肌使瞳孔转向上外，上斜肌使瞳孔转向下外，二者收缩都使眼球转向外侧并内旋。上、下直肌和内直肌主要由动眼神经支配，作用以向上、下及内侧为主。"},{"q":"可伸膝关节的肌是","o":["缝匠肌","股四头肌","大收肌","阔筋膜张肌","臀大肌"],"a":1,"e":"股四头肌的股直肌起自髂前下棘，三个股肌起自股骨体，四头合成髌韧带止于胫骨粗隆，是伸膝关节的唯一肌群。缝匠肌、大收肌和臀大肌均不伸膝。"},{"q":"脉管系统的构成","o":["心血管系统和淋巴管组成","心、动脉、毛细血管和静脉","心血管系统和淋巴器官","心、动脉、静脉和淋巴导管","心血管系统和淋巴系统"],"a":4,"e":"脉管系统包括心血管系统和淋巴系统，前者由心、动脉、毛细血管和静脉组成，后者由淋巴管道、淋巴器官和淋巴组织组成，共同完成物质运输。"},{"q":"关于颈内静脉的叙述，错误的是","o":["延续于乙状窦","位于颈动脉鞘内","与面静脉汇合成锁骨下静脉","属支有舌静脉和咽静脉","外伤时可致空气栓塞"],"a":2,"e":"颈内静脉在胸锁关节后方与锁骨下静脉汇合成头臂静脉，并不与面静脉合成锁骨下静脉。颈内静脉续于乙状窦，位于颈动脉鞘内，外伤开放可吸入空气造成栓塞。"},{"q":"关于面静脉的正确描述是","o":["起自翼静脉丛","注入颈外静脉","通过眼上及眼下静脉与海绵窦交通","通过面深静脉与颅内静脉相通","在颈内、外动脉的深部走行"],"a":2,"e":"面静脉经内眦静脉、眼上静脉和眼下静脉与海绵窦交通，且缺乏静脉瓣，面部感染可循此途径蔓延至颅内。面静脉注入颈内静脉，与面深静脉交通的是翼静脉丛。"},{"q":"与成人比较，婴幼儿耳的特点是","o":["外耳道短而弯曲","鼓膜更为倾斜，近似呈水平位","检查鼓膜时，应将耳郭拉向后上方","小儿咽鼓管短而窄","外耳道骨性部分占比例更大"],"a":1,"e":"婴幼儿鼓膜较成人更为倾斜，近似水平位，故检查时须将耳郭向后下方牵拉。婴幼儿外耳道短而窄，骨性部比例小，咽鼓管短、宽而平，故中耳炎多见。"},{"q":"脑干内的非脑神经核","o":["动眼神经核","动眼神经副核","红核","展神经核","面神经核"],"a":2,"e":"红核位于中脑，接受小脑齿状核和大脑皮质的纤维，发出红核脊髓束，属非脑神经核。动眼神经核、展神经核和面神经核等均直接发出脑神经纤维。"},{"q":"左、右肺根内自前向后排列的主要结构是","o":["肺动脉、肺静脉和主支气管","肺静脉、肺动脉和主支气管","肺动脉、主支气管和肺静脉","肺静脉、主支气管和肺动脉","主支气管、肺静脉和肺动脉"],"a":1,"e":"肺根内结构自前向后依次为肺静脉、肺动脉和主支气管。自上而下右肺为支气管、肺动脉、肺静脉，左肺为肺动脉、支气管、肺静脉。"},{"q":"既能屈髋关节又能伸膝关节的肌是","o":["缝匠肌","股薄肌","股直肌","髂腰肌","股二头肌"],"a":2,"e":"股直肌起自髂前下棘，跨越髋、膝两关节，收缩时既屈髋关节又伸膝关节。缝匠肌屈髋屈膝，髂腰肌只屈髋，股二头肌伸髋屈膝。"},{"q":"关于甲状腺的描述，错误的是","o":["紧贴喉和气管上部的两侧和前方","呈“H”形，分为左右侧叶和中间的甲状腺峡","有时甲状腺峡向上伸出一锥状叶","甲状腺峡位于第4～5气管软骨环的前方","甲状腺可分泌甲状腺素"],"a":3,"e":"甲状腺峡多位于第2～4气管软骨环前方，窄者仅覆盖第2～3环。甲状腺呈H形，贴于喉和气管上部的两侧和前方，可分泌甲状腺素。"},{"q":"舌下阜","o":["有舌下腺小管的开口","只有下颌下腺管的开口","有舌腺的开口","有下颌下腺管和舌下腺大管的开口","其深面藏有舌下腺"],"a":3,"e":"舌下阜为舌下襞前端的圆形隆起，有下颌下腺管和舌下腺大管共同开口。舌下腺小管开口于舌下襞表面，舌下阜深面并无舌下腺。"},{"q":"视网膜脱离发生于","o":["双极细胞与节细胞之间","视网膜与脉络膜之间","脉络膜与巩膜之间","视网膜内层与外层之间","视锥、视杆细胞与双极细胞之间"],"a":3,"e":"视网膜视部由外层的色素上皮层和内层的神经层构成，两层之间结合疏松，此处分离即视网膜脱离。色素上皮与脉络膜结合紧密，不在此处分离。"},{"q":"胸导管穿经下述哪个结构进入到胸腔","o":["食管裂孔","腰肋三角","主动脉裂孔","膈肌","腔静脉孔"],"a":2,"e":"胸导管经主动脉裂孔自腹腔进入胸腔，沿脊柱前方上行，至胸上部斜向左上注入左静脉角。食管裂孔通过食管和迷走神经，腔静脉孔通过下腔静脉。"},{"q":"对感觉器的描述正确的有","o":["感觉器即感受器","结构简单，由感觉神经末梢形成","视器和前庭蜗器均为感觉器","仅可感受机体外环境刺激","只分布于内脏器官"],"a":2,"e":"感觉器由感受器及其附属器构成，视器和前庭蜗器均属感觉器，能感受特定刺激。感受器结构有简有繁，可感受内、外环境刺激，并非仅分布于内脏。"},{"q":"下牙槽神经","o":["主要行于下颌管内","为感觉神经，是上颌神经的分支","发出颊神经","分布于上、下颌牙和牙龈、口唇周围皮肤黏膜","发出舌神经"],"a":0,"e":"下牙槽神经为下颌神经的分支，经卵圆孔、下颌孔进入下颌管，分支分布于下颌牙及牙龈，终支颏神经至颏部和下唇。舌神经是下颌神经的另一分支。"},{"q":"心的正常起搏点","o":["窦房结","房室结","房室束","左、右束支","浦肯野纤维"],"a":0,"e":"窦房结位于上腔静脉与右心房交界处界沟上端的心外膜深面，具自动节律性，是心的正常起搏点，频率约60～100次/分，冲动经结间束传至心房和房室结。"},{"q":"房室结的滋养动脉通常起自","o":["左冠状动脉","右冠状动脉","前室间支","后室间支","旋支"],"a":1,"e":"房室结的血液供应多来自右冠状动脉发出的房室结支，少数来自左冠状动脉旋支。房室结位于房间隔下部右侧心内膜深面，是房室交界区的主要结构。"},{"q":"关于鼓膜的描述，错误的是","o":["构成鼓室外侧壁的大部分","位于外耳道与鼓室之间，与外耳道底约成45°～50°的倾斜角","婴儿鼓膜更为倾斜，几乎呈水平位","鼓膜周缘较厚，附着在颞骨鼓部和鳞部","鼓膜中心部向内凹陷，称鼓膜脐，为砧骨柄末端附着处"],"a":4,"e":"鼓膜脐是鼓膜中心向内凹陷处，为锤骨柄末端的附着点，而非砧骨柄。鼓膜与外耳道底约成45°～50°角，婴儿鼓膜更倾斜，几乎呈水平位。"},{"q":"具有次级起搏作用的是心传导系的哪部分","o":["窦房结","结间束","房室结","房室束","左、右束支"],"a":2,"e":"房室结位于房间隔下部右侧心内膜深面，具有潜在自动节律性，是心的次级起搏点。窦房结功能障碍时由房室结发放冲动，频率约40～60次/分。"},{"q":"中耳鼓室位于","o":["颞骨岩部","颞骨鼓部","颞骨乳突","颞骨鳞部","枕骨体"],"a":0,"e":"鼓室是颞骨岩部内不规则含气小腔，位于鼓膜与内耳外侧壁之间，内含听小骨、韧带、肌和神经。鼓部、乳突部和鳞部均不是鼓室所在部位。"},{"q":"关于肛管的叙述，错误的是","o":["以齿状线区分内、外痔","白线是肛门内、外括约肌的分界线","肛窦易积存粪便","肛直肠线为肛柱下端的连线","在齿状线下方有一宽约1cm的环形区为肛梳"],"a":3,"e":"肛直肠线是肛柱上端的连线，齿状线才是肛柱下端与肛瓣边缘连成的锯齿状线，二者位置不同。肛梳为齿状线下方宽约1cm的光滑环形区。"},{"q":"关于肺动脉正确的说法是","o":["发自左心室","左肺动脉横过胸主动脉的后方","其末端与主动脉弓下缘之间有动脉韧带","是肺的营养性血管","将动脉血运至肺"],"a":2,"e":"肺动脉干起自右心室，向左后上行至主动脉弓下缘处分为左、右肺动脉，分叉处有动脉韧带连于主动脉弓。肺动脉运送静脉血至肺进行气体交换，属功能性血管。"},{"q":"可使髋关节伸和旋外的肌是","o":["缝匠肌","股四头肌","大收肌","阔筋膜张肌","臀大肌"],"a":4,"e":"臀大肌起自髂骨翼外面和骶骨背面，止于髂胫束和股骨臀肌粗隆，是强大的伸髋肌并使髋关节旋外，也是维持人体直立的重要肌。阔筋膜张肌屈髋并内旋。"},{"q":"关于乳房，错误的是","o":["乳腺癌晚期，局部皮肤可出现橘皮样改变","乳腺位于浅筋膜内","乳头位于第2肋","乳房的外侧可达腋中线","位于胸大肌前方"],"a":2,"e":"成年女性乳头位于第4肋间隙或第5肋与锁骨中线交点处，不在第2肋。乳腺位于胸大肌前方的浅筋膜内，外侧可达腋中线，癌侵犯皮肤韧带可致橘皮样改变。"},{"q":"腹膜内位器官有","o":["肝","卵巢","子宫","胆囊","十二指肠降部"],"a":1,"e":"卵巢除卵巢门处外均被腹膜覆盖，属腹膜内位器官。肝、胆囊、子宫和膀胱属腹膜间位器官，十二指肠降部为腹膜外位器官。"},{"q":"属于特殊内脏运动核的神经核","o":["动眼神经核","滑车神经核","面神经核","展神经核","舌下神经核"],"a":2,"e":"面神经核发出特殊内脏运动纤维支配面部表情肌，属特殊内脏运动核。动眼神经核、滑车神经核、展神经核和舌下神经核均为一般躯体运动核。"},{"q":"属于结肠下区的间隙是","o":["左肝下后间隙","右肝下间隙","肝肾隐窝","左结肠旁沟","左肝下前间隙"],"a":3,"e":"结肠下区包括左、右结肠旁沟和左、右肠系膜窦；左肝下前、后间隙和肝肾隐窝位于结肠上区。左结肠旁沟位于降结肠左侧与盆壁之间，向下通盆腔。"},{"q":"关于网状结构的叙述，错误的是","o":["网状结构存在于整个脑干内","网状结构内有很多核团","脊髓也有网状结构","与上行和下行传导束无联系","脑干网状结构内含有重要的生命中枢"],"a":3,"e":"网状结构是灰质与白质交织的区域，接受上、下行传导束的侧支，并发出纤维广泛投射，与传导束联系密切。其内含有心血管中枢和呼吸中枢等生命中枢。"},{"q":"神经系统的结构和功能基本单位是","o":["神经胶质","神经节","神经元","神经核","神经纤维"],"a":2,"e":"神经元是神经系统结构和功能的基本单位，由胞体和突起构成，能接受刺激、整合信息并传导冲动。神经胶质只起支持、营养和保护作用。"},{"q":"后纵隔出现包块，不可能发生的是","o":["胸腺瘤","支气管囊肿","神经瘤","主动脉瘤","膈疝"],"a":0,"e":"胸腺位于前纵隔，其肿瘤不会在后纵隔形成包块。后纵隔内有气管、食管、胸主动脉、胸导管和迷走神经等，故可见支气管囊肿、神经源性肿瘤、主动脉瘤和膈疝。"},{"q":"棘突短而末端分叉的椎骨是","o":["寰椎","第2～6颈椎","隆椎","胸椎","腰椎"],"a":1,"e":"第2～6颈椎棘突短，末端分叉。第7颈椎棘突长而不分叉，寰椎无棘突，胸椎棘突长且呈叠瓦状，腰椎棘突呈板状水平后伸。"},{"q":"间脑是","o":["仅次于端脑的中枢高级部","交感神经低级中枢","副交感神经低级中枢","位于脑桥与端脑之间","位于中脑与小脑之间"],"a":0,"e":"间脑位于中脑与端脑之间，是仅次于端脑的中枢高级部位，分为背侧丘脑、后丘脑、下丘脑和底丘脑等。交感与副交感低级中枢位于脊髓和脑干。"},{"q":"交感神经","o":["低级中枢位于脊髓胸1～腰3节段的中间外侧核","节前纤维经灰交通支终止于椎旁神经节","节后纤维仅分布于躯干、四肢的血管、汗腺和竖毛肌","不支配肾上腺","低级中枢位于脊髓胸1～腰3节段的中间内侧核"],"a":0,"e":"交感神经低级中枢位于脊髓胸1～腰3节段侧角的中间外侧核。节前纤维经白交通支入椎旁节，节后纤维经灰交通支返回脊神经，并支配肾上腺髓质和腹腔脏器。"},{"q":"位于前列腺后方的结构是","o":["膀胱","直肠","精囊","输精管壶腹","尿道球腺"],"a":1,"e":"直肠位于前列腺后方，二者之间隔以直肠膀胱隔。前列腺前方为耻骨联合，上方为膀胱颈，两侧为精囊和输精管壶腹，故可经直肠指诊触及前列腺。"},{"q":"精子产生于","o":["生精小管","精囊","睾丸小隔","睾丸网","睾丸间质细胞"],"a":0,"e":"生精小管的生精上皮由支持细胞和生精细胞构成，精子由生精细胞经多次分裂和变态发育形成。睾丸间质细胞分泌雄激素，睾丸网和输出小管属排出通道。"},{"q":"不属于眼球屈光装置的结构是","o":["角膜","房水","晶状体","玻璃体","巩膜"],"a":4,"e":"眼的屈光装置包括角膜、房水、晶状体和玻璃体，均无色透明，使光线聚焦于视网膜。巩膜属眼球纤维膜，起保护眼球和维持眼球形状的作用。"},{"q":"关于肺的形态，描述正确的是","o":["右肺狭长","肺底平坦","后缘锐利","前缘有心压迹","肺底也叫膈面"],"a":4,"e":"肺底又称膈面，因贴膈而略向上凹。右肺短而宽，左肺因心压迹而狭长；肺前缘锐利并有心切迹，后缘圆钝贴于脊柱。"},{"q":"关于泪器的叙述，错误的是","o":["泪器属于眼副器","泪道包括泪点、泪小管、泪囊和鼻泪管","泪腺位于眶上壁前外侧部的泪腺窝内","泪小管为连结泪点与泪囊的小管","由泪腺和泪小管组成"],"a":4,"e":"泪器由泪腺和泪道组成，泪道包括泪点、泪小管、泪囊和鼻泪管，泪腺位于眶上壁前外侧的泪腺窝内。只列泪腺和泪小管是以偏概全。"},{"q":"关于腋神经的叙述，错误的是","o":["发自臂丛后束","穿经四边孔","支配三角肌和大圆肌","伴旋肱后动脉绕肱骨外科颈后行至肩胛区","受损后患者肩部失去圆隆外形"],"a":2,"e":"腋神经发自臂丛后束，穿四边孔伴旋肱后动脉绕肱骨外科颈，支配三角肌和小圆肌，大圆肌由肩胛下神经支配。损伤后三角肌瘫痪，臂不能外展，出现方肩。"},{"q":"关于输卵管的正确描述是","o":["为一对长而直的肌性管道","与卵巢门相通连","末端开口于腹膜腔","内侧端膨大弯曲，连于子宫底两侧","输卵管峡部，长而狭窄"],"a":2,"e":"输卵管是一对肌性管道，其漏斗部末端开口于腹膜腔，壶腹部最长而弯曲，为受精部位。内侧端经子宫角通子宫腔，不与卵巢门相通，峡部短而狭窄。"},{"q":"下列何种结构受损可使对侧躯体感觉障碍","o":["丘脑前辐射","内囊膝","丘脑中央辐射","颞桥束","枕桥束"],"a":2,"e":"丘脑中央辐射由背侧丘脑腹后核发出的纤维构成，经内囊后肢投射至中央后回，传导对侧躯体感觉，受损即致对侧躯体感觉障碍。内囊膝含皮质核束，损伤致对侧核下瘫。"},{"q":"关于臂丛的叙述，错误的是","o":["胸长神经属于锁骨上分支","腋神经属于锁骨下分支","锁骨中点后方的臂丛结构较集中，为臂丛阻滞麻醉部位","第1胸神经前支加入臂丛","胸长神经发出分支支配胸大、小肌"],"a":4,"e":"胸长神经支配前锯肌，损伤后出现翼状肩；胸大肌由胸内、外侧神经支配，胸小肌由胸内侧神经支配。胸长神经自臂丛锁骨上部发出，沿前锯肌表面下行。"},{"q":"下列结构不是由腹膜形成的是","o":["输卵管系膜","卵巢系膜","子宫主韧带","睾丸鞘膜","鞘韧带"],"a":2,"e":"子宫主韧带由盆筋膜增厚形成，内含平滑肌和结缔组织，不含腹膜，是防止子宫下垂的主要结构。输卵管系膜、卵巢系膜和睾丸鞘膜均由腹膜形成。"},{"q":"关于腋神经的叙述，正确的是","o":["发自臂丛内侧束","支配背阔肌","行程中有胸背动脉伴行","支配肱三头肌","损伤后影响肩关节的外展功能"],"a":4,"e":"腋神经发自臂丛后束，穿四边孔绕肱骨外科颈，支配三角肌和小圆肌，损伤后三角肌瘫痪、肩关节不能外展，并出现方肩和三角肌区感觉障碍。背阔肌由胸背神经支配。"},{"q":"输送尿液离开肾锥体的结构是","o":["乳头孔","肾盂","肾大盏","输尿管","肾髓质"],"a":0,"e":"肾乳头尖端有许多乳头孔，尿液经乳头孔流入肾小盏，再经肾大盏、肾盂和输尿管排出。肾锥体构成髓质，肾柱为皮质伸入髓质的部分，均不直接输送尿液。"},{"q":"右肺根内结构自上而下排列的顺序是","o":["肺静脉、肺动脉、支气管","肺静脉、支气管、肺动脉","肺动脉、支气管、肺静脉","肺动脉、肺静脉、支气管","支气管、肺动脉、肺静脉"],"a":4,"e":"右肺根内结构自上而下为支气管、肺动脉和肺静脉，左肺根为肺动脉、支气管和肺静脉。自前向后两肺均为肺静脉、肺动脉和主支气管。"},{"q":"咽鼓管鼓室口开口于鼓室的哪一个壁上","o":["前壁","后壁","上壁","下壁","内侧壁"],"a":0,"e":"咽鼓管鼓室口开口于鼓室前壁，位于听小骨上方，经咽鼓管与鼻咽部相通。鼓室后壁有鼓室窦和乳突窦开口，内侧壁有前庭窗和蜗窗。"},{"q":"关于眼球外肌的错误描述是","o":["是受躯体运动神经支配的骨骼肌","各直肌共同起自总腱环","所有的直肌都受动眼神经支配","上睑提肌开大眼裂，由动眼神经支配","上直肌位于上睑提肌下方"],"a":2,"e":"外直肌由展神经支配，上斜肌由滑车神经支配，其余直肌和上睑提肌由动眼神经支配，并非所有直肌都受动眼神经支配。各直肌均起自总腱环。"},{"q":"关于贵要静脉的正确描述是","o":["起自手背静脉网桡侧","接受前臂正中静脉","注入肱静脉","收集前臂后面的静脉血","在臂部与头静脉交通"],"a":2,"e":"贵要静脉起自手背静脉网尺侧，沿前臂尺侧上行，在臂中部注入肱静脉，部分汇入腋静脉。头静脉起自手背静脉网桡侧，注入腋静脉或锁骨下静脉。"},{"q":"关于大脑小脑说法正确的是","o":["接受同侧大脑皮质的传入纤维，故称为大脑小脑","接受对侧脑桥核经小脑中脚的传入纤维","传出纤维主要止于脑干网状结构","传出纤维主要止于背侧丘脑前核群","传出纤维主要止于后丘脑"],"a":1,"e":"大脑小脑接受对侧脑桥核经小脑中脚传入的纤维，也接受大脑皮质经脑桥小脑纤维的调控。其传出纤维经齿状核、小脑上脚止于红核和背侧丘脑腹外侧核。"},{"q":"大脑中央前回的动脉血供主要来自","o":["大脑前动脉","前交通动脉","基底动脉","大脑后动脉","大脑中动脉"],"a":4,"e":"中央前回属躯体运动区，主要由大脑中动脉的皮质支供血，其上部尚有大脑前动脉分支参与。中央后回躯体感觉区亦主要由大脑中动脉供应。"},{"q":"下颌神经穿过的颅底孔裂是","o":["棘孔","卵圆孔","圆孔","破裂孔","茎乳孔"],"a":1,"e":"下颌神经为三叉神经第三支，经卵圆孔出颅进入颞下窝。眼神经经眶上裂入眶，上颌神经经圆孔出颅，面神经经茎乳孔出颅。"},{"q":"不属于阴囊深层结构的是","o":["精索外筋膜","提睾肌","精索内筋膜","肉膜","睾丸鞘膜"],"a":3,"e":"阴囊层次由浅入深为皮肤、肉膜、精索外筋膜、提睾肌、精索内筋膜和睾丸鞘膜。肉膜属浅筋膜，含平滑肌纤维，可随温度舒缩，不属深层结构。"},{"q":"关于股动脉的叙述，错误的是","o":["在腹股沟韧带中点的深面续于髂总动脉","其主要分支为股深动脉、腹壁浅动脉、旋髂浅动脉和阴部外动脉","其体表投影为：大腿外展外旋，自腹股沟韧带中点至收肌结节作一连线，此线的上2/3为股动脉","其压迫止血部位为：在腹股沟韧带中点处将股动脉压向耻骨上支","压迫该动脉其止血范围为下肢大部分"],"a":0,"e":"股动脉在腹股沟韧带中点深面续于髂外动脉，而非髂总动脉，髂总动脉在骶髂关节前方分为髂内、外动脉。股动脉主要分支有股深动脉、腹壁浅动脉和旋髂浅动脉等。"},{"q":"主动脉弓的分支有","o":["右颈总动脉","右锁骨下动脉","冠状动脉","椎动脉","头臂干"],"a":4,"e":"主动脉弓自右向左依次发出头臂干、左颈总动脉和左锁骨下动脉。右颈总动脉和右锁骨下动脉均发自头臂干，冠状动脉发自升主动脉，椎动脉发自锁骨下动脉。"},{"q":"关于胰的叙述，错误的是","o":["是人体最大的消化腺","分为4部分","胰头被十二指肠包绕","钩突紧邻肠系膜上血管","副胰管开口于十二指肠小乳头"],"a":0,"e":"肝是人体最大的消化腺，胰为第二大消化腺，兼有外分泌和内分泌功能。胰分头、体、尾和钩突四部，胰头被十二指肠环抱，副胰管开口于十二指肠小乳头。"},{"q":"一侧副神经损伤出现","o":["头不能向患侧侧屈","头不能向健侧侧屈","不能点头","不能伸舌","舌尖偏向健侧"],"a":0,"e":"副神经支配胸锁乳突肌和斜方肌，一侧损伤时胸锁乳突肌瘫痪，头不能向患侧侧屈、面不能转向健侧，并出现患侧肩下垂。伸舌和舌尖偏斜由舌下神经支配。"},{"q":"分布于下列何处的感受器为本体觉感受器","o":["血管","内耳基底膜","肌腱和关节","空腔性脏器壁内","皮肤和黏膜"],"a":2,"e":"本体觉感受器位于肌、腱、关节和韧带内，包括肌梭、腱器官和关节感受器，感受位置觉和运动觉。皮肤黏膜感受浅感觉，内耳基底膜感受听觉，空腔脏器壁感受牵张。"},{"q":"小腿前群肌包括","o":["腓骨长肌","趾长伸肌","腓骨短肌","趾长屈肌","腓肠肌"],"a":1,"e":"小腿前群肌包括胫骨前肌、趾长伸肌和拇长伸肌，均由腓深神经支配。腓骨长、短肌属外侧群，趾长屈肌和腓肠肌属后群。"},{"q":"属于舌下面的结构是","o":["界沟","舌盲孔","舌系带","舌扁桃体","菌状乳头"],"a":2,"e":"舌下面黏膜正中线上有连于口底的舌系带，其两侧有舌下襞和舌下阜。界沟和舌盲孔位于舌根与舌体交界处，舌扁桃体在舌根，菌状乳头分布于舌体上面。"},{"q":"关于臂丛正确的是","o":["由5～8颈神经前支反复分支组合后形成臂丛","在腋窝内最后形成3个神经干","在腋窝内最后形成3个神经束夹持腋动脉","从后束发出正中神经","从外侧束发出桡神经"],"a":2,"e":"臂丛由第5～8颈神经前支和第1胸神经前支大部组成，合成上、中、下三干，入腋窝后每干分前、后两股，最后形成内、外、后三束夹持腋动脉。正中神经由内、外侧根合成。"},{"q":"前庭蜗神经含有","o":["一般躯体感觉纤维","一般躯体运动纤维","一般内脏感觉纤维","一般内脏运动纤维","特殊躯体感觉纤维"],"a":4,"e":"前庭蜗神经为特殊躯体感觉神经，含传导听觉的蜗神经纤维和传导平衡觉的前庭神经纤维，分别起自螺旋器和前庭器。其感觉神经元胞体位于内耳道内的神经节。"},{"q":"上消化道不包括","o":["口腔","咽","空肠","胃","十二指肠"],"a":2,"e":"临床上将十二指肠以上的消化管称上消化道，包括口腔、咽、食管、胃和十二指肠。空肠、回肠及大肠位于其下，不属上消化道。"},{"q":"包绕外侧沟后端的脑区","o":["颞上回","颞中回","额下回","缘上回","角回"],"a":3,"e":"外侧沟后端绕至半球上外侧面处为缘上回，围绕颞上沟末端的是角回，二者均属顶下小叶。颞上回、颞中回和额下回不包绕外侧沟后端。"},{"q":"有关正中神经的构成，正确的是","o":["发自臂丛外侧束的分支","发自臂丛内侧束的分支","发自臂丛后束的分支","由外侧根与内侧根构成","是臂丛锁骨上分支"],"a":3,"e":"正中神经由臂丛内侧束发出的内侧根和外侧束发出的外侧根合成，在臂部与肱动脉伴行。它属臂丛锁骨下分支，桡神经发自后束。"},{"q":"属于间脑的结构是","o":["橄榄核","红核","黑质","苍白球","漏斗核"],"a":4,"e":"漏斗核位于下丘脑漏斗的后方、第三脑室壁上，属间脑结构。橄榄核在延髓，红核和黑质在中脑，苍白球属端脑的基底核。"},{"q":"以下关于小脑的描述，正确的是","o":["位于颅中窝","上面隔小脑幕与大脑枕叶相邻","绒球属于新小脑","小脑扁桃体位于小脑半球的后方","借小脑下脚与脑桥联系"],"a":1,"e":"小脑位于颅后窝，上面隔小脑幕与大脑枕叶相邻，下面为小脑谷。绒球属原小脑，小脑扁桃体位于小脑半球下面前内侧，小脑与脑桥借小脑中脚联系。"},{"q":"下列哪种结构不属于端脑的连合纤维","o":["胼胝体","前连合","额钳","穹窿连合","后连合"],"a":4,"e":"端脑的连合纤维包括胼胝体、前连合和穹窿连合，胼胝体嘴、膝及各钳均属其组成部分。后连合位于中脑与间脑交界处，连合上丘等结构，不属端脑连合纤维。"},{"q":"内侧丘系描述正确的是","o":["发自脊髓胸核","发自薄束核和楔束核","是交叉前的纤维","终于同侧上丘核","传导躯干四肢的温、痛觉"],"a":1,"e":"内侧丘系由对侧薄束核和楔束核发出的二级纤维交叉后组成，在延髓、脑桥和中脑上行，终止于背侧丘脑腹后外侧核，传导对侧躯干四肢意识性本体感觉和精细触觉。"},{"q":"小儿中耳炎的主要感染途径是","o":["咽鼓管","外耳道","鼓膜","鼓室","乳突窦"],"a":0,"e":"小儿咽鼓管短、宽而平直，咽部感染易经此侵入鼓室引起中耳炎，故小儿中耳炎多继发于上呼吸道感染。经外耳道、鼓膜途径感染者少见。"},{"q":"大脑脚脚底外侧1/5通过","o":["皮质脊髓束","皮质核束","额桥束","顶、枕、颞桥束","内侧纵束"],"a":3,"e":"大脑脚脚底自内侧向外侧依次为额桥束、皮质脊髓束和顶、枕、颞桥束，后者占外侧1/5。皮质核束位于皮质脊髓束内侧，内侧纵束位于被盖近中线处。"},{"q":"与甲状腺上动脉伴行的神经是","o":["迷走神经","喉返神经","喉上神经喉内支","喉上神经喉外支","颈交感干"],"a":3,"e":"喉上神经喉外支与甲状腺上动脉伴行，共同行于甲状腺侧叶上极附近，结扎甲状腺上动脉时应紧靠腺体，以免损伤该神经致声带松弛。喉返神经与甲状腺下动脉关系密切。"},{"q":"关于孤束核的叙述，错误的是","o":["孤束核位于迷走神经背核的腹外侧","孤束核主要位于延髓内","孤束上部接受来自第Ⅶ、Ⅸ、Ⅹ对脑神经的纤维","孤束核仅接受一般内脏感觉信息","孤束下部接受来自第Ⅸ、Ⅹ对脑神经的纤维"],"a":3,"e":"孤束核不仅接受一般内脏感觉，其上端还接受面神经、舌咽神经和迷走神经传导味觉的特殊内脏感觉纤维。孤束核位于延髓，居迷走神经背核的腹外侧。"},{"q":"下列管道中，无明显狭窄者为","o":["食管","男性尿道","输尿管","输精管","输卵管"],"a":3,"e":"输精管管径细而均匀，全长约50cm，全程无明显狭窄，是输送精子的管道。食管、男性尿道和输尿管均有三处生理性狭窄。"},{"q":"屈第2～5掌指关节和伸第2～5指骨间关节的肌是","o":["拇收肌","拇短屈肌","蚓状肌","拇短展肌","小指伸肌"],"a":2,"e":"蚓状肌起自指深屈肌腱，止于第2～5指的指背腱膜，收缩时屈掌指关节、伸指间关节。骨间肌作用相似，鱼际肌和小指伸肌不具此功能。"},{"q":"桡骨的骨性标志包括","o":["桡骨茎突和桡骨粗隆","桡骨茎突和桡骨头","桡骨颈和桡骨头","桡骨粗隆和桡骨颈","桡骨茎突和尺切迹"],"a":1,"e":"桡骨下端外侧的隆起为桡骨茎突，上端膨大为桡骨头，二者均可体表触及，是重要骨性标志。桡骨粗隆、桡骨颈和尺切迹位置较深，不易触及。"},{"q":"下列属于氨基酸能通路的是","o":["胆碱能通路","去甲肾上腺素能通路","5-羟色胺能通路","谷氨酸能通路","多巴胺能通路"],"a":3,"e":"谷氨酸是中枢神经系统主要的兴奋性氨基酸递质，谷氨酸能通路属氨基酸能通路。胆碱能通路属胆碱类递质，去甲肾上腺素能、多巴胺能和5-羟色胺能通路属单胺类。"},{"q":"眼的神经支配，正确的是","o":["动眼神经支配外直肌","滑车神经支配下斜肌","睫状肌由交感神经支配","瞳孔括约肌由副交感神经支配","眼球的痛温觉由视神经支配"],"a":3,"e":"瞳孔括约肌由动眼神经副核发出的副交感纤维经睫状神经节支配，收缩时瞳孔缩小。外直肌由展神经支配，下斜肌由动眼神经支配，眼球痛温觉由眼神经传导。"},{"q":"关于子宫位置的叙述，错误的是","o":["子宫下端位于坐骨棘平面以下","位于盆腔中央","位于膀胱与直肠之间","两侧有输卵管和卵巢","呈前倾前屈位"],"a":0,"e":"正常子宫呈前倾前屈位，位于小骨盆中央、膀胱与直肠之间，子宫颈下端位于坐骨棘平面以上，低于此平面提示子宫脱垂。子宫两侧有输卵管和卵巢。"},{"q":"仰视时，眼球收缩是","o":["两眼上直肌和下斜肌同时收缩","两眼下直肌和下斜肌同时收缩","两眼下直肌和上斜肌同时收缩","两眼上直肌和上斜肌同时收缩","两眼内直肌和下斜肌同时收缩"],"a":0,"e":"仰视时两眼上直肌和下斜肌同时收缩，上直肌使瞳孔转向上内，下斜肌使瞳孔转向上外，二者协同完成上转。俯视则由下直肌和上斜肌共同作用。"},{"q":"可上提和后退下颌骨的肌是","o":["翼外肌","颞肌","翼内肌","咬肌","二腹肌"],"a":1,"e":"颞肌起自颞窝，止于下颌骨冠突，后部纤维收缩可上提并后退下颌骨。咬肌和翼内肌只上提下颌骨，翼外肌使下颌前伸，二腹肌降下颌。"},{"q":"声带麻痹是由于损伤了","o":["颈交感干","舌咽神经","副神经","喉返神经","喉上神经喉内支"],"a":3,"e":"喉返神经支配除环甲肌以外的全部喉内肌，损伤后声带麻痹、声音嘶哑甚至呼吸困难。喉上神经喉内支司声门裂以上喉黏膜感觉，损伤主要引起呛咳。"},{"q":"关于背侧丘脑的描述，正确的是","o":["分为前核群、内侧核群和外侧核群","内髓板由密集排列的细胞组成","外髓板紧邻内囊外侧","内髓板内的核团称为正中核","网状核紧邻第三脑室侧壁"],"a":0,"e":"背侧丘脑被内髓板分为前核群、内侧核群和外侧核群，内髓板由白质纤维构成，其内的核团称板内核。外髓板分隔丘脑与网状核，网状核位于丘脑外侧。"},{"q":"患者有足下垂和足背皮肤感觉缺失，损伤可能涉及","o":["腓深神经","胫神经","腓浅神经","股神经","闭孔神经"],"a":0,"e":"腓深神经支配小腿前群肌和足背肌，损伤后胫骨前肌瘫痪出现足下垂，并伴第1、2趾间背侧皮肤感觉缺失。腓浅神经损伤致足外翻障碍，胫神经损伤致足底感觉障碍。"},{"q":"属于腹膜形成的结构是","o":["子宫阔韧带","子宫圆韧带","子宫主韧带","子宫骶韧带","卵巢固有韧带"],"a":0,"e":"子宫阔韧带由覆盖子宫前、后面的腹膜向两侧延伸至盆侧壁形成，内含输卵管、卵巢及血管等。子宫圆韧带、主韧带、骶子宫韧带由结缔组织和平滑肌构成。"},{"q":"关于阑尾的描述正确的是","o":["附于结肠起始部","位于左髂窝内","根部是3条结肠带集中之处","属腹膜间位器官","一般长度在10cm以上"],"a":2,"e":"阑尾根部附于盲肠后内侧壁，三条结肠带在阑尾根部集中，是术中寻找阑尾的标志。阑尾一般长6～8cm，属腹膜内位器官，位于右髂窝内。"},{"q":"脊髓副交感神经低级中枢位于","o":["胸腰部的脊髓侧角中","全部骶节中的骶副交感核","骶2～4节中的骶副交感核","全部腰节中的中间外侧核","腰2～4节中的中间外侧核"],"a":2,"e":"脊髓副交感神经的低级中枢位于骶2～4节段侧角的骶副交感核，发出节前纤维经盆内脏神经至盆丛换元。胸1～腰3节段侧角为交感低级中枢。"},{"q":"属于一般内脏运动柱的脑神经核","o":["动眼神经核","舌下神经核","面神经核","副神经核","迷走神经背核"],"a":4,"e":"迷走神经背核属一般内脏运动核，发出副交感节前纤维支配胸腹腔脏器。动眼神经核和舌下神经核为一般躯体运动核，面神经核和副神经核为特殊内脏运动核。"},{"q":"成对的脑颅骨是","o":["蝶骨","枕骨","筛骨","额骨","顶骨"],"a":4,"e":"脑颅骨共8块，成对的只有顶骨和颞骨，不成对的是额骨、枕骨、蝶骨和筛骨。所列选项中仅顶骨成对。"},{"q":"迷走神经的纤维成分不包括","o":["副交感纤维","特殊内脏运动纤维","一般内脏感觉纤维","一般躯体感觉纤维","特殊内脏感觉纤维"],"a":4,"e":"迷走神经含副交感纤维、一般内脏感觉、一般躯体感觉和支配咽喉肌的特殊内脏运动纤维四种成分，不含特殊内脏感觉纤维。味觉纤维随面神经和舌咽神经走行。"},{"q":"关于腭的叙述，错误的是","o":["腭是固有口腔的顶","软腭称为腭帆","腭垂是腭帆后缘中部向下的突起","腭舌弓延至舌根","腭咽弓延至咽侧壁"],"a":1,"e":"软腭后缘游离下垂的部分称腭帆，其中部向下的突起为腭垂，故不能把整个软腭称为腭帆。腭舌弓延至舌根，腭咽弓延至咽侧壁，腭构成固有口腔的顶。"},{"q":"关于纵隔，正确的叙述是","o":["两侧界为纵隔胸膜","容纳心和肺","后界为胸主动脉和食管","位于胸膜腔内","下界为壁腹膜"],"a":0,"e":"纵隔是两侧纵隔胸膜之间全部器官、结构和结缔组织的总称，上界为胸廓上口，下界为膈，前界为胸骨，后界为脊柱胸段。肺位于胸膜腔内，不在纵隔内。"},{"q":"男性的生殖腺是","o":["前列腺","精囊","睾丸","尿道球腺","附睾"],"a":2,"e":"睾丸是男性生殖腺，产生精子并分泌雄激素。前列腺、精囊和尿道球腺属附属腺，附睾是输精管道的一部分。"},{"q":"对于静脉特点的正确描述是","o":["数量比动脉少","管壁粗","弹性大","大部分有静脉瓣","吻合较少"],"a":3,"e":"静脉管壁薄、弹性小、管腔大，数量多于动脉且吻合丰富，四肢静脉内有静脉瓣防止血液逆流。动脉管壁厚、弹性大、无瓣膜。"},{"q":"关于内侧丘系正确的是","o":["纤维来自同侧的薄束核和楔束核","终止于背侧丘脑腹后内侧核","位于锥体束的腹侧","在中脑位于红核的内侧","传导对侧躯干、四肢意识性本体感觉和精细触觉"],"a":4,"e":"内侧丘系传导对侧躯干和四肢的意识性本体感觉及精细触觉，纤维来自对侧薄束核和楔束核，终止于背侧丘脑腹后外侧核，在脑干内行于锥体束的背侧。"},{"q":"属于一般内脏运动核的是","o":["孤束核","迷走神经背核","疑核","面神经核","副神经核"],"a":1,"e":"迷走神经背核属一般内脏运动核，发出副交感节前纤维。孤束核为一般和特殊内脏感觉核，疑核、面神经核和副神经核为特殊内脏运动核。"},{"q":"在十二指肠镜检查中，内镜插入大约多长才能到达食管的第2处狭窄","o":["15cm","20cm","25cm","30cm","40cm"],"a":2,"e":"食管第二处狭窄位于食管与左主支气管交叉处，距中切牙约25cm，是异物滞留和肿瘤好发部位。第一狭窄距中切牙15cm，第三狭窄距中切牙约40cm。"},{"q":"根据神经元的功能和传导方向将神经元分为","o":["假单极神经元、双极神经元和多极神经元","感觉神经元、运动神经元和联络神经元","胆碱能神经元、单胺能神经元和肽能神经元","假单极神经元、双极神经元和中间神经元","传入神经元、传出神经元和运动神经元"],"a":1,"e":"按功能和传导方向，神经元分为感觉（传入）神经元、运动（传出）神经元和联络（中间）神经元。假单极、双极和多极神经元是按形态分类。"},{"q":"关于脊柱的形态结构描述，正确的是","o":["共由24块椎骨连结而成","椎间盘的厚度约占脊柱全长的1/2","有颈、胸、腰、骶四个生理弯曲","由于胸部椎间盘较薄，故该处运动幅度较大","仅能作少量的屈、伸运动"],"a":2,"e":"成人脊柱由24块椎骨、骶骨和尾骨借椎间盘、韧带和关节连结而成，侧面观有颈、胸、腰、骶四个生理弯曲。椎间盘约占脊柱全长1/4，胸部椎间盘薄故运动幅度小。"},{"q":"锥体外系传导通路不包括","o":["皮质—新纹状体—背侧丘脑—皮质环路","新纹状体—黑质环路","苍白球—底丘脑环路","皮质—脑桥—小脑—皮质环路","皮质—脊髓环路"],"a":4,"e":"皮质脊髓束即皮质—脊髓环路，属锥体系。锥体外系包括皮质—新纹状体—背侧丘脑—皮质环路、新纹状体—黑质环路、苍白球—底丘脑环路和皮质—脑桥—小脑—皮质环路。"},{"q":"棘突特别长，末端不分叉，活体易于摸到，为记数椎骨序数的标志的椎骨是","o":["第1颈椎","第2颈椎","第7颈椎","胸椎","腰椎"],"a":2,"e":"第7颈椎棘突特别长，末端不分叉，活体易触及，是计数椎骨序数的标志，故称隆椎。寰椎无棘突，胸椎棘突呈叠瓦状，腰椎棘突呈板状。"},{"q":"关于咽鼓管的叙述，错误的是","o":["咽鼓管连通鼻咽部与鼓室","咽鼓管使鼓室的气压与外界的大气压相等，以保持鼓膜内、外侧的压力平衡","咽鼓管骨部向后外开口于咽鼓管鼓室口","咽鼓管软骨部向前内开口于咽鼓管咽口，平时处于开放状态","小儿咽鼓管短而宽，接近水平位，故咽部感染可经咽鼓管侵入鼓室"],"a":3,"e":"咽鼓管软骨部平时闭合，仅在吞咽、打哈欠或咀嚼时开放，以调节鼓室内外气压平衡。其骨部向后外开口于鼓室前壁，软骨部向前内开口于鼻咽部侧壁。"},{"q":"中脑内的副交感神经核","o":["动眼神经核","动眼神经副核","上泌涎核","下泌涎核","迷走神经背核"],"a":1,"e":"动眼神经副核位于中脑上丘平面，发出副交感节前纤维经动眼神经至睫状神经节换元，支配瞳孔括约肌和睫状肌。上、下泌涎核分别位于脑桥和延髓。"},{"q":"鱼际肌不包括","o":["拇短伸肌","拇短屈肌","拇短展肌","拇收肌","拇对掌肌"],"a":0,"e":"鱼际肌包括拇短展肌、拇短屈肌、拇对掌肌和拇收肌，前三者由正中神经支配，拇收肌由尺神经支配。拇短伸肌属前臂后群肌，不属鱼际肌。"},{"q":"肾乳头突入的结构是","o":["肾锥体","肾柱","肾皮质","肾窦","肾小盏"],"a":4,"e":"肾乳头尖端突入肾小盏，尿液经乳头孔流入肾小盏，再汇入肾大盏和肾盂。肾锥体构成肾髓质，肾柱为皮质伸入髓质的部分，肾窦容纳肾盏、肾盂及脂肪。"},{"q":"关于眼球外肌作用的叙述，错误的是","o":["眼球外肌都是骨骼肌","上直肌可使瞳孔转向上内侧","外直肌可使瞳孔转向内侧","上斜肌可使瞳孔转向下外侧","上、下斜肌都可使瞳孔转向外侧"],"a":2,"e":"外直肌由展神经支配，收缩时使瞳孔转向外侧，并非转向内侧。上直肌使瞳孔转向上内，上斜肌使瞳孔转向下外，上、下斜肌均可使瞳孔转向外侧。"},{"q":"关于大、小隐静脉的正确描述是","o":["小隐静脉在足内侧缘起自足背静脉弓","大隐静脉接受腹壁下静脉","小隐静脉注入股静脉","大隐静脉含有较少的瓣膜","小隐静脉经外踝后方上行"],"a":4,"e":"小隐静脉在足外侧缘起自足背静脉弓，经外踝后方沿小腿后面上行，穿深筋膜后注入腘静脉；经内踝前方上行并汇入股静脉的是大隐静脉。"},{"q":"肾蒂各结构的排列，从前向后依次是","o":["肾静脉、肾动脉、肾盂","肾静脉、肾盂、肾动脉","肾盂、肾静脉、肾动脉","肾盂、肾动脉、肾静脉","肾动脉、肾静脉、肾盂"],"a":0,"e":"肾蒂内结构自前向后为肾静脉、肾动脉和肾盂末端，自上向下则为肾动脉、肾静脉和肾盂；下腔静脉偏右，故右肾蒂较短。"},{"q":"脑桥内与迷走神经背核属于同一功能柱的核团","o":["上泌涎核","脑桥核","展神经核","面神经核","三叉神经脑桥核"],"a":0,"e":"一般内脏运动核共4对，即动眼神经副核、上泌涎核、下泌涎核和迷走神经背核，均发出副交感节前纤维，迷走神经背核与之同属一个功能柱。"},{"q":"关于结膜的描述，正确的是","o":["睑结膜与睑板结合疏松，易于分离","球结膜覆盖在巩膜和角膜前面","睑结膜和球结膜相互移行构成结膜囊","结膜囊为密闭的囊腔","结膜穹窿分为结膜上穹和结膜下穹"],"a":4,"e":"结膜穹窿是睑结膜与球结膜相互移行处，分为结膜上穹和结膜下穹，上穹较深；睑结膜与睑板结合紧密不易分离，结膜囊借泪道与外界相通。"},{"q":"关于胸膜腔的描述，正确的是","o":["由肋胸膜和脏胸膜围成","由壁胸膜相互返折形成","不与外界相通","左、右两侧经气管相通","内有左、右肺"],"a":2,"e":"胸膜腔由脏胸膜与壁胸膜围成，是封闭的潜在性间隙，内含少量浆液呈负压，不与外界相通，左右两腔互不相通，腔内也无肺。"},{"q":"不位于肝脏脏面的结构是","o":["肝圆韧带","静脉韧带","镰状韧带","肝门","胆囊窝"],"a":2,"e":"镰状韧带连于肝上面与膈和腹前壁之间，属肝上面的腹膜结构；肝的脏面有肝门、胆囊窝、腔静脉沟以及肝圆韧带、静脉韧带。"},{"q":"前锯肌收缩时","o":["可内收肩关节","使肩胛骨向前和紧贴胸廓","使肩关节前屈","使肩关节后伸","使肩胛骨下角旋内"],"a":1,"e":"前锯肌起自上8～9个肋骨外面，止于肩胛骨内侧缘和下角，收缩时拉肩胛骨向前并紧贴胸廓，下部肌束使肩胛骨下角旋外以助臂上举。"},{"q":"下列说法正确的是","o":["屏状核与岛叶皮质之间的白质称最外囊","屏状核与岛叶皮质之间的白质称外囊","大脑内的弓状纤维主要联系同侧半球各叶","皮质核束经内囊后肢下行","下纵束和扣带属于连合纤维"],"a":0,"e":"屏状核与豆状核之间的白质为外囊，屏状核与岛叶皮质之间的白质为最外囊；弓状纤维联系同侧半球相邻脑回，属联络纤维而非连合纤维。"},{"q":"男性输精管道不包括下列哪个结构","o":["男性尿道","射精管","输精管","附睾","睾丸"],"a":4,"e":"男性输精管道由附睾、输精管、射精管和男性尿道构成；睾丸属生殖腺，产生精子并分泌雄激素，不属输送管道。"},{"q":"正确描述阴道的是","o":["位于尿道的前方","穿过盆膈","上端包绕子宫颈的全部","上端直接通子宫腔","阴道口开口于阴道前庭"],"a":4,"e":"阴道为前后扁的肌性管道，下部较窄，以阴道口开口于阴道前庭；阴道位于尿道后方，上端环绕子宫颈阴道部，并不直接通子宫腔。"},{"q":"可足背屈和足内翻的肌是","o":["比目鱼肌","胫骨前肌","胫骨后肌","腓骨长肌","腓肠肌"],"a":1,"e":"胫骨前肌起自胫骨上端外侧面，肌腱经伸肌上、下支持带深面止于内侧楔骨和第1跖骨底，可伸踝关节即足背屈，并使足内翻。"},{"q":"肱骨的下端的形态结构不包括","o":["外侧部半球形的肱骨小头","内侧部滑车状的肱骨滑车","滑车前面上方有鹰嘴窝","滑车内侧突起为内上髁","内上髁后面的浅沟称尺神经沟"],"a":2,"e":"鹰嘴窝位于肱骨滑车后上方，伸肘时容纳尺骨鹰嘴；滑车前上方为冠突窝，肱骨小头前上方为桡窝，内上髁后方的浅沟为尺神经沟。"},{"q":"神经元的基本结构是","o":["胞体和突起","周围突和中枢突","胞体和轴突","胞体和神经","突触"],"a":0,"e":"神经元是神经系统结构和功能的基本单位，每个神经元都可分为胞体和突起两部分，突起又分为树突和轴突。"},{"q":"髋骨的重要体表标志不包括","o":["髂嵴","髂前上棘","耻骨结节","坐骨结节","坐骨棘"],"a":4,"e":"髋骨可扪及的体表标志有髂嵴、髂前上棘、耻骨结节和坐骨结节等；坐骨棘位于坐骨体后缘，位置深在，不能经体表触知。"},{"q":"关于前列腺的位置和毗邻，描述正确的是","o":["底位于尿生殖膈上面","尖邻接膀胱颈","后方邻盆膈","后上方有输精管壶腹和精囊","前方邻直肠"],"a":3,"e":"前列腺底朝上邻膀胱颈，尖朝下接尿生殖膈，后方为直肠，后上方有输精管壶腹和精囊；其前方为耻骨联合。"},{"q":"关于神经纤维的正确描述是","o":["是神经元的轴突","是树突包被髓鞘而成","仅存在于周围神经系统","有髓纤维比无纤维的传导速度快","神经纤维的直径与传导速度快慢无关"],"a":3,"e":"神经纤维由轴突及包被它的髓鞘和神经膜构成，中枢与周围神经系统内均有分布；传导速度与纤维直径、髓鞘厚薄成正比，有髓纤维快于无髓纤维。"},{"q":"对动眼神经的描述，正确的是","o":["由动眼神经核发出的纤维组成","由大脑脚内侧出脑","和视神经一起经视神经孔入眶","与瞳孔光反射无关","分支至角膜"],"a":1,"e":"动眼神经根连于脚间窝下部、大脑脚内侧，经眶上裂入眶；瞳孔对光反射的传出即由动眼神经的副交感纤维完成。"},{"q":"蛛网膜粒突入","o":["上矢状窦","下矢状窦","直窦","窦汇","乙状窦"],"a":0,"e":"蛛网膜粒突入上矢状窦，是脑脊液回流入静脉的重要途径，颅盖内板相应处形成颗粒小凹；下矢状窦则注入直窦。"},{"q":"关于眼的神经分布的叙述，错误的是","o":["视觉由眼神经传导","眼的一般感觉由三叉神经传导","瞳孔开大肌由交感神经支配","瞳孔括约肌和睫状肌由动眼神经支配","眼球外肌的运动由动眼、滑车和展神经支配"],"a":0,"e":"视觉由视神经传导，眼神经只传导眼球及眶内的一般躯体感觉；瞳孔开大肌受交感神经支配，括约肌和睫状肌受动眼神经副交感纤维支配。"},{"q":"瘫痪时可产生“塌肩”现象的肌是","o":["大圆肌","斜方肌","背阔肌","三角肌","前锯肌"],"a":1,"e":"斜方肌止于锁骨外侧1/3、肩峰和肩胛冈，上部纤维上提肩胛骨，该肌瘫痪时肩胛骨下移、肩下垂，出现“塌肩”。"},{"q":"心包横窦位于","o":["心包腔前下部","升主动脉与肺动脉后方","下腔静脉和心包后壁之间","上腔静脉和右肺血管之间","主动脉和左心房后壁之间"],"a":1,"e":"心包横窦位于升主动脉和肺动脉干后方与上腔静脉、左心房前壁之间，是心包腔内的通道，可容手指通过。"},{"q":"关于桡神经的叙述，错误的是","o":["从臂丛后束发出","在臂后区发出分支支配肱三头肌","肱骨中段骨折易导致该神经的损伤","桡神经深支又称为骨间后神经","与前臂前群肌的支配无关"],"a":4,"e":"桡神经发自臂丛后束，支配臂后群和前臂后群伸肌，还支配前臂前群的肱桡肌，并非与前臂前群无关；其深支即骨间后神经。"},{"q":"支配瞳孔括约肌的神经的节后纤维发自","o":["动眼神经副核","翼腭神经节","下神经节","睫状神经节","颈交感干神经节"],"a":3,"e":"动眼神经副核发出的副交感节前纤维随动眼神经入眶，在睫状神经节内换元，节后纤维支配瞳孔括约肌和睫状肌。"},{"q":"男性膀胱后面毗邻的结构中不包括","o":["精囊","输精管壶腹","输尿管盆部","前列腺","直肠前壁"],"a":3,"e":"男性膀胱底后方与精囊、输精管壶腹和直肠前壁相邻，输尿管盆部经其后方下行；前列腺位于膀胱颈下方，不属膀胱后面的毗邻。"},{"q":"上腔静脉在注入右心房之前接受的静脉是","o":["奇静脉","半奇静脉","副半奇静脉","颈内静脉","锁骨下静脉"],"a":0,"e":"奇静脉沿胸主动脉右侧上行，至第4胸椎高度弓形向前越过右肺根注入上腔静脉；半奇静脉、副半奇静脉均汇入奇静脉。"},{"q":"有关内淋巴的描述，不正确的是","o":["位于膜迷路内","来自蜗管外侧壁","经内淋巴囊回流入血液循环","和外淋巴在蜗孔处相交通","可以传递声波"],"a":3,"e":"内淋巴位于膜迷路内，由蜗管外侧壁的血管纹产生，经内淋巴管至内淋巴囊回流入静脉；蜗孔只连通前庭阶与鼓阶内的外淋巴。"},{"q":"下列结构中，何者与精子的排出无关","o":["附睾","输精管","射精管","膀胱","尿道"],"a":3,"e":"精子经附睾、输精管、射精管进入尿道排出体外，膀胱为贮存尿液的器官，与精子的排出途径无关。"},{"q":"连于胃小弯的韧带是","o":["脾胃韧带","胃膈韧带","胃结肠韧带","脾肾韧带","肝胃韧带"],"a":4,"e":"小网膜由肝门移行于胃小弯和十二指肠上部，连于胃小弯的部分为肝胃韧带；胃脾韧带和胃结肠韧带连于胃大弯。"},{"q":"侧脑室，正确的选项是","o":["位于左、右侧大脑半球之间","侧脑室中央部位于室间孔和胼胝体压部之间","侧脑室经室间孔与第四脑室相通","后角伸入颞叶","前角伸向顶叶"],"a":1,"e":"侧脑室位于大脑半球内，中央部在顶叶内，为室间孔与胼胝体压部之间的部分；前角伸向额叶，后角伸入枕叶，经室间孔通第三脑室。"},{"q":"下列结构中不属于男性内生殖器的是","o":["前列腺","男性尿道","睾丸","阴茎","尿道球腺"],"a":3,"e":"男性内生殖器由生殖腺睾丸、输精管道（附睾、输精管、射精管、尿道）和附属腺（精囊、前列腺、尿道球腺）组成，阴茎与阴囊属外生殖器。"},{"q":"关于室间隔正确的描述是","o":["呈垂直位","大部分缺乏肌质","缺损多发生于膜部","主要由结缔组织构成","前、后缘的表面标志部明显"],"a":2,"e":"室间隔大部分为肌部，仅上方一小部分为膜部，膜部较薄且缺乏心肌，是室间隔缺损最常见的部位。"},{"q":"有关鼓膜的描述，正确的是","o":["构成鼓室外侧壁的大部分","位于内耳道与鼓室之间","婴儿鼓膜更为倾斜，近似呈垂直位","鼓膜边缘较薄，附着于颞骨鼓部和鳞部","鼓膜中心向内凹陷，称为鼓膜脐，内侧面为镫骨附着处"],"a":0,"e":"鼓膜构成鼓室外侧壁的大部分，位于外耳道底与鼓室之间，与外耳道底约成45°～50°角，小儿更倾斜，几乎呈水平位。"},{"q":"分泌雄性激素的器官是","o":["胸腺","睾丸","垂体","甲状腺","甲状旁腺"],"a":1,"e":"睾丸是男性生殖腺，位于阴囊内，生精小管产生精子，间质细胞分泌雄激素；垂体、甲状腺和甲状旁腺均不分泌雄激素。"},{"q":"界嵴分隔","o":["心房与心室","左心房与右心房","右心室的流入道与流出道","主动脉前庭与左心室","腔静脉窦与固有心房"],"a":4,"e":"右心房以界沟为界分为前部固有心房和后部腔静脉窦，腔面与界沟对应的纵行肌隆起即界嵴，故界嵴分隔腔静脉窦与固有心房。"},{"q":"颞下颌关节的特征不包括","o":["有关节盘","关节面覆盖透明软骨","囊外有外侧韧带加强","关节腔分上、下两部分","易向前脱位"],"a":1,"e":"颞下颌关节的关节面覆以纤维软骨而非透明软骨，关节盘将关节腔分为上、下两层，关节囊外侧有外侧韧带加强，易向前脱位。"},{"q":"属于椎旁神经节的是","o":["腹腔神经节","主动脉肾神经节","肠系膜上神经节","肠系膜下神经节","骶神经节"],"a":4,"e":"交感神经节分椎旁节和椎前节，骶交感干上的骶神经节属椎旁节；腹腔、主动脉肾及肠系膜上、下神经节均属椎前节。"},{"q":"左室前壁及室间隔前部心肌梗死，可能累及的血管是","o":["左冠状动脉主干","前室间支","旋支","后室间支","右冠状动脉主干"],"a":1,"e":"前室间支为左冠状动脉的直接延续，分布于左心室前壁、心尖、室间隔前2/3以及右心室前壁的一小部分。"},{"q":"腹内斜肌腱膜形成的结构不正确的是","o":["腹股沟镰","弓状线","腹白线","腹直肌鞘","精索内筋膜"],"a":4,"e":"腹内斜肌腱膜参与构成腹直肌鞘、腹白线、腹股沟镰和弓状线；精索内筋膜由腹横筋膜延续而来，与腹内斜肌无关。"},{"q":"右侧大脑半球中央旁小叶前部损害可引起","o":["左侧下肢肌瘫痪","右侧下肢肌瘫痪","左侧下肢皮肤感觉障碍","右侧下肢皮肤感觉障碍","右侧上肢肌瘫痪"],"a":0,"e":"中央旁小叶前部为下肢运动代表区，运动皮质支配对侧肢体，故右侧中央旁小叶前部损害引起对侧即左侧下肢肌瘫痪。"},{"q":"与泪腺分泌有关的神经节","o":["睫状神经节","下颌下神经节","耳神经节","翼腭神经节","颈上神经节"],"a":3,"e":"面神经的副交感节前纤维经岩大神经至翼腭神经节换元，节后纤维随颧神经、泪腺神经分布于泪腺，司泪液分泌。"},{"q":"关于肺静脉的正确描述是","o":["位于后纵隔内","每侧通常有一条","注入右心房","有静脉血流动","属于肺的功能性血管"],"a":4,"e":"肺静脉左右各两条，运载含氧丰富的动脉血回流入左心房，与肺动脉共同构成肺的功能性血管；营养肺的血管为支气管动脉。"},{"q":"喉上神经支配","o":["环杓后肌","环杓侧肌","环甲肌","甲杓肌","杓会厌肌"],"a":2,"e":"喉上神经外支支配环甲肌，收缩时拉长并紧张声带；喉内肌的其余各肌均由喉返神经支配。"},{"q":"关于肺的叙述，错误的是","o":["肺底又称为膈面","两肺的前缘都有心切迹","左肺的前缘有左肺小舌","肺与胸廓相邻的面称为肋面","纵隔面中央凹陷处称为肺门"],"a":1,"e":"仅左肺前缘下部有心切迹，其下方突起称左肺小舌；右肺前缘较平直，没有心切迹，两肺门前下方均有心压迹。"},{"q":"脊髓丘脑束","o":["包括脊髓丘脑前束和脊髓丘脑侧束","脊髓丘脑前束主要传导痛、温觉信息","脊髓丘脑侧束主要传导粗触觉、压觉信息","纤维起自脊神经节","经脊髓灰质Ⅰ和Ⅳ～Ⅷ层中继后止于背侧丘脑"],"a":0,"e":"脊髓丘脑束由脊髓丘脑侧束和脊髓丘脑前束组成，侧束传导痛、温觉，前束传导粗略触、压觉，均经白质前连合交叉后上行。"},{"q":"以下关于垂体的描述，哪项正确","o":["位于颅前窝的垂体窝内","分为前、中、后叶","产生的激素可影响甲状腺、肾上腺和性腺的分泌活动","分泌胰岛素","没有导管腺"],"a":2,"e":"腺垂体分泌促甲状腺激素、促肾上腺皮质激素和促性腺激素，分别促进甲状腺、肾上腺皮质和性腺的分泌活动。"},{"q":"具有伸膝关节的肌是","o":["股四头肌","缝匠肌","股二头肌","大收肌","小腿三头肌"],"a":0,"e":"股四头肌四个头合成一腱，包绕髌骨续为髌韧带止于胫骨粗隆，是伸膝关节的主要肌；股二头肌等腘绳肌则屈膝。"},{"q":"在骨连结，纤维连结包括","o":["骺软骨","棘间韧带","耻骨联合","椎间盘","骶椎合成骶骨"],"a":1,"e":"纤维连结包括韧带、缝和骨间膜，棘间韧带连于相邻棘突之间，属韧带连结；耻骨联合、椎间盘为软骨连结，骶椎融合为骨性结合。"},{"q":"与鼓室相通的管道是","o":["内耳道","外耳道","蜗管","骨半规管","咽鼓管"],"a":4,"e":"咽鼓管连通鼻咽部与鼓室，向后外开口于鼓室前壁，向前内开口于鼻咽部侧壁，可平衡鼓室内外的气压。"},{"q":"鼓室黏膜的感觉神经来源于","o":["上颌神经","舌咽神经","面神经","迷走神经","前庭蜗神经"],"a":1,"e":"鼓室黏膜的一般内脏感觉由舌咽神经的鼓室神经传导，经下神经节入脑止于孤束核；面神经只支配镫骨肌。"},{"q":"临床上做多项血液指标检查，采血最常见的血管是","o":["手背静脉网","贵要静脉","头静脉","肘正中静脉","前臂正中静脉"],"a":3,"e":"肘正中静脉在肘窝处连接头静脉和贵要静脉，位置表浅、管径较粗且变异多，是临床采血和静脉注射最常用的血管。"},{"q":"外伤损伤右侧端脑枕叶的患者会产生","o":["双眼左侧视野偏盲","左眼右侧视野偏盲","右眼右侧视野偏盲","右眼全盲","左眼全盲"],"a":0,"e":"视皮质一侧接受双眼同侧半视网膜的纤维，右侧视区受损时右眼颞侧、左眼鼻侧的视觉丧失，表现为双眼左侧视野同向性偏盲。"},{"q":"属于颈内动脉的直接分支的是","o":["后交通动脉","前交通动脉","大脑后动脉","小脑上动脉","迷路动脉"],"a":0,"e":"后交通动脉起自颈内动脉，向后与大脑后动脉吻合；大脑后动脉和小脑上动脉来自椎-基底动脉系，前交通动脉连接两侧大脑前动脉。"},{"q":"关于脑桥核正确的是","o":["位于脑桥基底部","位于脑桥被盖部","接受锥体束纤维传导来的信息","接受来自小脑皮质的运动信息","发出纤维参与形成小脑下脚"],"a":0,"e":"脑桥核为分散于脑桥基底部的神经元，接受同侧大脑皮质的皮质脑桥纤维，发出脑桥小脑纤维交叉后经小脑中脚入小脑。"},{"q":"关于直肠的叙述，错误的是","o":["直肠下段扩大称为直肠壶腹","直肠横襞是镜检的定位标志","在第2骶椎前起自乙状结肠","直肠骶曲凸向后","直肠会阴曲凸向前"],"a":2,"e":"直肠在第3骶椎前方起自乙状结肠，沿骶、尾骨前面下行，穿盆膈续于肛管；其骶曲凸向后，会阴曲凸向前。"},{"q":"嗅神经含有","o":["一般躯体感觉纤维","一般躯体运动纤维","特殊内脏感觉纤维","特殊内脏运动纤维","一般内脏运动纤维"],"a":2,"e":"嗅神经由上鼻甲和鼻中隔上部黏膜内嗅细胞的中枢突组成，司嗅觉，属特殊内脏感觉纤维，穿筛板筛孔入颅止于嗅球。"},{"q":"关于大隐静脉的正确描述是","o":["起自外踝前方","属于深静脉","经腹股沟韧带深面注入股静脉","收集除小腿外侧部的下肢静脉血液","深静脉回流受阻时可发生曲张"],"a":4,"e":"大隐静脉在足内侧缘起自足背静脉弓，经内踝前方上行，于隐静脉裂孔注入股静脉，属浅静脉；深静脉回流受阻或穿静脉瓣膜关闭不全时发生浅静脉曲张。"},{"q":"属于面神经的功能包括","o":["支配胸锁乳突肌","支配肩胛提肌","支配舌前2/3的味觉","支配舌前2/3的痛温觉","支配舌后1/3的味觉"],"a":2,"e":"面神经的鼓索含特殊内脏感觉和一般内脏运动纤维，前者司舌前2/3味蕾的味觉；舌前2/3一般感觉由三叉神经舌神经传导。"},{"q":"关节韧带的特征不包括","o":["连接相邻两骨","囊外韧带可与关节囊分离","是致密纤维结缔组织束","囊内韧带位于关节腔内","能增加关节的稳固"],"a":3,"e":"囊内韧带位于关节囊内但不在关节腔内，表面被滑膜包裹，如膝交叉韧带；关节腔仅含少量滑液，韧带不可能位于其中。"},{"q":"上肢骨与躯干骨连结的唯一的滑膜关节是","o":["胸锁关节","肩锁关节","肩关节","喙肩韧带","肩锁韧带"],"a":0,"e":"胸锁关节由锁骨的胸骨端与胸骨柄的锁切迹构成，是上肢骨与躯干骨之间唯一的滑膜关节，腔内有纤维软骨构成的关节盘。"},{"q":"阑尾根部的体表投影","o":["右髂前上棘与脐连线的中、外1/3交点","右髂前下棘与脐连线的中、外1/3交点","两侧髂前下棘连线的右、中1/3交点","两侧髂结节连线的右、中1/3交点","两侧髂前下棘连线的左、中1/3交点"],"a":0,"e":"阑尾根部体表投影通常在右髂前上棘与脐连线的中、外1/3交点处，即McBurney点，为阑尾炎的重要压痛点。"},{"q":"关于右冠状动脉正确的描述是","o":["起于主动脉前窦","窦房结的主要供血动脉","与心大静脉伴行","分布室间隔后2/3","由右心耳与主动脉根部穿出"],"a":1,"e":"右冠状动脉一般较粗大，约60%的人其右缘支或窦房结支供应窦房结，故为窦房结的主要供血动脉。"},{"q":"关于小脑髓质的描述，正确的是","o":["小脑深部的灰质团块","被小脑皮质包裹的白质纤维","位于最中间的小脑蚓","出入小脑的3对脚","小脑皮质与小脑核之间的联系纤维"],"a":1,"e":"小脑髓质是位于小脑皮质深部的白质，由出入小脑的纤维以及小脑皮质与小脑核之间的联系纤维构成，被小脑皮质包裹。"},{"q":"关于视网膜的叙述，错误的是","o":["视网膜的视部分为色素上皮层和神经层","视网膜属于眼球壁的内层","视网膜视部最大、最厚，附于脉络膜的内面","视网膜视部全都有感光的能力","视网膜分为虹膜部、睫状体部、脉络膜部3部分"],"a":3,"e":"视网膜视部由色素上皮层和神经层构成，后部最厚，视神经盘处无感光细胞，为生理盲点，故并非全部都有感光能力。"},{"q":"患者，女。食管下段癌症。试分析食管胸下段淋巴管大部分注入的是","o":["纵隔前淋巴结","胃左淋巴结和纵隔后淋巴结","颈外侧深淋巴结","气管支气管淋巴结","纵隔后淋巴结"],"a":1,"e":"食管胸下段的淋巴大部分注入胃左淋巴结，部分注入纵隔后淋巴结；胸上段则注入气管旁淋巴结和气管支气管淋巴结。"},{"q":"前列腺输出管开口于","o":["尿道海绵体部","尿道前列腺部","尿道膜部","尿道球部","射精管"],"a":1,"e":"前列腺的输出管开口于尿道前列腺部后壁尿道嵴的两侧，射精管则开口于精阜；前列腺部与膜部合称后尿道。"},{"q":"关于肠系膜上动脉描述正确的是","o":["供应范围包括空肠、升结肠、横结肠和降结肠","分支有左结肠动脉","平对第1腰椎高度起自腹主动脉前壁","分支包括胰十二指肠上动脉","分出直肠上动脉"],"a":2,"e":"肠系膜上动脉在腹腔干起点稍下方，约平第1腰椎高度起自腹主动脉前壁，分支供应胰头、小肠及右半结肠。"},{"q":"内脏大神经","o":["属于副交感神经节前纤维","属于交感神经节前纤维","属于交感神经节后纤维","属于内脏感觉纤维","属于副交感节后纤维"],"a":1,"e":"内脏大神经由T5～T9侧角发出的交感神经节前纤维组成，穿交感干后终止于腹腔神经节等椎前神经节。"},{"q":"有关呼吸道的描述，正确的是","o":["口腔属于上呼吸道","鼻属于上呼吸道","气管属于上呼吸道","喉属于下呼吸道","肺属于下呼吸道"],"a":1,"e":"呼吸道以喉为界，鼻、咽、喉为上呼吸道，气管和各级支气管为下呼吸道；口腔属消化器官，肺亦不属呼吸道。"},{"q":"掌浅弓","o":["由骨间总动脉与桡动脉末端吻合形成","由尺动脉的末端与桡动脉的末端吻合形成","由尺动脉末端与桡动脉掌浅支吻合形成","由尺动脉的掌深支与桡动脉的掌浅支吻合形成","与掌深弓没有吻合"],"a":2,"e":"掌浅弓由尺动脉末端与桡动脉掌浅支吻合而成，位于掌腱膜深面；掌深弓则由桡动脉末端与尺动脉掌深支吻合形成。"},{"q":"投射纤维是大脑髓质的主要纤维，它们大都经过内囊，其中下行的投射纤维不包括","o":["丘脑中央辐射","皮质脊髓束","额桥束","皮质核束","顶枕颞桥束"],"a":0,"e":"丘脑中央辐射自丘脑腹后核至中央后回，属上行感觉投射纤维；内囊下行的投射纤维有皮质脊髓束、皮质核束及额桥束、顶枕颞桥束。"},{"q":"穿过茎乳孔的是","o":["舌咽神经","面神经","副神经","舌下神经","脑膜中动脉"],"a":1,"e":"面神经穿内耳道底入面神经管，最后经茎乳孔出颅；舌咽、迷走和副神经经颈静脉孔出颅，舌下神经经舌下神经管出颅。"},{"q":"以下关于房水及其循环的描述中正确的是","o":["房水为无色透明的液体，无折光作用","房水由虹膜产生，充满眼房内","房水可为角膜和晶状体提供营养","房水循环受阻可降低眼内压","房水经瞳孔由眼前房进入后房"],"a":2,"e":"房水由睫状体产生，经后房、瞳孔至前房，再经虹膜角膜角渗入巩膜静脉窦回流入血，为角膜和晶状体提供营养并维持眼内压。"},{"q":"后角固有核位于脊髓灰质的","o":["Ⅰ～Ⅱ层","Ⅱ～Ⅲ层","Ⅲ～Ⅳ层","Ⅳ～Ⅴ层","Ⅴ～Ⅵ层"],"a":2,"e":"脊髓灰质Ⅲ、Ⅳ层内较大的细胞群组成后角固有核，接受后根传入纤维；Ⅰ～Ⅳ层相当于后角头，属外感受区。"},{"q":"胃网膜右动脉起自","o":["胰十二指肠上动脉","胃十二指肠动脉","脾动脉","肝固有动脉","肠系膜上动脉"],"a":1,"e":"肝总动脉发出胃十二指肠动脉，后者经幽门后方分为胃网膜右动脉和胰十二指肠上动脉；胃网膜左动脉起自脾动脉。"},{"q":"股骨的重要体表标志不包括","o":["股骨内侧髁","股骨大转子","股骨小转子","股骨外侧髁","收肌结节"],"a":2,"e":"大转子、内、外侧髁及收肌结节均可触及或定位，是重要骨性标志；小转子位于股骨颈内下方，位置深在，不能扪及。"},{"q":"与间脑相连的脑神经是","o":["三叉神经","面神经","动眼神经","视神经","滑车神经"],"a":3,"e":"12对脑神经中嗅神经连于端脑，视神经连于间脑，动眼神经和滑车神经连于中脑，三叉神经和面神经连于脑桥。"},{"q":"在脊柱，为椎体之间连结，有限制脊柱过度后伸和防止椎间盘向前脱出的韧带是","o":["棘上韧带","黄韧带","前纵韧带","后纵韧带","横突间韧带"],"a":2,"e":"前纵韧带位于椎体前面，宽而坚韧，上自枕骨大孔前缘下达骶椎，限制脊柱过度后伸并防止椎间盘向前脱出。"},{"q":"射精管开口于","o":["尿道海绵体部","尿道膜部","尿道球部","尿道前列腺部","舟状窝"],"a":3,"e":"射精管穿前列腺实质，开口于尿道前列腺部后壁的精阜；该部与膜部合称后尿道，海绵体部则称前尿道。"},{"q":"对鼓索的描述，哪项是错误的","o":["出鼓室后并入舌神经","出茎乳孔后入鼓室","其内脏运动纤维在下颌下神经节换元","味觉纤维分布于舌前2/3的味蕾","含有一般内脏运动节前纤维"],"a":1,"e":"鼓索在茎乳孔上方约6mm处自面神经管穿出，经鼓索后小管进入鼓室，再穿岩鼓裂出颅并入舌神经，并不经茎乳孔。"},{"q":"不属于腹膜内位的消化管是","o":["胃","横结肠","升结肠","乙状结肠","回肠"],"a":2,"e":"升结肠属腹膜间位器官，无系膜，借结缔组织贴附于腹后壁；胃、横结肠、乙状结肠和回肠均为腹膜内位器官。"},{"q":"胸长神经支配","o":["肩胛下肌","大圆肌","胸大肌","前锯肌","背阔肌"],"a":3,"e":"胸长神经沿胸侧壁下行支配前锯肌，该肌收缩时拉肩胛骨向前并紧贴胸廓；此神经损伤后肩胛骨内侧缘翘起，形成“翼状肩”。"},{"q":"延髓内的非脑神经核","o":["舌下神经核","疑核","薄束核","迷走神经背核","下泌涎核"],"a":2,"e":"延髓内的薄束核与楔束核为薄束、楔束的终止核，属非脑神经核；舌下神经核、疑核、迷走神经背核、下泌涎核均为脑神经核。"},{"q":"有关胸导管的描述正确的是","o":["注入右侧的静脉角","经食管裂孔进入胸腔","至第4胸椎高度斜行向左","不是全身最大的淋巴管","第12胸椎下缘高度起自乳糜池"],"a":4,"e":"胸导管是全身最大的淋巴管，平第12胸椎下缘起自乳糜池，经主动脉裂孔入胸腔，上行至颈部注入左静脉角。"},{"q":"不属于结肠上区的间隙是","o":["肝肾隐窝","右肝上前间隙","左肝下前间隙","网膜囊","右结肠旁沟"],"a":4,"e":"结肠上区为横结肠及其系膜以上的间隙，包括各肝上、肝下间隙和网膜囊；右结肠旁沟位于横结肠以下，属结肠下区。"},{"q":"屈髋并使股骨旋外的肌是","o":["臀大肌","臀中肌","臀小肌","梨状肌","髂腰肌"],"a":4,"e":"髂腰肌由腰大肌和髂肌组成，止于股骨小转子，收缩时使髋关节前屈并旋外，下肢固定时可使躯干前屈。"},{"q":"对于垂体的描述，哪项是错误的","o":["位于蝶骨体上面的垂体窝内","借漏斗向上连于下丘脑","可分为腺垂体和神经垂体两部分","神经垂体可分泌垂体素","腺垂体可分泌多种激素"],"a":3,"e":"神经垂体不含腺细胞，不能合成激素，只贮存和释放下丘脑视上核、室旁核产生的抗利尿激素和催产素。"},{"q":"一侧耳聋可能是由于什么结构受损引起的","o":["同侧前庭神经受损","对侧前庭神经受损","同侧蜗神经受损","对侧蜗神经受损","面神经受损"],"a":2,"e":"蜗神经传导螺旋器的听觉冲动，一侧蜗神经损伤引起同侧感音性耳聋；前庭神经受损则表现为眩晕和平衡障碍。"},{"q":"关于结肠的描述正确的是","o":["介于回肠和直肠之间","各部均有系膜","升结肠和横结肠转折处称为脾曲","乙状结肠是憩室和恶性肿瘤的多发部位","横结肠和降结肠转折处称为肝曲"],"a":3,"e":"乙状结肠有系膜、活动度大，是憩室和恶性肿瘤的多发部位；升结肠与横结肠转折处为结肠右曲，即肝曲。"},{"q":"直肠的淋巴管注入的是","o":["腹股沟深淋巴结","髂总淋巴结","骶淋巴结","腹股沟浅淋巴结","髂外淋巴结"],"a":2,"e":"直肠的淋巴除沿直肠上血管注入直肠上淋巴结外，尚沿骶外侧血管注入骶淋巴结；齿状线以下者注入腹股沟浅淋巴结。"},{"q":"关于眼的静脉的描述，错误的是","o":["眼下静脉可注入翼静脉丛","向前与面静脉有吻合","向后面注入海绵窦","面部感染可经眼静脉侵入海绵窦，引起颅内感染","涡静脉收纳虹膜的静脉血"],"a":4,"e":"涡静脉为眼球血管膜的主要静脉，收集脉络膜和睫状体的静脉血，汇入眼上、下静脉；虹膜的血液则主要经睫状前静脉回流。"},{"q":"表面有结肠带的肠管","o":["空肠","回肠","盲肠","阑尾","直肠"],"a":2,"e":"结肠带、结肠袋和肠脂垂为结肠和盲肠的特征性结构，结肠带由纵行肌增厚形成并汇聚于阑尾根部；直肠、肛管和阑尾无此三特征。"},{"q":"患者车祸入院治疗，经检查发现患者右侧上肢瘫痪，其损伤部位在","o":["左侧中央前回上部","左侧中央前回下部","左侧旁中央小叶","右侧中央前回","右侧旁中央小叶"],"a":1,"e":"官方题库缺失图片"},{"q":"与后室间支伴行的静脉","o":["心大静脉","心中静脉","心小静脉","心前静脉","心最小静脉"],"a":1,"e":"心中静脉位于后室间沟内，与后室间支伴行，收纳左右心室后壁、室间隔后部和心尖部的静脉血，注入冠状窦。"},{"q":"一患者经检查发现为感觉性失语症，损伤的部位位于","o":["舌叶","额下回后1/3部","额中回后部","缘上回","角回"],"a":3,"e":"感觉性失语为听觉性语言中枢受损，患者能听到声音但不理解语义；该中枢位于颞上回后部，与缘上回、角回共同构成Wernicke区。"},{"q":"下列核团中哪个属于后丘脑","o":["枕","背外侧核","腹后外侧核","内侧膝状体","后外侧核"],"a":3,"e":"后丘脑包括内侧膝状体和外侧膝状体，分别接受听觉和视觉纤维，属特异性中继核；腹后外侧核属背侧丘脑。"},{"q":"具有使髋关节外展的肌是","o":["臀大肌","臀中肌","半腱肌","半膜肌","股二头肌"],"a":1,"e":"臀中肌起自髂骨翼外面，止于股骨大转子，是髋关节外展的主要肌；臀大肌伸髋，半腱肌、半膜肌和股二头肌屈膝。"},{"q":"俯视时，收缩的眼球外肌为","o":["上斜肌和下直肌","下斜肌和下直肌","下斜肌和内直肌","上直肌和下斜肌","上直肌和上斜肌"],"a":0,"e":"俯视时两眼的下直肌与上斜肌同时收缩，使瞳孔分别转向下内和下外；仰视时则为上直肌与下斜肌。"},{"q":"椎骨的一般形态不包括","o":["前方的椎体","后方的椎弓","椎弓分椎弓根和椎弓板","椎弓板发出5个突起","棘突1个"],"a":3,"e":"椎弓发出7个突起，即1个棘突、1对横突、1对上关节突和1对下关节突；椎体与椎弓共同围成椎孔。"},{"q":"关于心尖正确的描述是","o":["朝向前下方","平对第5肋间","由左心室形成","偏左侧有心尖切迹","位于心脏裸区"],"a":2,"e":"心尖圆钝而游离，由左心室构成，朝向左前下方，体表位于左侧第5肋间隙锁骨中线内侧1～2cm处。"},{"q":"神经组织的两种主要细胞","o":["神经细胞和胶质细胞","神经元和星形胶质细胞","神经细胞和少突胶质细胞","星形胶质细胞和少突胶质细胞","神经元和施万细胞"],"a":0,"e":"神经组织由神经细胞和神经胶质细胞两种主要细胞构成，前者感受刺激、传导冲动，后者起支持、营养、绝缘和保护作用。"},{"q":"关于晶状体的描述，错误的是","o":["位于虹膜的后方、玻璃体的前方","呈双凸透镜状，无色透明，有丰富的血管和神经","晶状体外面包以具有高度弹性的晶状体囊","晶状体实质由平行排列的晶状体纤维所组成","晶状体若因疾病或创伤而变混浊，称为白内障"],"a":1,"e":"晶状体位于虹膜与玻璃体之间，呈双凸透镜状，无色透明、富有弹性，不含血管和神经，其营养来自房水。"},{"q":"面部的危险三角感染导致颅内感染是由于","o":["面静脉与海绵窦有交通支","面静脉与乙状窦有交通支","面静脉通过板障静脉与颅内交通","面静脉与上矢状窦有交通支","面静脉与横窦有交通支"],"a":0,"e":"面静脉经眼上静脉和眼下静脉与海绵窦交通，并经面深静脉通翼静脉丛；口角以上面静脉缺乏静脉瓣，面部感染可逆行入颅。"},{"q":"男性尿道分为","o":["前列腺部、膜部、阴茎部","前列腺部、膜部、尿道球部","前列腺部、膜部、海绵体部","前列腺部、膜部、后尿道","前列腺部、海绵体部"],"a":2,"e":"男性尿道分前列腺部、膜部和海绵体部，前列腺部与膜部合称后尿道，海绵体部称前尿道。"},{"q":"关于锁骨下动脉错误的说法是","o":["锁骨中点上方锁骨上窝为该动脉的止血点","在颈根部行经前、中斜角肌之间","在颈根部斜越胸膜顶前方","右侧锁骨下动脉起自头臂干","所有分支均分布于上肢"],"a":4,"e":"锁骨下动脉除供应上肢外，还发出椎动脉、胸廓内动脉、甲状颈干和肋颈干，分布于脑、脊髓、胸前壁及颈部等处。"},{"q":"本体感受器的分布不包括","o":["骨骼肌","肌腱","关节","基底膜","膜壶腹"],"a":3,"e":"本体感受器分布于骨骼肌、肌腱、关节囊和内耳膜壶腹等处；基底膜上的螺旋器是听觉感受器。"},{"q":"关于锁骨下动脉的叙述，错误的是","o":["左锁骨下动脉起自主动脉弓，右锁骨下动脉起自头臂干","其分支有椎动脉、胸廓内动脉、甲状颈干和肋颈干","其体表投影为：自胸锁关节至锁骨中点画一凸向上的线，最凸处在锁骨上方1.5cm","其压迫止血部位为：在锁骨中点向下压，将动脉压在第3肋骨上","压迫该动脉其止血范围包括整个上肢"],"a":3,"e":"锁骨下动脉的压迫止血点在锁骨中点上方的锁骨上窝，向后下压向第1肋骨；其体表投影最凸处在锁骨上方约1.5cm。"},{"q":"关于面静脉的起始和特点，正确的是","o":["注入颈外静脉","通过面深静脉与海绵窦交通","缺乏静脉瓣","起自翼静脉丛","属于深静脉"],"a":2,"e":"面静脉起自内眦静脉，与眼静脉、面深静脉和翼静脉丛交通，口角以上一般缺乏静脉瓣，故面部感染易致海绵窦炎。"},{"q":"营养甲状腺的血管中，甲状腺下动脉来自于","o":["颈外动脉","颈内动脉","胸廓内动脉","甲状颈干","颈总动脉"],"a":3,"e":"甲状腺下动脉起自甲状颈干，该干在椎动脉外侧、前斜角肌内侧缘附近起始，还发出肩胛上动脉等分支。"},{"q":"颅前窝骨折，可能引起","o":["视神经损伤","嗅神经损伤","动眼神经损伤","滑车神经损伤","三叉神经损伤"],"a":1,"e":"颅前窝底即筛板，嗅丝穿筛孔入颅，颅前窝骨折时易撕裂嗅丝而致嗅觉障碍，并可出现脑脊液鼻漏。"},{"q":"关于舌的叙述，错误的是","o":["颏舌肌两侧收缩时伸舌向前下","舌根和舌体在舌的下面以界沟为界","舌根背部黏膜内有舌扁桃体","舌下面中线上有舌系带，其根部的两侧有舌下阜","舌下襞深面有舌下腺"],"a":1,"e":"舌以舌背的V形界沟分为前2/3的舌体和后1/3的舌根，界沟尖端有舌盲孔；舌下面中线有舌系带及舌下阜、舌下襞。"},{"q":"下列选项中不属于小脑核的是","o":["栓状核","球状核","红核","顶核","齿状核"],"a":2,"e":"小脑核包括齿状核、栓状核、球状核和顶核；红核位于中脑被盖，属锥体外系核团，不属小脑核。"},{"q":"节制索位于","o":["右心房","右心室","左心房","左心室","房间隔"],"a":1,"e":"节制索又称调节束，为右心室腔内横过室腔的一条肌束，自室间隔连至前乳头肌根部，可防止心室过度扩张。"},{"q":"可牵拉肩胛骨向前的肌是","o":["胸大肌","肩胛下肌","前锯肌","斜方肌","菱形肌"],"a":2,"e":"前锯肌收缩时拉肩胛骨向前并紧贴胸廓，其下部肌束使肩胛骨下角旋外；菱形肌则牵拉肩胛骨向后内。"},{"q":"脊髓圆锥","o":["脊髓的膨大部分","脊髓末端变细的部分","约平对第2腰椎下缘","由结缔组织组成","附着于尾骨背面"],"a":1,"e":"脊髓下端逐渐变细呈圆锥状，称脊髓圆锥，末端约平第1腰椎下缘，向下续为终丝止于第1尾椎背面。"},{"q":"关于脊柱的侧面观特征不正确的是","o":["有4个生理性的弯曲","腰曲和骶曲在胚胎时已形成","颈曲凸向前","颈曲支持头的抬起","胸曲凹向后"],"a":1,"e":"胚胎时已形成的是胸曲和骶曲，二者均凸向后；颈曲和腰曲在出生后随抬头、坐起和站立行走逐渐形成，凸向前。"},{"q":"属于脑神经的感觉神经节的是","o":["膝神经节","翼腭神经节","下颌下神经节","耳神经节","睫状神经节"],"a":0,"e":"膝神经节为面神经的感觉神经节，含假单极神经元胞体；翼腭、下颌下、耳和睫状神经节均属副交感神经节。"},{"q":"女性易发生逆行性尿路感染，是因为","o":["前上方与阴蒂相邻","膀胱容积大","尿道短、宽而直","尿道开口于阴道前庭","女性抵抗力差"],"a":2,"e":"女性尿道长约3～5cm，较男性短、宽而直，外口又邻近阴道前庭，细菌易逆行侵入膀胱引起尿路感染。"},{"q":"松果体位于","o":["脚间窝","上髓帆上方","视交叉后方","上丘上方","下丘脑前方"],"a":3,"e":"松果体位于上丘脑的后上方，以柄连于第三脑室顶的后部，儿童期发达，7岁左右开始退化并可钙化形成脑砂。"},{"q":"甲状腺的淋巴注入的淋巴结是","o":["颏下淋巴结","下颌下淋巴结","耳后淋巴结","咽后淋巴结","气管旁淋巴结"],"a":4,"e":"甲状腺的淋巴注入甲状腺淋巴结、气管前淋巴结和气管旁淋巴结，再汇入颈外侧深淋巴结；甲状腺峡部者多入气管前淋巴结。"},{"q":"胸骨的形态结构特征包括","o":["成人胸骨体内含有黄骨髓","分为胸骨体和胸骨柄2个部分","与肋软骨都以关节相连","胸骨体左右外侧缘接第1～7肋软骨","上缘有颈静脉切迹"],"a":4,"e":"胸骨柄上缘中份为颈静脉切迹，两侧有锁切迹；胸骨由柄、体和剑突构成，胸骨体侧缘接第2～7肋软骨。"},{"q":"肺的描述中，正确的是","o":["位于胸膜腔内","肺尖高度不超过锁骨水平","左、右肺形态相同","右肺有斜裂和水平裂","外侧缘中部有肺门"],"a":3,"e":"右肺由斜裂和水平裂分为上、中、下三叶，左肺只有斜裂分为上、下两叶；肺位于胸腔内而不在胸膜腔内。"},{"q":"有关肺根的叙述，错误的是","o":["左肺根上方有主动脉弓跨过","右肺根上方有奇静脉弓跨过","肺动脉位于肺根内最前方","迷走神经行于肺根后方","膈神经行于肺根前方"],"a":2,"e":"两肺根内结构自前向后为上肺静脉、肺动脉、主支气管和下肺静脉，故肺动脉并非最前；膈神经经肺根前方，迷走神经经其后方。"},{"q":"关于右肺的形态，描述错误的是","o":["通常分3叶","分10个肺段","有斜裂和水平裂","较左肺宽而短","前缘有心切迹"],"a":4,"e":"心切迹位于左肺前缘下部，右肺前缘无此切迹；右肺通常分3叶、10个肺段，有斜裂与水平裂，较左肺宽而短。"},{"q":"关于颈外静脉的正确描述是","o":["由面静脉和下颌后静脉汇合形成","沿胸锁乳突肌深面下行","注入锁骨下静脉或静脉角","主要收集颈部的静脉血","坐立时可显露"],"a":2,"e":"颈外静脉由下颌后静脉后支、耳后静脉和枕静脉汇合而成，沿胸锁乳突肌表面下行，穿深筋膜注入锁骨下静脉或静脉角。"},{"q":"下列关于玻璃体的描述中，正确的是","o":["玻璃体位于虹膜与晶状体之间","富含血管神经","玻璃体前面凹陷称玻璃体凹","玻璃体对视网膜起营养作用","玻璃体发生混浊时，不影响视力"],"a":2,"e":"玻璃体填充于晶状体与视网膜之间，约占眼球内腔的后4/5，前面以晶状体及睫状小带为界形成玻璃体凹，对视网膜起支撑作用。"},{"q":"脊髓的交感神经低级中枢位于","o":["脊髓网状结构","后角固有核","胸核","中间外侧核","中间内侧核"],"a":3,"e":"脊髓中间带外侧核位于T1～L3节段侧角，是交感神经节前神经元胞体所在部位，即交感神经的低级中枢。"},{"q":"关于甲状软骨的描述，正确的是","o":["前角借韧带和舌骨大角相连","上角上方为上切迹","下角与杓状软骨相关节","前角上端为喉结","左右软骨板后方连接形成后角"],"a":3,"e":"甲状软骨左右软骨板前缘的融合处为前角，前角上端向前突出即喉结，成年男性明显，其上方有V形的上切迹。"},{"q":"受损致患者瞳孔转向内侧的脑神经","o":["视神经","动眼神经","展神经","面神经","滑车神经"],"a":2,"e":"展神经支配外直肌，该肌收缩使瞳孔转向外侧，展神经损伤则眼球不能外展并出现内斜视。"},{"q":"前庭蜗神经纤维瘤时，患者除了有听力障碍和小脑损伤的症状外，肿瘤还可压迫位于附近的哪些神经","o":["动眼神经、滑车神经、面神经和迷走神经","展神经、三叉神经、舌咽神经和迷走神经","动眼神经、三叉神经、舌咽神经和迷走神经","面神经、三叉神经、舌咽神经和舌下神经","面神经、三叉神经、舌咽神经和迷走神经"],"a":4,"e":"前庭蜗神经根位于脑桥小脑三角，该处肿瘤可压迫邻近的面神经、三叉神经、舌咽神经和迷走神经而出现相应症状。"},{"q":"有关锥体系描述正确的是","o":["皮质核束支配双侧脑神经","分为皮质脊髓束和皮质核束","下行纤维都在延髓下端交叉","受损后，反射消失，但骨骼肌不萎缩","起始于中央后回及中央旁小叶后部"],"a":1,"e":"锥体系由中央前回等处皮质发出的下行纤维构成，分为皮质脊髓束和皮质核束，前者大部分纤维在延髓锥体交叉。"},{"q":"分布于舌的脑神经有","o":["滑车神经","三叉神经","副神经","迷走神经","鼻睫神经"],"a":1,"e":"三叉神经的分支舌神经分布于舌前2/3黏膜，传导一般感觉；舌前2/3的味觉则由面神经鼓索传导。"},{"q":"子宫的描述中，正确的是","o":["分为体、颈、峡三部分","子宫内腔即子宫腔","颈部全部位于阴道内","峡部在非妊娠期明显","子宫颈管下通阴道"],"a":4,"e":"子宫颈管呈梭形，上通子宫腔，下口通阴道称子宫口；子宫颈分阴道部和阴道上部，仅阴道部突入阴道。"},{"q":"左纤维三角的位置是","o":["左、右房室口之间","主动脉口与左房室口之间","主动脉口与右房室口之间","肺动脉口与左房室口之间","肺动脉口与右房室口之间"],"a":1,"e":"左纤维三角位于主动脉口与左房室口之间，右纤维三角位于左、右房室口与主动脉口之间，均属心纤维性支架。"},{"q":"运动时使拇指掌面与小指掌面相对的肌是","o":["拇短展肌","拇长屈肌","拇短屈肌","拇对掌肌","拇收肌"],"a":3,"e":"拇对掌肌起自第1掌骨，止于拇指掌骨外侧缘，使拇指对掌，即拇指掌面与小指掌面相对；拇收肌则内收拇指。"},{"q":"面神经内含有","o":["红核的纤维","上泌涎核的纤维","下泌涎核的纤维","下橄榄核的纤维","上橄榄核的纤维"],"a":1,"e":"面神经含一般内脏运动纤维，起自上泌涎核，经翼腭神经节和下颌下神经节换元后支配泪腺、下颌下腺和舌下腺。"},{"q":"纵隔的不同部位可发生不同的肿瘤，其中常发生于中纵隔的是","o":["胸腺瘤","心包囊肿","淋巴瘤","主动脉瘤","支气管囊肿"],"a":1,"e":"中纵隔容纳心包及出入心的大血管，是心包囊肿的好发部位；胸腺瘤位于前纵隔，支气管囊肿多见于中、后纵隔。"},{"q":"一患者在肛瘘手术后大便失禁，可能切断了以下哪些肌肉","o":["肛门外括约肌","肛门外括约肌浅部、深部，肠壁纵行肌，肛门内括约肌，耻骨直肠肌","肛门外括约肌和肛门内括约肌","肛提肌、肛门外括约肌皮下部和肛门内括约肌","肛门内括约肌和肛门外括约肌皮下部"],"a":1,"e":"肛直肠环由肛门外括约肌浅部、深部，直肠下份纵行肌，肛门内括约肌以及肛提肌共同构成，手术损伤即致大便失禁。"},{"q":"子宫的形态","o":["子宫分为头、体、颈三部分","子宫与阴道相通，不与输卵管相通","子宫颈全部被阴道包绕","子宫口是子宫颈管的下口","子宫峡正常约5cm长"],"a":3,"e":"子宫腔呈前后扁的倒三角形，上两端通输卵管，尖端向下续为子宫颈管，子宫颈管下口通阴道称子宫口；非妊娠期子宫峡仅约1cm。"},{"q":"膈的腔静脉孔约平对","o":["第8胸椎","第9胸椎","第10胸椎","第11胸椎","第12胸椎"],"a":0,"e":"膈的腔静脉孔位于中心腱内，约平第8胸椎，有下腔静脉通过；食管裂孔平第10胸椎，主动脉裂孔平第12胸椎。"},{"q":"关于精囊的描述正确的是","o":["为单一的囊状器官","位于膀胱前方","由附睾管构成","可储存精子","其输出管与输精管壶腹末端合成射精管"],"a":4,"e":"精囊为成对的囊状器官，位于膀胱底后方、输精管壶腹外侧，其排出管与输精管壶腹末端汇合成射精管；贮存精子的是附睾。"},{"q":"没有结肠带的肠管是","o":["横结肠","盲肠","直肠","乙状结肠","升结肠"],"a":2,"e":"结肠带、结肠袋和肠脂垂见于结肠和盲肠，直肠、肛管和阑尾没有结肠带，故直肠不具此特征性结构。"},{"q":"当上肢上举固定时，可作引体向上活动的肌是","o":["斜方肌","背阔肌","肩胛提肌","菱形肌","竖脊肌"],"a":1,"e":"背阔肌为全身最大的扁肌，收缩时使肩关节后伸、内收和旋内；当上肢上举固定时，可协助完成引体向上。"},{"q":"以下关于舌下神经描述正确的是","o":["司舌下腺的分泌","损伤时舌肌无萎缩","含有特殊内脏运动纤维","支配全部的舌内肌和舌外肌","一侧舌下神经损伤，患者伸舌舌尖偏向患侧"],"a":4,"e":"舌下神经支配全部舌内肌和大部分舌外肌，一侧损伤时同侧舌肌瘫痪萎缩，伸舌时舌尖偏向患侧。"},{"q":"不含有味蕾的结构","o":["菌状乳头","轮廓乳头","丝状乳头","叶状乳头","软腭黏膜"],"a":2,"e":"味蕾分布于轮廓乳头、菌状乳头、叶状乳头以及软腭、会厌等处的黏膜；丝状乳头数目最多但无味蕾，仅有触觉作用。"},{"q":"支配舌后三分之一特殊内脏感觉的脑神经是","o":["副神经","舌下神经","滑车神经","舌咽神经","三叉神经"],"a":3,"e":"舌咽神经含特殊内脏感觉纤维，胞体位于下神经节，周围突分布于舌后1/3的味蕾，中枢突止于孤束核上部。"},{"q":"椎体和椎弓围成","o":["椎间孔","椎孔","横突孔","骶前孔","骶后孔"],"a":1,"e":"椎体后面与椎弓共同围成椎孔，各椎孔上下贯通构成椎管，容纳脊髓；相邻椎弓根之间的孔为椎间孔。"},{"q":"眼副器不包括","o":["眼球外肌","眼睑","结膜","泪器","房水"],"a":4,"e":"眼副器包括眼睑、结膜、泪器、眼球外肌、眶脂体和眶筋膜；房水属眼球内容物，与角膜、晶状体、玻璃体合称屈光装置。"},{"q":"声门裂以下黏膜的感觉神经是","o":["面神经","舌咽神经","喉返神经","喉上神经外支","喉上神经内支"],"a":2,"e":"声门裂以下的喉黏膜感觉由喉返神经即喉下神经传导，声门裂以上者由喉上神经内支传导；喉上神经外支支配环甲肌。"},{"q":"肝外胆道不包括","o":["肝左管","肝右管","胆囊管","胰管","肝总管"],"a":3,"e":"肝外胆道系统包括胆囊和输胆管道，后者由肝左管、肝右管、肝总管和胆总管组成；胰管属胰的排泄管道。"},{"q":"一患者损伤左侧大脑半球角回，下列哪项与角回无关","o":["围绕外侧沟后端","围绕颞上沟末端","又称阅读中枢","损伤可导致失读症","损伤后无视觉障碍"],"a":0,"e":"角回位于顶下小叶，围绕颞上沟末端，为视觉性语言中枢即阅读中枢，损伤后视觉正常但不能阅读，称失读症。"},{"q":"右肾门前面毗邻的组织器官是","o":["肝方叶","十二指肠降部","结肠右曲","胆囊","肠系膜血管"],"a":1,"e":"右肾内侧缘与十二指肠降部相贴，肾门前方主要为十二指肠降部。肝方叶邻右肾前上部，结肠右曲邻右肾下部，二者不直接贴邻肾门。"},{"q":"神经节是指","o":["神经元树突的集合","神经元胞体在中枢的集合","神经元胞体在周围的集合","神经元轴突的集合","神经元胞体与树突的集合"],"a":2,"e":"周围部神经元胞体聚集处称神经节，中枢内胞体聚集则称灰质或神经核。神经节由节内神经元胞体及卫星细胞构成，并非单纯树突或轴突的集合。"},{"q":"下丘脑属于","o":["中脑","间脑","端脑","小脑","脑桥"],"a":1,"e":"间脑包括背侧丘脑、后丘脑、上丘脑、底丘脑和下丘脑五部分，下丘脑位于第三脑室侧壁下部，属间脑。中脑、脑桥归脑干，端脑为大脑半球。"},{"q":"关于脑神经进出脑的部位，正确的是","o":["延髓脑桥沟内有面神经","中脑脚间窝内有视神经","延髓锥体前方有舌下神经","小脑背面有动眼神经","小脑中脚有展神经"],"a":0,"e":"延髓脑桥沟内自中线向外侧依次连有展神经、面神经和前庭蜗神经根。视神经连于间脑，舌下神经经锥体与橄榄之间出脑，动眼神经自脚间窝出脑。"},{"q":"以下不属于肾上腺分泌的激素的是","o":["盐皮质激素","糖皮质激素","性激素","去甲肾上腺素","促肾上腺激素释放激素"],"a":4,"e":"促肾上腺皮质激素释放激素由下丘脑合成，经垂体门脉系统作用于腺垂体，并非肾上腺分泌。肾上腺皮质分泌盐、糖皮质激素和性激素，髓质分泌肾上腺素和去甲肾上腺素。"},{"q":"前庭神经","o":["传导本体感觉","起自内耳门处前庭神经节双极神经元","在橄榄体上端入脑","与蜗神经同行，在延髓脑桥沟外侧端入脑","全部纤维终止于延髓内的前庭神经核"],"a":3,"e":"前庭神经与蜗神经伴行，经内耳门入颅，在延髓脑桥沟外侧部入脑，终止于前庭神经核群和小脑，传导平衡觉；前庭神经节位于内耳道底而非内耳门处。"},{"q":"三叉丘系为","o":["同侧三叉神经半月节发出的纤维组成","对侧三叉神经半月节发出的纤维组成","同侧三叉神经感觉核发出的纤维组成","对侧三叉神经感觉核发出的纤维组成","对侧三叉神经感觉纤维的直接延续"],"a":3,"e":"三叉丘系又称三叉丘脑束，由对侧三叉神经脊束核和双侧三叉神经脑桥核发出的二级感觉纤维组成，终止于背侧丘脑腹后内侧核，传导头面部痛温觉。"},{"q":"关于脾的位置正确的是","o":["左侧第9～11肋深面","胃底前面","胰尾上方","左肋弓下方","结肠左曲后方"],"a":0,"e":"脾位于左季肋部，胃底与膈之间，第9～11肋深面，长轴与第10肋一致，正常时左肋弓下不能触及。脾借胃脾、脾肾等韧带固定。"},{"q":"疑核发出的纤维加入","o":["前庭蜗神经","舌咽神经","面神经和迷走神经","舌下神经和迷走神经","舌下神经和副神经"],"a":1,"e":"疑核上部发出的纤维进入舌咽神经，支配茎突咽肌；中部纤维加入迷走神经，支配软腭、咽和喉肌；下部纤维构成副神经脑根。"},{"q":"有关脑蛛网膜的描述，下面正确的是","o":["富有血管神经","与硬脊膜之间有硬膜外隙","与软脑膜之间有软脑膜下隙","与软脑膜之间的腔隙内充满脑脊液","与硬脊膜之间为蛛网膜下隙"],"a":3,"e":"脑蛛网膜薄而透明，缺乏血管神经，与硬脑膜间为硬膜下隙，与软脑膜间为蛛网膜下隙，隙内充满脑脊液。硬膜外隙位于硬脊膜与椎管壁之间。"},{"q":"前列腺分为5叶，不包括","o":["前叶","后叶","中叶","周边叶","两侧叶"],"a":3,"e":"前列腺分前叶、中叶、后叶和两侧叶五叶，无周边叶。前叶很小，位于尿道前方和左、右侧叶之间；后叶位于尿道后方。"},{"q":"关于胸腔器官淋巴结的叙述，正确的是","o":["纵隔前淋巴结的输出淋巴管注入胸导管","肺淋巴结沿支气管血管排列","支气管肺淋巴结又称肺门淋巴结","气管旁淋巴结沿气管杈排列","纵隔后淋巴结的输出淋巴管参与合成支气管纵隔干"],"a":2,"e":"支气管肺门淋巴结位于肺门处，又称肺门淋巴结，收纳肺和食管的淋巴，输出管注入气管支气管淋巴结。纵隔前淋巴结的输出管参与合成支气管纵隔干。"},{"q":"与胫、腓骨下端组成踝关节的结构是","o":["跟骨结节","足舟骨","距骨滑车","骰骨","内侧楔骨"],"a":2,"e":"踝关节由胫、腓骨下端与距骨滑车构成，属屈戌关节。距骨滑车前宽后窄，跖屈时较窄的后部入窝，关节不稳，故扭伤多发生于跖屈位。"},{"q":"脑干内的一般内脏运动核","o":["动眼神经核、迷走神经背核、疑核","上泌涎核、下泌涎核、迷走神经背核","孤束核、迷走神经背核、疑核","孤束核、迷走神经背核、动眼神经核","面神经核、迷走神经背核、动眼神经核"],"a":1,"e":"脑干一般内脏运动核即副交感核，包括动眼神经副核、上泌涎核、下泌涎核和迷走神经背核，发出节前纤维支配头颈胸腹的平滑肌、心肌和腺体；疑核属特殊内脏运动核。"},{"q":"关于子宫描述正确的是","o":["子宫颈低于坐骨棘平面","子宫前倾为子宫颈与体之间形成的钝角","子宫峡为子宫颈阴道上部的上端与子宫体相连的部分","子宫的固定装置不包括盆底的肌肉","其交感神经来自盆内脏神经"],"a":2,"e":"子宫颈上端与子宫体相接处较狭窄，称子宫峡，非孕时长约1cm，妊娠期伸展形成子宫下段。子宫颈下端位于坐骨棘平面稍上方而非下方。"},{"q":"肺和胸膜的体表投影不同，主要区别是","o":["肺尖低于胸膜顶1cm","在胸腺区，肺与胸膜前界的体表投影差别大","在锁骨中线肺下界较胸膜下界高两个肋","在心包区，右肺与右侧胸膜前界体表投影差别大","在前正中线左、右两侧肺下界与胸膜下界体表投影差别大"],"a":2,"e":"同一部位肺下界较胸膜下界高出约两个肋，如锁骨中线肺下缘平第6肋、胸膜下界平第8肋。肺尖低于胸膜顶，胸膜前界在胸腺区左右靠拢。"},{"q":"面神经连接脑的部位","o":["延髓上端","小脑中脚中下份","延髓脑桥沟靠近锥体上端处","延髓脑桥沟外侧","延髓脑桥沟中线两侧"],"a":3,"e":"面神经连于延髓脑桥沟外侧部，经内耳门、内耳道、面神经管，最后由茎乳孔出颅。展神经在沟内侧靠近中线处出脑，前庭蜗神经居其外侧。"},{"q":"颅内肿瘤的患者出现厌食，肿瘤可能压迫到了","o":["下丘脑前区内侧","下丘脑后区外侧","下丘脑外侧区","下丘脑前区","下丘脑后区"],"a":2,"e":"下丘脑外侧部为摄食中枢，损毁后引起厌食、消瘦；腹内侧核为饱食中枢，损毁则多食肥胖。肿瘤压迫外侧区可出现厌食。"},{"q":"关于卵巢的叙述，错误的是","o":["位于卵巢窝内","属于腹膜内位器官","后缘中部血管神经出入处称卵巢门","上端连卵巢悬韧带","下端连卵巢固有韧带"],"a":2,"e":"卵巢前缘借卵巢系膜连于阔韧带，称卵巢系膜缘，其中部有血管神经出入，称卵巢门；后缘游离为独立缘。卵巢属腹膜内位器官，上端连卵巢悬韧带，下端连卵巢固有韧带。"},{"q":"孤束核接受的神经纤维来自","o":["第Ⅴ、Ⅵ和Ⅶ对脑神经","第Ⅵ、Ⅶ和Ⅷ对脑神经","第Ⅶ、Ⅷ和Ⅸ对脑神经","第Ⅷ、Ⅸ和Ⅹ对脑神经","第Ⅶ、Ⅸ和Ⅹ对脑神经"],"a":4,"e":"孤束核位于延髓内界沟外侧，其上、下部接受经面神经、舌咽神经和迷走神经传入的味觉及一般内脏感觉纤维，即第Ⅶ、Ⅸ、Ⅹ对脑神经。"},{"q":"副神经脑根起于","o":["副神经核","疑核","孤束核","上泌涎核","下泌涎核"],"a":1,"e":"副神经脑根起自疑核下部，纤维出颅后离开副神经加入迷走神经，经喉返神经支配除环甲肌以外的喉肌；脊髓根起自副神经核。"},{"q":"脑干背面出颅的脑神经是","o":["滑车神经","三叉神经","展神经","面神经","前庭蜗神经"],"a":0,"e":"滑车神经根在下丘下方、上髓帆处出脑，是唯一自脑干背侧面出脑的脑神经，经眶上裂入眶支配上斜肌；其余脑神经均自脑干腹侧或侧方出脑。"},{"q":"齿状韧带","o":["由蛛网膜形成","由硬脊膜形成","其作用是将脊髓的血管固定在椎管上","由软脊膜在脊髓两侧脊神经前、后根之间形成","其尖端附于脊髓上"],"a":3,"e":"齿状韧带由软脊膜在脊髓两侧脊神经前、后根之间形成，呈齿状，尖端附于硬脊膜，起固定脊髓的作用。硬脊膜与椎管壁之间为硬膜外隙。"},{"q":"关于胫后动脉的叙述，错误的是","o":["该动脉发自腘动脉","其主要分支包括腓动脉、足底内侧动脉和足底外侧动脉","其体表投影为：自腘窝中点至内踝和跟结节之间的中点连线","其压迫止血部位为：在内踝和跟结节之间向深部压迫","压迫该动脉其止血范围为：整个足部"],"a":4,"e":"胫后动脉发自腘动脉，分支有腓动脉、足底内侧动脉和足底外侧动脉，体表投影为腘窝中点至内踝与跟结节间中点连线，压迫止血范围限于小腿后部和足底。"},{"q":"关于阴部神经的叙述，错误的是","o":["自骶丛发出后，经梨状肌下孔出盆腔","穿坐骨小孔至会阴","在坐骨肛门窝行于阴部管内","在肛区不发出分支","在尿生殖区分为会阴神经和阴茎（蒂）神经"],"a":3,"e":"阴部神经自骶丛发出，穿梨状肌下孔出盆腔，绕坐骨棘经坐骨小孔入坐骨肛门窝，在阴部管内前行，沿途发出肛神经、会阴神经和阴茎（蒂）背神经。"},{"q":"管理硬脑膜的神经是","o":["耳大神经","面神经","舌咽神经耳支","副神经","迷走神经"],"a":4,"e":"迷走神经上神经节发出脑膜支，分布于颅后窝硬脑膜，传导一般躯体感觉。幕上硬脑膜由三叉神经分支管理，舌咽神经耳支分布于耳后皮肤。"},{"q":"关于颞浅动脉的叙述，错误的是","o":["该动脉发自颈外动脉","该动脉主要供应腮腺和额、颞、顶部软组织","其体表投影为该动脉的根部位于外耳门的前方，向上分为两大分支","其压迫止血部位为在外耳门前方可摸到动脉搏动，然后将其压向颞骨","压迫该动脉，其止血范围为项背部"],"a":4,"e":"颞浅动脉为颈外动脉终支之一，根部位于外耳门前方，分布于腮腺及额、颞、顶部软组织，压迫后止血范围为头前外侧部，不包括项背部。"},{"q":"含有交感神经节后纤维的神经","o":["内脏大神经","内脏小神经","腰内脏神经","心上、中、下神经","盆内脏神经"],"a":3,"e":"心上、中、下神经自颈交感干神经节发出，属节后纤维。内脏大、小神经和腰内脏神经由交感节前纤维组成，盆内脏神经为骶部副交感节前纤维。"},{"q":"关于脑干的内部结构，说法正确的是","o":["灰质在外，白质在内","中央的腔隙为第四脑室","锥体由上行纤维构成","薄束核、楔束核为脑神经核团","锥体交叉在内侧丘系交叉平面之下"],"a":4,"e":"锥体束在延髓下部交叉形成锥体交叉，位置低于内侧丘系交叉平面；内侧丘系交叉位于橄榄中部平面，由薄束核、楔束核发出的内弓状纤维越中线形成。"},{"q":"下列属于连合纤维的是","o":["前连合","内囊","钩束","内侧丘系","乳头丘脑束"],"a":0,"e":"连合纤维是连接两侧大脑半球相应皮质区的纤维，包括胼胝体、前连合和穹窿连合。内囊为投射纤维，钩束属联络纤维，内侧丘系为上行传导束。"},{"q":"经圆孔出颅的神经是","o":["展神经","上颌神经","下颌神经","动眼神经","眼神经"],"a":1,"e":"三叉神经第2支上颌神经经圆孔出颅入翼腭窝；眼神经经眶上裂、下颌神经经卵圆孔出颅，展神经和动眼神经亦经眶上裂。"},{"q":"不属于臂丛锁骨下分支的是","o":["胸内侧神经","胸背神经","肌皮神经","胸长神经","胸外侧神经"],"a":3,"e":"胸长神经起自臂丛神经根，在臂丛主要结构后方斜向外下进入腋窝，属锁骨上分支。胸内、外侧神经及胸背神经、肌皮神经均为锁骨下分支。"},{"q":"脊髓小脑束","o":["脊髓小脑前束位于脊髓前索","脊髓小脑后束位于脊髓后索","脊髓小脑前束经小脑下脚进入小脑","脊髓小脑后束经小脑上脚进入小脑","传导下肢和躯干下部非意识性本体感觉和触、压觉信息至小脑"],"a":4,"e":"脊髓小脑前、后束起自脊髓，传导下肢和躯干下部的非意识性本体感觉及触、压觉至小脑，前束经小脑上脚、后束经小脑下脚入小脑。"},{"q":"副交感神经的低级中枢位于","o":["间脑和骶2～4脊髓节段","脑干和胸1～腰2脊髓节段","脑干和骶2～4脊髓节段","胸1～腰3脊髓节段","脑干"],"a":2,"e":"副交感神经低级中枢位于脑干的一般内脏运动核和脊髓S2～S4节段的骶副交感核；交感神经低级中枢位于脊髓T1～L3节段的中间带外侧核。"},{"q":"脑干内的一般躯体运动核支配","o":["舌肌、眼球外肌","咽喉肌","表情肌","咀嚼肌","平滑肌、心肌"],"a":0,"e":"脑干一般躯体运动核包括动眼、滑车、展和舌下神经核，发出纤维支配由肌节衍化的眼球外肌和舌肌。咽喉肌、表情肌和咀嚼肌由特殊内脏运动核支配。"},{"q":"属于一般躯体运动核的神经核是","o":["三叉神经运动核","滑车神经核","面神经核","副神经核","疑核"],"a":1,"e":"一般躯体运动核共4对，为动眼神经核、滑车神经核、展神经核和舌下神经核，紧靠中线两侧排列。三叉神经运动核、面神经核、疑核、副神经核属特殊内脏运动核。"},{"q":"顶盖前区参与","o":["内脏反射","瞳孔对光反射","角膜反射","浅反射","听觉反射"],"a":1,"e":"顶盖前区接受经上丘臂来的视束纤维，发出纤维至双侧动眼神经副核，是瞳孔对光反射通路的中继站。上丘发出顶盖脊髓束完成视觉反射。"},{"q":"关于胸膜腔正确的叙述是","o":["由脏、壁胸膜共同围成的窄隙","由壁胸膜相互返折而成","可通过呼吸与外界相通","左、右胸膜腔经气管相通","其内有左、右肺和少量液体"],"a":0,"e":"胸膜腔是脏、壁胸膜在肺根处相互移行围成的封闭潜在腔隙，左右各一，互不相通，呈负压，内含少量浆液，不含肺。"},{"q":"收缩时，作张口运动的肌是","o":["双侧咬肌","双侧颞肌","口轮匝肌","双侧翼内肌","双侧翼外肌"],"a":4,"e":"翼外肌起自蝶骨大翼下面和翼突外侧面，止于下颌颈，两侧同时收缩使下颌骨前伸并张口；咬肌、颞肌和翼内肌收缩均上提下颌骨。"},{"q":"关于肺，正确的描述是","o":["肺位于胸膜腔内","右肺上方有主动脉压迹","左肺上方有奇静脉沟","肺尖不超出胸廓上口","肺底位于膈上方，又称膈面"],"a":4,"e":"肺底位于膈的上方，因与膈相邻又称膈面，向上凹陷。肺位于胸膜腔之外的胸腔内，右肺有奇静脉沟，左肺有主动脉压迹，肺尖高出胸廓上口。"},{"q":"不穿行于海绵窦的结构","o":["动眼神经","滑车神经","眼神经","上颌神经","下颌神经"],"a":4,"e":"海绵窦外侧壁内自上而下有动眼神经、滑车神经、眼神经和上颌神经通过，窦内侧壁有颈内动脉和展神经。下颌神经经卵圆孔出颅，不穿海绵窦。"},{"q":"关于桡神经正确的是","o":["从臂丛外侧束发出，下行穿桡神经沟至臂后区","从臂丛后束发出，穿四边孔到达臂后区","在肱三头肌深面穿桡神经沟下行至肘的前外侧","不支配肱桡肌","在臂后区不发出分支支配臂部伸肌群"],"a":2,"e":"桡神经发自臂丛后束，与肱深动脉伴行，经肱三头肌长头与内侧头之间入桡神经沟，绕肱骨后面下行，在肱骨外上髁上方穿外侧肌间隔至肘前外侧，支配臂后群伸肌。"},{"q":"窦房结位于","o":["房间隔的心内膜深面","上腔静脉口的心内膜深面","上腔静脉与右心房交界处","右肺静脉入口处","下腔静脉入口处"],"a":2,"e":"窦房结位于上腔静脉与右心房交界处界沟上1/3的心外膜深面，是心的正常起搏点。房室结位于房间隔下部右侧心内膜深面，为次级起搏点。"},{"q":"下列哪条动脉是肝固有动脉的分支","o":["胃网膜右动脉","胃左动脉","胃网膜左动脉","胃十二指肠动脉","胃右动脉"],"a":4,"e":"肝总动脉分为肝固有动脉和胃十二指肠动脉，肝固有动脉发出胃右动脉沿胃小弯左行，本干入肝门前分为肝左、右支。胃网膜右动脉发自胃十二指肠动脉。"},{"q":"视网膜视部的3层神经细胞由内向外依次为","o":["感光细胞、双极细胞、节细胞","感光细胞、节细胞、双极细胞","双极细胞、感光细胞、节细胞","节细胞、感光细胞、双极细胞","节细胞、双极细胞、感光细胞"],"a":4,"e":"视网膜视部神经层由外向内依次为感光细胞、双极细胞和节细胞：感光细胞为视觉感受器，双极细胞为第1级神经元，节细胞为第2级神经元。"},{"q":"舌的味觉纤维走行于","o":["面神经和舌咽神经","面神经和舌下神经","舌下神经和迷走神经","舌咽神经和舌下神经","舌咽神经和舌神经"],"a":0,"e":"舌前2/3味蕾由面神经的鼓索传导，舌后1/3味蕾由舌咽神经传导，故味觉纤维行于面神经和舌咽神经。舌下神经为运动神经，管理舌肌运动。"},{"q":"引流支气管淋巴的淋巴结是","o":["纵隔前淋巴结","膈上淋巴结","纵隔后淋巴结","肺淋巴结","气管旁淋巴结"],"a":3,"e":"肺淋巴结位于肺叶支气管和肺段支气管分支夹角处，收纳肺内淋巴，输出管注入支气管肺门淋巴结。肺的淋巴经肺淋巴结、肺门淋巴结、气管支气管淋巴结依次引流。"},{"q":"输出淋巴管参与组成肠干的淋巴结是","o":["髂外淋巴结","腰淋巴结","肠系膜上淋巴结","髂内淋巴结","髂总淋巴结"],"a":2,"e":"肠系膜上淋巴结位于肠系膜上动脉根部周围，收纳肠系膜淋巴结及回结肠、右结肠、中结肠淋巴结的输出管，与腹腔淋巴结、肠系膜下淋巴结的输出管共同汇合成肠干。"},{"q":"关于主动脉弓正确的说法是","o":["位于胸骨角平面之下","自左前方弯向右后方","分支有头臂干、右颈总动脉和右锁骨下动脉","弓的下缘借动脉韧带连于肺动脉","前方有气管，后方有食管"],"a":3,"e":"主动脉弓下缘借动脉韧带连于肺动脉干分叉处稍左侧，该韧带为动脉导管闭锁的遗迹。主动脉弓位于胸骨角平面之上，凸侧发出头臂干、左颈总动脉和左锁骨下动脉。"},{"q":"尿道球腺开口于","o":["膀胱","尿道前列腺部","尿道球部","尿道膜部","舟状窝"],"a":2,"e":"尿道球腺位于会阴深横肌内，其输出管开口于尿道球部，分泌物参与精液组成。尿道球部为尿道海绵体内最宽处，临床上称前尿道。"},{"q":"有面神经通过的孔是","o":["颈静脉孔","破裂孔","卵圆孔","茎乳孔","枕骨大孔"],"a":3,"e":"面神经经内耳门、内耳道入面神经管，最后由茎乳孔出颅。颈静脉孔有舌咽、迷走、副神经通过，卵圆孔有下颌神经通过，圆孔有上颌神经通过。"},{"q":"杏仁体错误的是","o":["它与情绪的产生有关","按功能上分，杏仁体不属于基底核","不属于边缘系统","它是内脏活动皮质下中枢","杏仁体位于海马旁回钩的深面"],"a":2,"e":"杏仁体位于侧脑室下角前端上方、海马旁回钩深面，属边缘系统的皮质下中枢，与内脏活动调节和情绪产生有关。"},{"q":"桡腕关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":2,"e":"桡腕关节由手舟骨、月骨、三角骨的近侧关节面与桡骨腕关节面及尺骨头下方关节盘构成，关节头呈椭圆形，属典型椭圆关节，可屈伸、收展和环转。"},{"q":"可使足跖屈和外翻的肌是","o":["腓肠肌","胫骨前肌","胫骨后肌","腓骨长肌","比目鱼肌"],"a":3,"e":"腓骨长肌起自腓骨外侧面，肌腱经外踝后方转向前，止于内侧楔骨和第一跖骨底，收缩时使足跖屈和外翻。胫骨前肌使足背屈和内翻。"},{"q":"关于桡动脉的描述错误是","o":["为肱动脉的分支之一","沿肱桡肌内侧深面下行","至桡骨下端，弯行向手背","主干末端参与构成掌浅弓","在腕部常取此动脉摸脉"],"a":3,"e":"桡动脉末端与尺动脉掌深支吻合形成掌深弓，其掌浅支才与尺动脉末端吻合构成掌浅弓。桡动脉下段位置表浅，为临床触摸脉搏的常用部位。"},{"q":"加强肩关节囊上壁的韧带是","o":["喙肱韧带","盂肱上韧带","盂肱中韧带","盂肱下韧带","喙肩韧带"],"a":0,"e":"肩关节囊上壁有喙肱韧带加强，自喙突根部至肱骨大结节前面，与冈上肌腱交织融合。喙肩韧带架于关节上方，防止肱骨头向上脱位，不属囊壁韧带。"},{"q":"面神经不含下列哪种纤维成分","o":["特殊内脏运动纤维","一般内脏运动纤维","特殊内脏感觉纤维","一般躯体运动纤维","一般躯体感觉纤维"],"a":3,"e":"面神经含特殊内脏运动、一般内脏运动、特殊内脏感觉和一般躯体感觉四种纤维，不含一般躯体运动纤维。一般躯体运动纤维仅见于动眼、滑车、展和舌下神经。"},{"q":"关于巩膜静脉窦，叙述正确的是","o":["位于角膜内","位于虹膜内","角膜缘处的巩膜实质内","巩膜静脉窦垂直穿出眼球壁","与房水的循环无关"],"a":2,"e":"巩膜静脉窦位于角膜缘处的巩膜实质内，为环形管道，是房水流出的通道，与房水循环密切相关。其位置表浅，不与角膜、虹膜直接相连。"},{"q":"关节囊滑膜的特征不包括","o":["滑膜构成关节囊的内层","富有血管网，覆盖于关节软骨表面","主要由疏松结缔组织构成","可产生滑液，能够提供营养","内面有许多滑膜绒毛"],"a":1,"e":"滑膜衬于纤维膜内面，边缘附着于关节软骨周缘，包被关节内除关节软骨、关节唇和关节盘以外的所有结构，故不覆盖关节软骨表面。滑膜富含血管，能产生滑液。"},{"q":"组成肌腱袖的肌不包括","o":["肩胛下肌","冈上肌","冈下肌","三角肌","小圆肌"],"a":3,"e":"肌腱袖由冈上肌、冈下肌、小圆肌和肩胛下肌的肌腱构成，止于肱骨大、小结节，增强肩关节稳定性。三角肌为肩部独立肌，不参与肌腱袖。"},{"q":"肝胰壶腹开口于","o":["十二指肠上部","十二指肠大乳头","十二指肠升部","十二指肠水平部","十二指肠球部"],"a":1,"e":"肝胰壶腹由胆总管与胰管汇合形成，开口于十二指肠降部后内侧壁的十二指肠大乳头。十二指肠小乳头位于大乳头上方，为副胰管开口。"},{"q":"头面部浅感觉通路的第三级神经元胞体在","o":["腹前核","底丘脑核","背侧丘脑腹后内侧核","背侧丘脑腹后外侧核","背侧丘脑腹外侧核"],"a":2,"e":"头面部浅感觉传导通路的第3级神经元胞体位于背侧丘脑腹后内侧核，发出纤维经内囊后肢投射至中央后回下部。腹后外侧核接受内侧丘系和脊髓丘系。"},{"q":"关于颈内静脉的正确描述是","o":["延续于海绵窦","位于颈动脉鞘内","与面静脉汇合成锁骨下静脉","属支有颈外静脉和面静脉","缺乏静脉瓣"],"a":1,"e":"颈内静脉在颈静脉孔处续于乙状窦，在颈动脉鞘内沿颈内动脉和颈总动脉外侧下行，至胸锁关节后方与锁骨下静脉合成头臂静脉，属支有面静脉、舌静脉等。"},{"q":"对下列上肢浅静脉的描述正确的是","o":["头静脉收集前臂尺侧浅层的静脉血","贵要静脉收集前臂桡侧浅层的静脉血","肘正中静脉连接头静脉与贵要静脉","前臂正中静脉收集手背的静脉血","上肢浅静脉的静脉血直接汇入锁骨下静脉"],"a":2,"e":"肘正中静脉在肘窝处连接头静脉与贵要静脉，变异较多。头静脉起自手背静脉网桡侧，贵要静脉收集手和前臂尺侧浅层静脉血。"},{"q":"可伸肘关节和内收肩关节的肌是","o":["肱二头肌","肱三头肌","肱桡肌","旋前圆肌","旋后肌"],"a":1,"e":"肱三头肌长头起自盂下结节，跨越肩关节，收缩时使肩关节后伸和内收，三个头共同作用伸肘关节。肱二头肌和肱桡肌主要屈肘。"},{"q":"腭扁桃体位于","o":["扁桃体上窝内","扁桃体小窝内","咽隐窝内","腭咽弓后方的窝内","腭舌弓与腭咽弓之间的窝内"],"a":4,"e":"腭舌弓与腭咽弓之间的三角形凹陷为扁桃体窝，容纳腭扁桃体。扁桃体上窝位于扁桃体上方，咽隐窝位于咽鼓管圆枕后方，均非扁桃体所在。"},{"q":"关于交感神经交通支的叙述，错误的是","o":["分为灰、白交通支","白交通支含有节前纤维","灰交通支含有节后纤维","胸、腰神经均有白交通支","每对脊神经均有灰交通支"],"a":3,"e":"白交通支由有髓的节前纤维构成，节前神经元胞体仅存在于T1～L3节段，故白交通支只见于胸1至腰3脊神经，共15对；灰交通支连于全部31对脊神经。"},{"q":"通过棘孔的结构是","o":["上颌神经","下颌神经","脑膜中动脉","上颌动脉","副神经"],"a":2,"e":"脑膜中动脉为上颌动脉的分支，在下颌颈深面发出后穿棘孔入颅，分前、后支分布于硬脑膜和颅骨。上颌神经穿圆孔，下颌神经穿卵圆孔。"},{"q":"与桡骨头关节凹组成肱桡关节的结构是","o":["尺骨滑车切迹","肱骨小头","尺骨桡切迹","桡骨尺切迹","桡骨环状关节面"],"a":1,"e":"肱桡关节由肱骨小头与桡骨头关节凹构成，属肘关节的一部分。肱尺关节由肱骨滑车与尺骨滑车切迹构成，桡尺近侧关节由桡骨环状关节面与尺骨桡切迹构成。"},{"q":"缩短循环途径，调节局部血流量的是","o":["血管吻合","动脉间吻合","静脉间吻合","动、静脉吻合","侧支吻合"],"a":3,"e":"动、静脉吻合是小动脉与小静脉直接相连的血管支，见于指尖、鼻、唇及勃起组织等处，可缩短循环途径、调节局部血流量和体温。"},{"q":"支配瞳孔括约肌的神经是","o":["动眼神经的交感神经纤维","动眼神经的副交感神经纤维","眼神经的交感神经纤维","三叉神经的副交感神经纤维","面神经的交感神经纤维"],"a":1,"e":"瞳孔括约肌由动眼神经副核发出的副交感节前纤维在睫状神经节换元后的节后纤维支配，收缩时瞳孔缩小。交感纤维经颈上神经节支配瞳孔开大肌。"},{"q":"不属于副交感神经节的是","o":["下颌下神经节","耳神经节","翼腭神经节","膝状神经节","睫状神经节"],"a":3,"e":"颅部副交感神经节有睫状神经节、翼腭神经节、耳神经节和下颌下神经节四对。膝状神经节是面神经的感觉神经节，内含假单极神经元。"},{"q":"与鼓室不相连通的结构是","o":["外耳道","咽鼓管","乳突窦","乳突小房","耳蜗"],"a":4,"e":"鼓室借咽鼓管通鼻咽部，向后经乳突窦通乳突小房，向外借鼓膜与外耳道相隔。耳蜗位于骨迷路内，借蜗孔与前庭相通，不与鼓室相通。"},{"q":"髋关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":4,"e":"髋关节由髋臼与股骨头构成，属多轴球窝关节，可作屈伸、收展、旋转和环转运动。因髋臼深、韧带强韧，其运动范围较肩关节小。"},{"q":"鼻泪管开口于","o":["下鼻道","上鼻道","中鼻道","泪点","泪囊"],"a":0,"e":"鼻泪管向下开口于下鼻道前上方，其开口处黏膜富含静脉丛，感冒充血时可致鼻泪管下口闭塞而流泪。上、中鼻道有鼻旁窦开口。"},{"q":"组成腕关节的结构不包括","o":["手舟骨","月骨","三角骨","豌豆骨","桡骨下端的关节面"],"a":3,"e":"桡腕关节由手舟骨、月骨和三角骨的近侧关节面与桡骨下端关节面及尺骨头下方关节盘构成，豌豆骨不参与。豌豆骨位于腕骨近侧列尺侧。"},{"q":"第四脑室","o":["位于延髓、脑桥和中脑之间","底由上髓帆、下髓帆和第四脑室脉络组织组成","底为脑桥和中脑背侧面构成的菱形窝","经室间孔与侧脑室直接相通","脑脊液经单一的第四脑室正中孔和成对的第四脑室外侧孔通入蛛网膜下隙"],"a":4,"e":"第四脑室位于延髓、脑桥与小脑之间，底为菱形窝，顶由上髓帆、下髓帆和第四脑室脉络组织构成，借正中孔和成对外侧孔通蛛网膜下隙。"},{"q":"临床行胃大部分切除术时需要结扎的胃左动脉来源于","o":["腹腔干","肝总动脉","脾动脉","胃网膜右动脉","肠系膜上动脉"],"a":0,"e":"胃左动脉为腹腔干三大分支之一，沿胃小弯行于小网膜两层之间，与胃右动脉吻合。肝总动脉和脾动脉亦直接发自腹腔干。"},{"q":"胸廓的组成不包括","o":["胸骨","12对肋","12块胸椎","肋椎关节","胸锁关节"],"a":4,"e":"胸廓由12块胸椎、12对肋、1块胸骨及它们之间的连结共同构成，肋椎关节属其连结。胸锁关节是上肢骨与躯干骨的连结，不参与胸廓构成。"},{"q":"关节盘的特征不包括","o":["膝关节的关节盘称半月板","将关节腔分为两部","是透明软骨板","有利于运动","周缘附着于关节囊"],"a":2,"e":"关节盘由纤维软骨构成，周缘附着于关节囊，将关节腔分为上、下两部，可缓和冲击、增加关节运动形式。膝关节的关节盘呈半月形，称半月板。"},{"q":"含有假单极神经元的部位是","o":["副交感神经节内","交感神经节内","基底核内","脊神经节内","前庭神经节内"],"a":3,"e":"脊神经节内为假单极神经元，其周围突构成感觉神经，中枢突经后根入脊髓。交感、副交感神经节内为多极神经元，前庭神经节内为双极神经元。"},{"q":"支配腮腺的副交感节前纤维的胞体位于","o":["动眼神经副核","迷走神经背核","孤束核","上泌涎核","下泌涎核"],"a":4,"e":"下泌涎核发出副交感节前纤维经舌咽神经的岩小神经至耳神经节换元，节后纤维经耳颞神经至腮腺。上泌涎核支配泪腺、下颌下腺和舌下腺。"},{"q":"心前壁主要由哪部分心腔构成","o":["左心室","右心室","左心房","右心房","腔静脉窦"],"a":1,"e":"右心室前壁构成胸肋面的大部分，介于右冠状沟、前室间沟、心右缘与肺动脉口平面之间，是心前壁的主要构成部分。左心室构成心尖和膈面大部分。"},{"q":"关于子宫的正确描述是","o":["位于小骨盆腔内，属腹膜内位器官","上端宽而圆凸的部分为子宫体","颈下端在坐骨棘平面稍下方","子宫颈与阴道上部相接处狭窄称子宫峡","正常位置为前倾前屈位"],"a":4,"e":"成年人子宫呈轻度前倾前屈位，前倾为子宫长轴与阴道长轴之间向前开放的钝角，前屈为子宫体与子宫颈间约170°的角。子宫颈下端位于坐骨棘平面稍上方。"},{"q":"经白质前连合交叉至对侧形成的纤维束是","o":["薄、楔束","脊髓丘脑束","红核脊髓束","皮质脊髓前束","皮质脊髓侧束"],"a":1,"e":"脊髓丘脑束起自脊髓灰质Ⅰ和Ⅳ～Ⅷ层，纤维经白质前连合交叉至对侧外侧索和前索上行，止于背侧丘脑。薄束、楔束不交叉。"},{"q":"神经系统","o":["基本组织是神经胶质","结构和功能的基本单位是神经元","神经胶质主要是感受刺激","胶质细胞也有传导神经冲动的功能","周围神经只包括脑神经和脊神经"],"a":1,"e":"神经元是神经系统结构和功能的基本单位，具有感受刺激和传导神经冲动的功能；神经胶质是支持组织，起支持、营养、保护和形成髓鞘的作用。"},{"q":"脊髓第8胸节平对","o":["第2胸椎","第3胸椎","第4胸椎","第5胸椎","第6胸椎"],"a":4,"e":"脊髓中胸节段T5～T8约平对同序数椎骨上方第2个椎体，故第8胸节平对第6胸椎。下颈髓和上胸髓平对同序数椎骨上方第1位。"},{"q":"骶骨的形态结构特征包括","o":["有5对骶前孔","由4块骶椎融合而成","与第4腰椎相关节","骶管内有脊髓通过","于骶角处可寻骶管裂孔进行神经阻滞麻醉"],"a":4,"e":"骶管裂孔位于骶管下端，两侧有向下突出的骶角，骶管麻醉常以骶角为标志经此裂孔穿刺。骶骨由5块骶椎融合，有4对骶前孔和4对骶后孔。"},{"q":"甲状颈干的分支有","o":["甲状腺下动脉","颈升动脉","肩胛下动脉","甲状腺上动脉","肩胛背动脉"],"a":0,"e":"甲状颈干在椎动脉外侧起自锁骨下动脉，迅即分为甲状腺下动脉、肩胛上动脉等，分布于甲状腺、咽、食管、喉及肩部肌。甲状腺上动脉发自颈外动脉。"},{"q":"分布于肺的神经","o":["内脏大神经","内脏小神经","内脏最小神经","肋下神经","迷走神经"],"a":4,"e":"肺由迷走神经和交感神经共同支配，迷走神经的副交感纤维使支气管平滑肌收缩、腺体分泌增加。内脏大、小神经支配腹腔脏器。"},{"q":"关于睾丸的描述不正确的是","o":["后缘有附睾体尾附着","精曲小管上皮合成和分泌雌性激素","睾丸上端被附睾头遮盖","后缘白膜增厚，凸入睾丸内形成睾丸纵隔","从睾丸网发出12～15条睾丸输出小管进入附睾"],"a":1,"e":"生精小管上皮产生精子，其间的间质细胞分泌雄性激素；雌性激素由卵巢卵泡和黄体分泌。睾丸后缘白膜增厚凸入形成睾丸纵隔。"},{"q":"不参与组成大脑动脉环的动脉","o":["大脑前动脉","大脑中动脉","大脑后动脉","前交通动脉","后交通动脉"],"a":1,"e":"大脑动脉环由前交通动脉、两侧大脑前动脉、两侧颈内动脉、两侧后交通动脉和两侧大脑后动脉构成，大脑中动脉为颈内动脉分支，不参与组成。"},{"q":"下腔静脉的直接接纳的静脉是","o":["肝门静脉","肝静脉","脾静脉","胃左静脉","胃右静脉"],"a":1,"e":"肝左、中、右静脉在腔静脉沟上端即第二肝门处出肝，直接注入下腔静脉。肝门静脉、脾静脉和胃左、右静脉属肝门静脉系，不直接注入下腔静脉。"},{"q":"通过海绵窦与颈内动脉伴行的神经","o":["动眼神经","滑车神经","眼神经","上颌神经","展神经"],"a":4,"e":"海绵窦内侧壁有颈内动脉和展神经通过，二者伴行。动眼神经、滑车神经、眼神经和上颌神经行于海绵窦外侧壁。"},{"q":"动眼神经含有的副交感纤维来源于","o":["滑车神经核","展神经核","动眼神经核","E-W核","三叉神经运动核"],"a":4,"e":"官方答案为【三叉神经运动核】，但依据教材，正确答案为【E-W核】。动眼神经的副交感节前纤维起自动眼神经副核（E-W核），在睫状神经节换元后节后纤维支配瞳孔括约肌和睫状肌。"},{"q":"关于淋巴结的描述正确的是","o":["青年人有100个","当中凹陷为淋巴结门","可称为淋巴组织","基本上为深淋巴结","和免疫反应无关"],"a":1,"e":"淋巴结一侧隆凸，另一侧凹陷，凹陷中央处为淋巴结门，有输出淋巴管、神经和血管出入，凸侧连输入淋巴管。淋巴结有滤过淋巴和免疫应答功能。"},{"q":"关于指压法压迫止血描述正确的是","o":["当前臂和手部出血时，肱动脉的常用指压法止血部位在肱动脉的起始段","手指出血时，采用指压法进行止血的部位应在手指的两侧","头皮出血时，常用的指压法压迫止血点在口角处","面部出血时，常用的指压法压迫止血点在咬肌后缘与下颌骨下缘交界处","头皮出血时，常用的指压法压迫止血点在内眦"],"a":1,"e":"指掌侧固有动脉行于手指两侧，故手指出血时在指根两侧向指骨压迫止血。肱动脉压迫点在臂中部肱二头肌内侧沟，面动脉在下颌骨下缘咬肌前缘处。"},{"q":"上纵隔最前方的结构是","o":["左、右头臂静脉","上腔静脉","气管","主动脉弓","胸腺"],"a":4,"e":"上纵隔内自前向后依次为胸腺、左头臂静脉、右头臂静脉、上腔静脉、膈神经、迷走神经、主动脉弓及其三大分支以及气管、食管和胸导管，胸腺居最前。"},{"q":"十二指肠大乳头","o":["位于十二指肠水平部","距中切牙65cm","位于十二指肠环形皱襞上","上面有肝胰壶腹的开口","其下方有十二指肠小乳头"],"a":3,"e":"十二指肠大乳头位于十二指肠降部后内侧壁，是肝胰壶腹的开口处，距中切牙约75cm。十二指肠小乳头位于其上方1～2cm，为副胰管开口。"},{"q":"关于骨迷路描述，错误的是","o":["骨迷路是由骨密质构成的不规则的腔与管","由耳蜗、前庭和骨半规管构成，沿颞骨岩部的长轴排列","前庭后上部有5个小孔与3个半规管相通","前庭外侧壁有前庭窗和蜗窗","前庭窗由第一鼓膜封闭，蜗窗由第二鼓膜封闭"],"a":4,"e":"前庭窗由镫骨底封闭，蜗窗由第二鼓膜封闭，并非第一、第二鼓膜分别封闭前庭窗和蜗窗。骨迷路由骨密质构成，分耳蜗、前庭和骨半规管。"},{"q":"鼻腔嗅区黏膜存在于","o":["鼻翼","上鼻甲","中鼻甲","下鼻甲","鼻前庭"],"a":1,"e":"嗅区黏膜位于上鼻甲、与其相对的鼻中隔及二者上方鼻腔顶部，富含嗅细胞。中、下鼻甲黏膜属呼吸区。"},{"q":"与肩胛骨的关节盂组成肩关节的结构是","o":["肱骨头","肱骨大结节","肱骨小结节","肱骨外科颈","肱骨解剖颈"],"a":0,"e":"肩关节由肱骨头与肩胛骨关节盂构成，肱骨头呈半球形，关节盂仅能容纳关节头的1/4～1/3。肱骨大、小结节为肌腱附着处，不参与关节构成。"},{"q":"属于非特异性投射核团的是","o":["腹前核","腹外侧核","腹后内侧核","腹后外侧核","中线核"],"a":4,"e":"非特异性投射核团属原丘脑，包括中线核、板内核和网状核，接受嗅脑和脑干网状结构的传入纤维。腹前核、腹外侧核和腹后核属特异性投射核团。"},{"q":"迷走神经不支配","o":["环甲肌","乙状结肠","咽中缩肌","胃","十二指肠"],"a":1,"e":"迷走神经副交感纤维分布于颈、胸脏器及腹腔大部分脏器，结肠左曲以下的消化管由骶副交感核经盆内脏神经支配，故乙状结肠不受迷走神经支配。"},{"q":"损伤一侧大脑皮质躯体运动区可导致","o":["对侧肢体瘫痪和肌张力减退","对侧肢体瘫痪并伴有感觉障碍","对侧肢体震颤并伴有肌张力增强","同侧共济运动障碍和感觉障碍","对侧肢体瘫痪和肌张力增强"],"a":4,"e":"一侧中央前回损伤致对侧肢体痉挛性瘫痪，表现为随意运动障碍、肌张力增高、腱反射亢进，早期无明显肌萎缩。感觉障碍提示中央后回或内囊受累。"},{"q":"男性输精管结扎常选择在哪个部位进行","o":["睾丸部","精索部","盆部","腹股沟管部","壶腹部"],"a":1,"e":"输精管精索部位于睾丸上端与腹股沟管皮下环之间，位置表浅易于触及，为结扎输精管的理想部位。盆部为输精管最长的一段。"},{"q":"一侧皮质核束","o":["只支配对侧动眼神经核","只支配对侧动眼神经副核","支配双侧面神经核","只支配对侧舌下神经核","只支配对侧疑核"],"a":3,"e":"皮质核束大部分纤维止于双侧脑神经运动核，仅面神经核下部和舌下神经核只接受对侧皮质核束支配，故一侧皮质核束只支配对侧舌下神经核。"},{"q":"有肋凹的椎骨是","o":["第1颈椎","第2颈椎","第7颈椎","胸椎","腰椎"],"a":3,"e":"胸椎椎体两侧后份的上、下缘有上、下肋凹，与肋头相关节；第1、10～12胸椎肋凹形态特殊。颈椎、腰椎均无肋凹。"},{"q":"在骨连结中，骨性连结包括","o":["骺软骨","前臂骨间膜","耻骨连合","椎间盘","髂骨、坐骨和耻骨合成髋骨"],"a":4,"e":"骨性连结是两骨借骨组织相连，如髂骨、坐骨和耻骨融合成髋骨。骺软骨属透明软骨结合，前臂骨间膜为纤维连结，耻骨联合和椎间盘为软骨连结。"},{"q":"舌咽神经分布不包括","o":["腮腺","颈动脉窦","舌前2/3味觉","舌后1/3味觉","鼓室"],"a":2,"e":"舌前2/3味觉由面神经的鼓索传导，舌后1/3味觉由舌咽神经传导。舌咽神经还分布于腮腺、颈动脉窦、鼓室及咽部黏膜。"},{"q":"视觉传导通路中的第2级神经元是","o":["视锥细胞","视杆细胞","双极细胞","节细胞","外侧膝状体"],"a":3,"e":"视觉传导通路由3级神经元组成，第1级为双极细胞，第2级为节细胞，第3级为外侧膝状体细胞。视锥、视杆细胞为感受器，不属传导通路神经元。"},{"q":"腹前外侧群的肌肉不包括","o":["腹外斜肌","腹内斜肌","腹横肌","腰大肌","腹直肌"],"a":3,"e":"腹前外侧群肌包括腹外斜肌、腹内斜肌、腹横肌和腹直肌，腰大肌属腹后群肌，归属下肢肌的髂腰肌。"},{"q":"女性外阴部发生炎症后，最容易形成囊肿的部位是","o":["大阴唇","小阴唇","阴阜","阴蒂","前庭大腺"],"a":4,"e":"前庭大腺位于大阴唇后部、前庭球后端深面，导管开口于阴道前庭，炎症时导管阻塞易形成前庭大腺囊肿。"},{"q":"下述哪一项包含在淋巴系统的组成中","o":["组织液","毛细血管","淋巴器官","淋巴小结","脾髓"],"a":2,"e":"淋巴系统由淋巴管道、淋巴组织和淋巴器官组成，淋巴器官包括淋巴结、胸腺、脾和扁桃体。组织液、毛细血管不属其组成。"},{"q":"视神经","o":["外包三层膜，为相应脑膜的延续","经眶上裂入颅中窝","为双极神经元的中枢突组成","完全受损，伤侧全盲且瞳孔对光反射消失","连于端脑"],"a":0,"e":"视神经由节细胞轴突构成，外包硬脑膜、蛛网膜和软脑膜三层鞘，为相应脑膜的延续，经视神经管入颅，连于间脑。"},{"q":"分泌雄性激素的是","o":["睾丸间质细胞","睾丸网","精囊","白膜","前列腺"],"a":0,"e":"睾丸间质细胞位于生精小管之间的结缔组织内，分泌雄性激素。睾丸网、白膜、精囊和前列腺均不分泌雄性激素。"},{"q":"一男性患者，左侧内囊出血，导致右侧视野偏盲，其因是视辐射通过","o":["豆状核下部","豆状核后部","豆丘部","豆状核与尾状核之间","内囊前肢与后肢之间"],"a":1,"e":"视辐射经内囊豆状核后部向后行至枕叶视皮质，故该处出血致对侧同向性偏盲。豆丘部有皮质脊髓束、丘脑中央辐射，豆状核下部有听辐射。"},{"q":"小脑扁桃体","o":["属于古小脑","属于小脑的淋巴组织","位于小脑下面靠近枕骨大孔处","位于小脑上面靠近小脑幕切迹处","属于旧小脑"],"a":2,"e":"小脑扁桃体位于小脑半球下面靠近枕骨大孔处，紧邻延髓，颅内压增高时可被挤入枕骨大孔形成小脑扁桃体疝，压迫延髓生命中枢。"},{"q":"损伤后导致肢体瘫痪的纤维束","o":["红核脊髓束","脊髓丘脑束","顶盖脊髓束","皮质脊髓侧束","皮质脊髓前束"],"a":3,"e":"皮质脊髓侧束由锥体交叉后来自对侧的纤维构成，在下行中逐节终止于前角运动神经元，支配四肢肌，损伤后出现同侧肢体瘫痪。"},{"q":"心底朝向","o":["右侧","右前方","右后方","后方","右后上方"],"a":4,"e":"心底朝向右后上方，主要由左心房和小部分右心房构成；心尖朝向左前下方，由左心室构成。胸肋面大部分由右心室构成。"},{"q":"拇指腕掌关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":3,"e":"拇指腕掌关节由大多角骨与第1掌骨底构成，两关节面均呈鞍状，属鞍状关节，可作屈伸、收展、环转和对掌运动，为灵长类特有。"},{"q":"不是肠系膜上动脉分支的动脉是","o":["空肠动脉","回肠动脉","升结肠动脉","横结肠动脉","降结肠动脉"],"a":4,"e":"肠系膜上动脉发出空肠动脉、回肠动脉、回结肠动脉、右结肠动脉和中结肠动脉；降结肠由肠系膜下动脉发出的左结肠动脉供血。"},{"q":"既屈膝关节又屈髋关节的肌是","o":["股薄肌","缝匠肌","股四头肌","半膜肌","股二头肌"],"a":1,"e":"缝匠肌起自髂前上棘，止于胫骨上端内侧面，收缩时屈髋关节和膝关节，并使已屈的膝关节旋内。股四头肌只屈髋伸膝，股二头肌屈膝伸髋。"},{"q":"有关颈总动脉的描述错误的是","o":["头颈部出血可压迫此动脉","左侧者发自头臂干","分杈处的后壁上有颈动脉小球","分支为颈内、外动脉","两侧均经胸锁关节后方"],"a":1,"e":"左颈总动脉起自主动脉弓，右颈总动脉起自头臂干；两侧均经胸锁关节后方上行，至甲状软骨上缘分为颈内、颈外动脉，分杈处有颈动脉小球。"},{"q":"桡骨的形态结构不包括","o":["位于前臂的外侧，分为一体两端","上端有膨大的桡骨头","头下方变细称桡骨颈","颈的内下方有一突起称桡骨粗隆","桡骨茎突较尺骨茎突低1cm"],"a":4,"e":"桡骨上端为桡骨头，头下缩细为桡骨颈，颈内下方有桡骨粗隆，下端外侧为桡骨茎突；桡骨茎突低于尺骨茎突约1cm属两骨对比关系，不属桡骨本身形态结构。"},{"q":"关于尺动脉描述正确的是","o":["行于肱桡肌肌腱与桡侧腕屈肌肌腱之间","其下段为临床上诊脉的常用部位","在尺侧腕屈肌与指浅屈肌之间下行","是掌深弓的主要组成动脉","其终末支为掌深支"],"a":2,"e":"尺动脉在尺侧腕屈肌与指浅屈肌之间下行，经豌豆骨桡侧至手掌，末端与桡动脉掌浅支吻合形成掌浅弓。掌深弓由桡动脉末端与尺动脉掌深支构成。"},{"q":"关于皮质脊髓侧束正确的是","o":["在脊髓外侧索前部下行","是小部分在延髓椎体交叉的纤维","其下行纤维终止于中间神经元","起于中央后回大椎体细胞","一侧脊髓损伤出现同侧肢体随意运动障碍"],"a":4,"e":"皮质脊髓侧束位于脊髓外侧索后部，由对侧锥体交叉后的纤维构成，支配四肢肌；一侧损伤出现同侧损伤平面以下的痉挛性瘫痪。"},{"q":"关于房室结的叙述，错误的是","o":["心肌收缩的起搏点","多由右冠状动脉的分支供应","位于房室交界区的中央部","病变后可引起异位搏动","具有延搁传导的作用"],"a":0,"e":"窦房结是心的正常起搏点，房室结为次级起搏点，位于房室交界区中央部，具有传导延搁作用，病变时可引起异位搏动，多由右冠状动脉分支供血。"},{"q":"硬脑膜窦","o":["内含动脉血","窦壁内有丰富的平滑肌","损伤后平滑肌收缩能自行止血","与颅外静脉无交通","由硬脑膜在某些部位两层分开，内衬内皮细胞构成"],"a":4,"e":"硬脑膜窦由硬脑膜两层在某些部位分开、内面衬内皮细胞构成，窦内含静脉血，壁无平滑肌不能收缩，损伤出血时难以自行止血，且与颅外静脉有交通。"},{"q":"不含有毛细血管的是","o":["骨","软骨","肌肉","舌","胃"],"a":1,"e":"毛细血管吻合成网遍布全身，但角膜、晶状体、毛发、软骨、牙釉质和被覆上皮无血管分布，故软骨不含毛细血管，其营养靠基质渗透。"},{"q":"下列何结构受损伤，可致对侧偏身运动障碍","o":["红核脊髓束","皮质核束","皮质脊髓束","内囊后肢","内囊后肢和内囊膝"],"a":4,"e":"内囊后肢的皮质脊髓束和膝部的皮质核束受损均可致对侧偏瘫，故内囊后肢和膝损伤出现对侧偏身运动障碍，常伴偏身感觉障碍和偏盲。"},{"q":"分泌雌性激素的内分泌腺是","o":["甲状腺","甲状旁腺","卵巢","松果体","胸腺"],"a":2,"e":"卵巢为女性生殖腺，卵泡壁细胞和黄体分泌雌激素与孕激素。甲状腺、甲状旁腺、松果体和胸腺均不分泌雌激素。"},{"q":"薄束和楔束","o":["起自肌、腱、关节和皮肤的感受器","止于脑桥的薄束核和楔束核","传导非意识性本体感觉信息","薄束位于后索外侧部，楔束位于内侧部","损伤后精细触觉丧失"],"a":4,"e":"薄束、楔束传导同侧躯干四肢的本体感觉和皮肤精细触觉，脊髓后索病变时精细触觉和位置觉、振动觉丧失而痛温觉保留。两束止于延髓薄束核和楔束核。"},{"q":"骨质的描述，不正确的是","o":["骨质分骨密质和骨松质","骨密质均分布于骨表面","颅盖骨的松质骨称为板障","颅盖的内板厚而紧韧","骨质均有骨组织构成"],"a":3,"e":"颅盖骨外板厚而坚韧富弹性，内板薄而松脆，骨折多见于内板，故内板厚而紧韧的说法错误。骨密质配布于骨表面，扁骨松质称板障。"},{"q":"关于肾上腺的描述，哪项错误","o":["左、右各一","左侧的近似半月形","右侧的呈三角形","分泌盐皮质激素","调节血钙平衡"],"a":4,"e":"调节血钙平衡的是甲状旁腺分泌的甲状旁腺激素与甲状腺滤泡旁细胞分泌的降钙素。肾上腺皮质分泌盐、糖皮质激素和性激素，髓质分泌肾上腺素和去甲肾上腺素。"},{"q":"颈总动脉","o":["约平对甲状软骨上缘高度分出颈内动脉和颈外动脉","右侧的起自升主动脉","左侧的起自头臂干","走行于气管和喉的后方","颈动脉窦位于颈总动脉的起始处"],"a":0,"e":"颈总动脉在甲状软骨上缘高度分为颈内、颈外动脉；左颈总动脉起自主动脉弓，右颈总动脉起自头臂干，沿气管和喉的外侧上行。"},{"q":"某患者手术中损伤右侧外侧丘系，下面关于外侧丘系的叙述，正确的是","o":["起始于双侧蜗神经核和上橄榄核","全部由对侧的蜗神经核发出的轴突形成","没有外侧丘系核的纤维参与","大部分纤维不交叉","右侧外侧丘系损伤导致双耳的听觉障碍"],"a":0,"e":"外侧丘系主要由双侧蜗神经核发出的二级听觉纤维组成，并有双侧上橄榄核发出的三级纤维加入，一侧损伤不引起明显耳聋。"},{"q":"子宫骶韧带的作用是","o":["固定子宫于骶骨前方","防止子宫脱垂","牵引子宫颈向后上","牵引子宫底向前下","防止子宫倾向一侧"],"a":2,"e":"子宫骶韧带从子宫颈后面上外侧向后绕过直肠两侧，止于第2、3骶椎前面的筋膜，向后上牵引子宫颈，协同子宫圆韧带维持子宫前倾前屈位。"},{"q":"临床上逆行胰胆管造影（ERCP）是将内镜插至十二指肠，找到十二指肠大乳头以后，由内镜活检孔插入造影管至十二指肠大乳头上的肝胰壶腹开口，注入造影剂，作胆胰管X线造影。造影管插入的长度至少是","o":["25cm","35cm","45cm","55cm","75cm"],"a":4,"e":"十二指肠大乳头距中切牙约75cm，为肝胰壶腹的开口处，故经口插入的造影管长度至少需75cm才能到达该处。"},{"q":"有关局部淋巴结的叙述，正确的为","o":["是引流器官淋巴液的第一级淋巴结","切除肿瘤时不用切除局部淋巴结","不能清除肿瘤细胞和寄生虫","是引流器官淋巴的第二级淋巴结","不在器官附近"],"a":0,"e":"局部淋巴结是引流某一器官或部位淋巴的第一级淋巴结，又称哨位淋巴结，其肿大常反映引流区存在病变。"},{"q":"对喉返神经的描述，正确的是","o":["其终支称为喉下神经","右喉返神经在右锁骨下动脉后方发出","分支至甲状舌骨肌","支配全部喉肌","分布于喉中间腔和声门下腔黏膜"],"a":0,"e":"喉返神经在甲状腺侧叶深面入喉，终支称喉下神经，分布于声门裂以下喉黏膜及除环甲肌以外的全部喉肌，不支配甲状舌骨肌。"},{"q":"第3～6颈椎的特征不包括","o":["椎体较小","横断面呈椭圆形","有钩椎关节","上、下关节突的关节面呈冠状位","第6颈椎横突末端有颈动脉结节"],"a":3,"e":"第3～6颈椎椎体较小、横断面呈椭圆形，有椎体钩形成的钩椎关节，第6颈椎横突末端有颈动脉结节；其关节突关节面呈水平位，冠状位为胸椎特征。"},{"q":"在骨连结，透明软骨结合包括","o":["骺软骨","前臂骨间膜","耻骨连合","椎间盘","髂骨、坐骨和耻骨合成髋骨"],"a":0,"e":"透明软骨结合见于长骨骨干与骺之间的骺软骨、蝶骨与枕骨的结合，随年龄增长可骨化为骨性结合。前臂骨间膜属纤维连结，耻骨联合和椎间盘为纤维软骨结合。"},{"q":"长骨不包括","o":["腓骨","肋","指骨","掌骨","跖骨"],"a":1,"e":"长骨呈长管状，有骨髓腔，如腓骨、指骨、掌骨和跖骨；肋属扁骨，呈弓形弯曲，内为骨松质，不含骨髓腔。"},{"q":"腰椎的形态结构特征为","o":["横突末端有横突肋凹","椎体横断面呈心形","椎孔似圆形","关节突的关节面几乎呈矢状位","棘突较细长，向后下方倾斜，彼此呈叠瓦状排列"],"a":3,"e":"腰椎椎体粗大，上、下关节突粗大，关节面几乎呈矢状位，限制旋转运动；棘突宽短呈板状水平后伸，椎孔呈卵圆形或三角形。"},{"q":"关于淋巴液的生成，正确的叙述是","o":["来自于组织液的少部分水分和大分子物质","来自于毛细血管静脉端的静脉血","来自于毛细血管","来自于毛细血管动脉端的动脉血","来自于脑脊液"],"a":0,"e":"组织液与细胞交换后约90%经毛细血管静脉端回流入血，约10%的水分和大分子物质进入毛细淋巴管形成淋巴液，故淋巴液来源于组织液。"},{"q":"基底动脉","o":["由左、右椎动脉合成","与小脑腹侧相邻","走行于延髓背侧","穿经枕骨大孔","直接参与构成大脑动脉环"],"a":0,"e":"左、右椎动脉在脑桥与延髓交界处腹侧面汇合成基底动脉，沿脑桥基底沟上行，至脑桥上缘分为左、右大脑后动脉，不直接参与大脑动脉环。"},{"q":"前臂屈肌群中，受正中神经和尺神经双重支配的是","o":["指浅屈肌","旋前圆肌","指深屈肌","尺侧腕屈肌","拇长屈肌"],"a":2,"e":"指深屈肌由正中神经和尺神经共同支配，正中神经支配其桡侧半、尺神经支配尺侧半。指浅屈肌、旋前圆肌和拇长屈肌由正中神经支配，尺侧腕屈肌由尺神经支配。"},{"q":"属上颌动脉分支的血管是","o":["咽升动脉","甲状腺上动脉","舌动脉","面动脉","脑膜中动脉"],"a":4,"e":"脑膜中动脉为上颌动脉的分支，穿棘孔入颅，分布于硬脑膜和颅骨；咽升动脉、甲状腺上动脉、舌动脉和面动脉均直接发自颈外动脉。"},{"q":"损伤后导致对侧损伤平面以下痛觉、温觉丧失的纤维束是","o":["网状脊髓束","脊髓丘脑束","脊髓小脑束","皮质脊髓束","顶盖脊髓束"],"a":1,"e":"脊髓丘脑束经白质前连合交叉至对侧，传导痛温觉和粗触压觉，一侧损伤时对侧损伤平面下1～2个节段以下痛温觉减退或消失。"},{"q":"可使肩关节旋内的肌不包括","o":["胸大肌","背阔肌","大圆肌","小圆肌","肩胛下肌"],"a":3,"e":"小圆肌起自肩胛骨外侧缘上2/3背面，止于肱骨大结节下部，作用是使肩关节旋外；胸大肌、背阔肌、大圆肌和肩胛下肌均能使肩关节旋内。"},{"q":"属于前臂后群深层的肌是","o":["拇收肌","拇短屈肌","拇短展肌","拇对掌肌","拇短伸肌"],"a":4,"e":"前臂后群深层由外上向内下依次为旋后肌、拇长展肌、拇短伸肌、拇长伸肌和示指伸肌；拇收肌、拇短屈肌、拇短展肌和拇对掌肌均属手肌。"},{"q":"关于小腿三头肌的叙述，错误的是","o":["肌腱称为跟腱","止于跟骨","站立时稳定踝关节和膝关节","收缩时背屈踝关节和屈膝关节","分为深、浅层排列"],"a":3,"e":"小腿三头肌由浅层腓肠肌与深层比目鱼肌组成，两肌腱合成跟腱止于跟骨结节，收缩时使踝关节跖屈并屈膝，站立时可固定踝、膝两关节，并非背屈。"},{"q":"产生卵子和分泌女性激素的器官是","o":["子宫","输卵管","卵巢","阴道","前庭大腺"],"a":2,"e":"卵巢是女性生殖腺，既产生卵子又分泌雌激素和孕激素；子宫、输卵管和阴道属生殖管道，前庭大腺为附属腺，均无产生配子和分泌性激素的功能。"},{"q":"后尿道是指","o":["尿道前列腺部","尿道海绵体部、尿道膜部","尿道前列腺部、尿道膜部","海绵体部","膜部"],"a":2,"e":"临床上将尿道前列腺部和膜部合称后尿道，海绵体部称前尿道；后尿道位置固定，骨盆骨折时易受损伤。"},{"q":"男性尿道最狭窄处是","o":["尿道内口","尿道外口","尿道膜部","尿道前列腺部","尿道球部"],"a":1,"e":"男性尿道有三个狭窄，即尿道内口、尿道膜部和尿道外口，其中尿道外口最窄，呈矢状裂隙，结石最易嵌顿于狭窄处。"},{"q":"关于黄斑的描述，正确的是","o":["位于视神经盘的鼻侧约3、5mm稍下方","是感光最敏锐处","由密集的视杆细胞构成","位于视网膜脉络膜部","黄斑中央凹0、5mm范围内有丰富的血液供应"],"a":1,"e":"黄斑位于视神经盘颞侧约3.5mm稍下方，其中央凹无血管，由密集的视锥细胞构成，是感光最敏锐处；视杆细胞主司暗视觉。"},{"q":"下列哪条动脉为腹腔干的三大分支之一","o":["胃左动脉","胃右动脉","肠系膜上动脉","肠系膜下动脉","肝固有动脉"],"a":0,"e":"腹腔干在主动脉裂孔稍下方起自腹主动脉前壁，立即分为胃左动脉、肝总动脉和脾动脉三大分支；胃右动脉发自肝固有动脉，肝固有动脉又属肝总动脉的分支。"},{"q":"甲状旁腺位于","o":["甲状腺的前面","甲状腺的两侧","甲状腺的两层被膜之间","甲状腺的上方","甲状腺的下方"],"a":2,"e":"甲状旁腺常贴附于甲状腺侧叶后缘，位于真被膜与假被膜之间的囊鞘间隙内，也可埋入甲状腺实质或位于甲状腺鞘外，上甲状旁腺位置较恒定。"},{"q":"顶盖前区","o":["位于中脑和间脑的交界部，导水管周围灰质的腹侧","接受外侧丘系的纤维","接受内侧丘系的纤维","发出纤维仅支配同侧的动眼神经副核","发出纤维支配双侧动眼神经副核"],"a":4,"e":"顶盖前区位于中脑与间脑交界处，接受视束经上丘臂来的纤维，发出纤维至双侧动眼神经副核，是瞳孔对光反射通路的重要中继站。"},{"q":"动脉摸脉点","o":["足背动脉在活体上易触摸到搏动的部位是踝关节后方，内、外踝连线的中点","股动脉在活体上易触摸到搏动的部位是其下段","面动脉在活体上易触摸到搏动的部位在咬肌前缘与下颌骨下缘交界处","桡动脉在活体上诊脉的部位是桡动脉中段","颞浅动脉在活体上易触摸到搏动的部位是在外耳门的后方"],"a":2,"e":"面动脉在咬肌止点前缘绕过下颌骨下缘处位置表浅，活体可触及搏动，面部出血可在此压迫止血；足背动脉应在踝关节前方、内踝与外踝连线中点触及。"},{"q":"中枢神经系统内形成髓鞘的细胞","o":["施万细胞","室管膜细胞","小胶质细胞","少突胶质细胞","星形胶质细胞"],"a":3,"e":"中枢神经系统的髓鞘由少突胶质细胞形成，一个少突胶质细胞可包卷多条轴突；施万细胞是周围神经系统的成髓鞘细胞，只形成一条轴突的髓鞘。"},{"q":"肾上腺素由哪个内分泌器官分泌","o":["胰岛","睾丸间质细胞","卵巢","肾上腺皮质","肾上腺髓质"],"a":4,"e":"肾上腺髓质的嗜铬细胞分泌肾上腺素和去甲肾上腺素，前者作用于心肌使心跳加快、收缩力加强；肾上腺皮质分泌盐皮质激素、糖皮质激素和性激素。"},{"q":"关于女性尿道的描述，正确的是","o":["尿道内口周围被横纹肌组成的膀胱括约肌环绕","短而直，穿过尿生殖膈","位于阴道下段的后面","尿道下端有尿道阴道括约肌环绕，不受意识支配","尿道旁腺感染时，可形成囊肿而致尿路阻塞"],"a":1,"e":"女性尿道长约3～5cm，较男性短、宽而直，向前下方穿过尿生殖膈开口于阴道前庭；尿道内口由平滑肌构成的膀胱括约肌环绕，穿尿生殖膈处有横纹肌性尿道阴道括约肌。"},{"q":"颈椎的形态结构特征是","o":["关节面都呈冠状位","横突孔只存在于1～6颈椎","都有棘突","都有一个较小的椎体","第6颈椎横突末端前有颈动脉结节"],"a":4,"e":"第6颈椎横突前结节特别隆起，称颈动脉结节，颈总动脉经其前方，头面部出血时可在此将动脉压向结节止血；寰椎无椎体和棘突，第7颈椎也有横突孔。"},{"q":"下列关于腹膜的描述，错误的是","o":["腹膜是覆盖于腹、盆腔壁内和腹、盆腔脏器表面的黏膜","衬于腹、盆腔壁内的腹膜称为壁腹膜","覆盖于腹、盆腔脏器表面的腹膜称为脏腹膜","壁腹膜和脏腹膜相互延续、移行","腹膜具有分泌、吸收、保护、支持、修复等功能"],"a":0,"e":"腹膜是覆盖于腹、盆腔壁内面和脏器表面的浆膜，分壁腹膜与脏腹膜，二者相互移行延续，具有分泌、吸收、保护、支持和修复功能；其为浆膜而非黏膜。"},{"q":"关于胸神经的叙述，错误的是","o":["上11对前支进入肋间隙","第12对前支为肋下神经","第2对前支分布于乳头平面的皮肤区","第6对前支分布于剑突平面的皮肤区","第7～12对前支下行进入腹内斜肌和腹横肌之间"],"a":2,"e":"胸神经前支的皮支分布有明显节段性，第2胸神经前支分布于胸骨角平面，第4胸神经前支才达乳头平面，第6对平剑突，第10对平脐。"},{"q":"关于鼓室的描述，正确的是","o":["为颞骨乳突部内的含气的小腔","其黏膜与咽鼓管内的黏膜相延续","借咽鼓管与口咽部相通","内侧壁上有锥隆起，内藏镫骨肌","向内可通迷路"],"a":1,"e":"鼓室是颞骨岩部内的含气小腔，其黏膜与咽鼓管黏膜相延续，经咽鼓管通鼻咽部；内侧壁有前庭窗和蜗窗，前庭窗被镫骨底封闭。"},{"q":"使髋关节后伸的肌是","o":["大收肌","髂腰肌","臀大肌","梨状肌","股薄肌"],"a":2,"e":"臀大肌起自髂骨翼外面和骶骨背面，止于髂胫束和股骨臀肌粗隆，是使髋关节后伸和外旋最有力的肌；髂腰肌、大收肌主要屈髋或内收髋。"},{"q":"小腿后群肌包括","o":["趾长屈肌","趾长伸肌","腓骨短肌","胫骨前肌","腓骨长肌"],"a":0,"e":"小腿后群浅层为腓肠肌和比目鱼肌，深层有腘肌、趾长屈肌、胫骨后肌和踇长屈肌；趾长伸肌、胫骨前肌属前群，腓骨长肌、腓骨短肌属外侧群。"},{"q":"喉腔的最狭窄处是","o":["前庭裂","喉中间腔","声门下腔","声门裂","喉口"],"a":3,"e":"声门裂位于两侧声襞与杓状软骨基底部之间，是喉腔最狭窄处，也是喉异物易滞留的部位；前庭裂位于前庭襞之间，较声门裂宽。"},{"q":"三叉神经","o":["含有特殊内脏运动纤维和一般躯体感觉纤维","特殊内脏传出纤维支配面部表情肌","一般躯体传入纤维接受整个头面部的感觉信息","在脑桥下部下缘出脑","传导舌后1/3的黏膜感觉"],"a":0,"e":"三叉神经为混合性脑神经，含特殊内脏运动纤维和一般躯体感觉纤维，前者支配咀嚼肌，后者接受面部、鼻腔和口腔的一般感觉；面部表情肌由面神经支配。"},{"q":"关于左心室流出道位置，哪项正确","o":["位于左心室腔前部","位于左心室腔前外侧部","位于左心室腔前内侧部","位于左心室腔后外侧部","位于左心室腔后内侧部"],"a":2,"e":"左心室以二尖瓣前尖为界分为流入道和流出道，流出道又称主动脉前庭，位于左心室腔的前内侧部，由室间隔上部和二尖瓣前尖围成。"},{"q":"胸骨角向后平对","o":["第2胸椎体下缘","第3胸椎体下缘","第4胸椎体下缘","第5胸椎体下缘","第6胸椎体下缘"],"a":2,"e":"胸骨角由胸骨柄与胸骨体连接处向前突出形成，两侧平对第2肋，向后平对第4胸椎体下缘，是计数肋和椎骨的重要标志。"},{"q":"胸上肢肌包括","o":["肋间内肌、肋间外肌、肋间最内肌","三角肌、大圆肌、小圆肌","胸大肌、胸小肌、前锯肌","胸大肌、胸小肌、肩胛下肌","胸大肌、胸小肌、背阔肌"],"a":2,"e":"胸上肢肌包括胸大肌、胸小肌和前锯肌，均起自胸廓外面、止于上肢带骨或肱骨；肋间肌属胸固有肌，三角肌、大圆肌和小圆肌属上肢带肌。"},{"q":"关于结肠的叙述，错误的是","o":["结肠右曲也称为肝曲","结肠左曲也称为脾曲","乙状结肠好发憩室和恶性肿瘤","降结肠属于腹膜外位器官","横结肠属于腹膜内位器官"],"a":3,"e":"升结肠和降结肠为腹膜间位器官，前面及两侧有腹膜覆盖，后面借结缔组织贴附于腹后壁；横结肠和乙状结肠有系膜，属腹膜内位器官。"},{"q":"面神经中分布于泪腺的纤维的终止核为","o":["疑核","上泌涎核","下泌涎核","面神经核","孤束核"],"a":1,"e":"面神经的一般内脏运动纤维起自上泌涎核，经岩大神经至翼腭神经节换元后支配泪腺，经鼓索和下颌下神经节支配下颌下腺与舌下腺。"},{"q":"关于胸导管的叙述，正确的是","o":["起自左右腰干","经膈的食管裂孔进入胸腔","至第3胸椎高度向左侧斜行","注入左静脉角","引流全身1/4部位的淋巴"],"a":3,"e":"胸导管起自乳糜池，经主动脉裂孔入胸腔，一般至第5胸椎高度斜向左侧，注入左静脉角，收集全身3/4部位的淋巴。"},{"q":"以下关于眼副器的描述，正确的是","o":["包括眼睑、结膜、眼球外肌和眼的血管神经","泪腺的排泄管开口于结膜上穹内侧部","参与屈光调节","对眼球有保护、运动和支持作用","参与房水及泪液的产生"],"a":3,"e":"眼副器包括眼睑、结膜、泪器、眼球外肌以及眶筋膜和眶脂体，对眼球起保护、运动和支持作用，不参与屈光调节，也不产生房水。"},{"q":"新纹状体是指","o":["尾状核和豆状核","豆状核和屏状核","壳和苍白球","尾状核和壳","苍白球和屏状核"],"a":3,"e":"新纹状体由尾状核和壳组成，苍白球称旧纹状体；纹状体属锥体外系重要核团，参与肌张力和随意运动的调节。"},{"q":"下列脑神经中，属于运动性质的是","o":["嗅神经","视神经","三叉神经","展神经","前庭蜗神经"],"a":3,"e":"展神经为纯运动性脑神经，起自展神经核，支配外直肌；嗅神经、视神经和前庭蜗神经属感觉性神经，三叉神经为混合性神经。"},{"q":"下列关于输精管的描述，错误的是","o":["输精管为附睾管的直接延续","长度约50cm，左侧较右侧稍长","输精管以其行程可分为4部","输精管精索部为最长段","输精管盆部近末端膨大形成输精管壶腹"],"a":3,"e":"输精管依行程分睾丸部、精索部、腹股沟管部和盆部四部，其中盆部最长，精索部最短且位置表浅，是输精管结扎的常选部位。"},{"q":"与端脑相连的脑神经是","o":["动眼神经","嗅神经","滑车神经","视神经","三叉神经"],"a":1,"e":"嗅神经由嗅黏膜内嗅细胞的周围突汇集而成，穿筛孔入颅连于端脑的嗅球，是唯一与端脑相连的脑神经；视神经连于间脑。"},{"q":"缰三角属于","o":["上丘脑","下丘脑","后丘脑","底丘脑","背侧丘脑"],"a":0,"e":"缰三角位于第三脑室顶，由缰核和缰连合构成，属上丘脑；下丘脑位于下丘脑沟以下，后丘脑为内侧膝状体和外侧膝状体。"},{"q":"桡侧近侧关节属于","o":["屈戌关节","车轴关节","椭圆关节","鞍状关节","球窝关节"],"a":1,"e":"桡尺近侧关节由桡骨头环状关节面与尺骨桡切迹构成，属车轴关节，与桡尺远侧关节联合完成前臂旋前和旋后运动。"},{"q":"管理小指皮肤感觉的神经是","o":["正中神经","桡神经","尺神经","腋神经","肌皮神经"],"a":2,"e":"尺神经经腕尺管入手掌，发掌浅支和掌深支，发出指掌侧固有神经分布于小指及环指尺侧半皮肤；正中神经分布至桡侧三个半指掌面。"},{"q":"分布于半球内侧面顶枕沟以前大脑皮质的动脉是","o":["大脑中动脉","大脑前动脉","大脑后动脉","前交通动脉","基底动脉"],"a":1,"e":"大脑前动脉自颈内动脉发出后沿胼胝体沟后行，分布于半球内侧面顶枕沟以前的部分及额、顶叶外侧面上缘，供应额叶和顶叶内侧部皮质。"},{"q":"视觉中枢位于","o":["枕叶距状沟两侧皮质","外侧膝状体","顶盖前区","中脑上丘","角回"],"a":0,"e":"视觉中枢位于枕叶内侧面距状沟上、下方的皮质，接受外侧膝状体发出的视辐射纤维，一侧损伤可致对侧视野同向性偏盲。"},{"q":"前锯肌的滋养动脉是","o":["肋间后动脉","旋肩胛动脉","胸背动脉","胸外侧动脉","胸廓内动脉"],"a":3,"e":"胸外侧动脉伴胸长神经沿胸侧壁下行，分布于前锯肌、胸大肌和胸小肌，是前锯肌的主要滋养动脉；胸背动脉主要供应背阔肌。"},{"q":"齿状韧带形成于","o":["硬脊膜","硬脑膜","蛛网膜","软脊膜","软脑膜"],"a":3,"e":"齿状韧带由软脊膜在脊髓两侧向外突出形成，其尖端附着于硬脊膜，将脊髓悬吊固定于椎管内，起保护作用。"},{"q":"皮质脊髓束主要传导","o":["支配同侧上下肢骨骼肌的随意运动","支配对侧上下肢骨骼肌的随意运动","支配同侧躯干四肢骨骼肌的随意运动","支配对侧躯干四肢骨骼肌的随意运动","支配双侧躯干四肢骨骼肌的随意运动"],"a":1,"e":"皮质脊髓束起自大脑皮质运动区，经内囊、大脑脚和锥体交叉下行至脊髓前角；支配上、下肢的前角运动神经元只接受对侧皮质信息，躯干肌则受双侧支配。"},{"q":"踝部作静脉输液时，最佳的静脉是","o":["胫前静脉","穿静脉","小隐静脉","足背静脉弓","大隐静脉"],"a":4,"e":"大隐静脉起自足背静脉弓内侧端，经内踝前方沿小腿内侧上行，位置表浅恒定，是踝部及下肢静脉输液和静脉切开的常用血管。"},{"q":"薄束描述错误的是","o":["成自第5胸节以下的脊神经节细胞的中枢突","T5以下占据脊髓后索全部","主要传导同侧下肢的深感觉和精细触觉","上行至同侧薄束核内交换神经元","上行至对侧薄束核内交换神经元"],"a":4,"e":"薄束由第5胸节以下脊神经节细胞的中枢突组成，在脊髓后索内上行止于同侧薄束核换元，传导同侧下肢的深感觉和精细触觉，并不越边至对侧。"},{"q":"输卵管常用结扎部位在","o":["输卵管子宫部","输卵管漏斗","输卵管壶腹","输卵管峡","输卵管伞"],"a":3,"e":"输卵管峡短而细，管壁较厚，位置较固定，是输卵管结扎术的常选部位；壶腹部为受精的常见部位。"},{"q":"关于正中神经正确的是","o":["发自臂丛后束","发出分支支配臂前群肌","发出分支支配除拇收肌以外的鱼际肌","损伤后影响小指功能，不能屈曲","损伤后可出现“爪形手”"],"a":2,"e":"正中神经发自臂丛内、外侧束，其返支支配除拇收肌以外的鱼际肌，并支配前臂前群大部及桡侧三个半指；损伤后呈“猿手”，爪形手为尺神经损伤表现。"},{"q":"关节腔的特征不包括","o":["由关节囊滑膜层围成","是滑膜关节的基本结构","含少量滑液","关节腔内呈负压","是密闭腔隙"],"a":0,"e":"关节腔由关节囊滑膜层与关节面共同围成，是滑膜关节的基本结构之一，腔内含少量滑液并呈负压，为密闭腔隙，并非仅由滑膜层围成。"},{"q":"关于男性尿道弯曲的叙述，错误的是","o":["耻骨前弯在耻骨联合的前下方，凸向上","耻骨下弯位于耻骨联合的下方","耻骨前弯是阴茎体与阴茎根之间的弯曲","向上牵拉阴茎时，耻骨前弯可消失","耻骨下弯是由尿道海绵体部构成"],"a":4,"e":"耻骨下弯位于耻骨联合下方约2cm，由尿道前列腺部、膜部和海绵体部起始段构成，凸向下后方且恒定；耻骨前弯位于耻骨联合前下方，上提阴茎可消失。"},{"q":"肝的韧带中，不属于腹膜形成的是","o":["镰状韧带","冠状韧带","左三角韧带","右三角韧带","肝圆韧带"],"a":4,"e":"肝圆韧带是胎儿脐静脉闭锁后的遗迹，位于镰状韧带游离缘内，由结缔组织构成；镰状韧带、冠状韧带及左、右三角韧带均由腹膜形成。"},{"q":"支配舌的神经不包括","o":["舌神经","面神经","舌咽神经","迷走神经","舌下神经"],"a":3,"e":"舌前2/3的一般感觉由舌神经传导，后1/3由舌咽神经传导，味觉分别由面神经和舌咽神经管理，运动由舌下神经支配，迷走神经不分布于舌。"},{"q":"在上肢带骨连结，有防止肱骨头向上脱位的结构是","o":["肩锁韧带","喙肱韧带","喙肩弓","喙锁韧带","肋锁韧带"],"a":2,"e":"喙肩弓由喙突、肩峰及二者间的喙肩韧带构成，位于肩关节上方，可防止肱骨头向上脱位；喙肱韧带主要限制肱骨外旋。"},{"q":"肱骨中下1/3骨折，最易发生的并发症是","o":["肱动脉损伤","正中神经损伤","尺神经损伤","桡神经损伤","肱二头肌断裂伤"],"a":3,"e":"肱骨中下1/3交界处后方的桡神经沟内有桡神经紧贴骨面走行，骨折时易损伤桡神经而出现垂腕；肱动脉损伤多见于肱骨髁上骨折。"},{"q":"相邻椎骨的上、下切迹共同围成","o":["椎间孔","椎孔","横突孔","骶前孔","骶后孔"],"a":0,"e":"相邻两椎骨的上切迹与下切迹相对，共同围成椎间孔，有脊神经和血管通过；椎孔由椎体后面与椎弓围成，容纳脊髓。"},{"q":"位于外侧沟前支和升支之间的脑区","o":["额下回眶部","额下回三角部","额下回岛盖部","缘上回","角回"],"a":1,"e":"额下回被外侧沟的前支和升支分为眶部、三角部和岛盖部，三角部位于前支与升支之间，岛盖部位于升支之后，与运动性语言中枢关系密切。"},{"q":"胎儿肺不同于幼儿肺，如何区分","o":["胎儿肺不含空气","胎儿肺比重较小","胎儿肺能浮出水面","胎儿肺无营养血管","胎儿肺无气道相连"],"a":0,"e":"胎儿肺未经呼吸，肺泡内不含空气而含液体，比重较大，投入水中下沉；出生呼吸后肺内充气，比重小于水而浮起。"},{"q":"对迷走神经的叙述，错误的是","o":["经颈静脉孔出颅","在橄榄后沟连于延髓","内含4种纤维成分","特殊内脏纤维来自疑核","一般内脏运动纤维分布于喉肌"],"a":4,"e":"迷走神经的一般内脏运动纤维支配胸腹腔脏器、心脏和腺体；喉肌则由疑核发出的特殊内脏运动纤维经喉返神经支配。"},{"q":"经卵圆孔出颅的神经是","o":["面神经","舌下神经","上颌神经","下颌神经","舌咽神经"],"a":3,"e":"下颌神经为三叉神经第三支，经卵圆孔出颅，属混合性神经；上颌神经经圆孔出颅，面神经经茎乳孔出颅，舌下神经经舌下神经管出颅。"},{"q":"左、右主支气管不同，其区别在于","o":["右主支气管与食管第2狭窄相邻","右主支气管比左主支气管外径小","右主支气管比左主支气管短","右侧嵴下角大","右主支气管不含软骨环"],"a":2,"e":"右主支气管短、粗、陡直，与气管中线夹角小，左主支气管细长而倾斜，故异物和坠积物易进入右主支气管。"},{"q":"乳房","o":["位于浅筋膜深面","乳腺叶有8～10个","每个乳腺叶有多条排泄管","输乳管以乳头为中心，呈放射状排列","乳房悬韧带对乳房无固定作用"],"a":3,"e":"输乳管以乳头为中心呈放射状排列，乳腺脓肿切开引流宜作放射状切口以减少乳管损伤；乳腺叶有15～20个，每叶有一条输乳管。"},{"q":"寰椎是","o":["第1颈椎","第2颈椎","第7颈椎","胸椎","腰椎"],"a":0,"e":"寰椎即第1颈椎，无椎体和棘突，由前弓、后弓和两侧块构成，与枕骨髁构成寰枕关节，其横突孔有椎动脉通过。"},{"q":"关于躯干四肢痛温觉和粗触觉传导通路的叙述，错误的是","o":["第1级神经元为脊神经节细胞","脊髓丘脑侧束传导痛温觉","脊髓丘脑前束传导粗触觉","丘脑中央辐射传导痛温觉和粗触觉","在脊髓内，来自颈、胸、腰和骶部的纤维自外向内依次在脊髓丘脑束排列"],"a":4,"e":"脊髓丘脑束内纤维由内向外依次排列为颈、胸、腰、骶部来源，即骶部纤维位于最外侧、颈部最内侧，故自外向内依次排列的表述错误。"},{"q":"淋巴器官包括下述哪个结构","o":["肝脏","胸腺","胰脏","孤立淋巴小结","淋巴滤泡"],"a":1,"e":"淋巴器官包括胸腺、脾、淋巴结和扁桃体，胸腺为中枢淋巴器官，培育T淋巴细胞；肝和胰属消化腺，淋巴小结属淋巴组织。"},{"q":"不存在明显的瓣膜纤维环的是","o":["主动脉口","肺动脉口","冠状窦口","左房室口","右房室口"],"a":2,"e":"冠状窦口无瓣膜纤维环，是冠状窦注入右心房的开口；主动脉口、肺动脉口及左、右房室口周围均有致密结缔组织构成的纤维环。"},{"q":"下列结构中不属于泪器","o":["泪腺","泪湖","泪小管","泪囊","鼻泪管"],"a":1,"e":"泪器由泪腺和泪道组成，泪道包括泪点、泪小管、泪囊和鼻泪管；泪湖是泪液积聚于眼内眦处的间隙，不属泪器结构。"},{"q":"脊髓前角运动神经元","o":["位于Ⅹ层","包括大型的运动神经元和小型的运动神经元","α动神经元支配梭内肌","γ运动神经元支配梭外肌","反馈抑制Renshaw细胞"],"a":1,"e":"脊髓前角位于灰质Ⅸ层，含大型α-运动神经元和小型γ-运动神经元，前者支配梭外肌，后者支配梭内肌；Renshaw细胞对α-运动神经元起抑制作用。"},{"q":"感受头部变速旋转刺激的是","o":["蜗管","螺旋器","壶腹嵴","球囊斑和椭圆囊斑","内淋巴"],"a":2,"e":"壶腹嵴位于膜半规管壶腹内，感受头部旋转变速运动的刺激；球囊斑和椭圆囊斑感受直线变速运动及头部位置变化，螺旋器感受声波。"}];
